COLLDATA("asabahur","ur",[[7824,"§۹۲۱۳ ۔ یاسر\nابو الرداء البلوی مولا رداء بنت عمرو بن عمارہ بن عطیہ البکری۔ ابن یونس کا قول ہے: فتح مصر میں شریک ہوئے اور صحابی ہیں۔ مصر میں ان کی اولاد ہے پھر بطریق سعید بن عفیر روایت کی ہے کہ ابو الرداء یاسر بلی کی ایک خاتون کے غلام تھے ان کا کہنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کے پاس سے گزرے، اس وقت وہ اپنی مالکن کی بکریاں چرا رہے تھے جن میں ان کی دو بکریاں تھیں۔ نبی کریم صلی اللہ علیہ وسلم نے ان سے (پانی) مشروب طلب فرمایا تو انہوں نے اپنی دو بکریاں دوہیں، پھر واپس لائے تو وہ پھر سے دودھ سے بھر گئیں۔ انہوں نے اپنی مالکن کو بتایا تو اس نے انہیں آزاد کر دیا۔ انہوں نے ابو الرداء کنیت رکھی۔ ابو بشر دولابی اور ابن مندہ نے بحوالہ ابو سلیمان مولیٰ ام سلمہ رضی اللہ عنہا روایت کی ہے کہ ابو الرداء نے ان سے بیان کیا کہ ان میں سے کسی شخص نے شراب پی لی جسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لائے تو آپ صلی اللہ علیہ وسلم نے اسے کوڑے لگوائے، اس نے دوسری بار پھر پی لی، پھر اسے لایا گیا تو پھر کوڑے لگوائے۔ اس نے تیسری بار بھی اس سے منہ لگا لیا۔ مجھے معلوم نہیں تیسری یا چوتھی بار کیا ہوا۔ آپ نے اس کے بارے میں حکم دیا تو اسے کنوئیں کی بلی پر رکھا گیا تو اس کی گردن اتار دی گئی۔\nدولابی نے یہ نام میم اور دال سے لکھا ہے، عبد الغنی فرماتے ہیں: یہ لفظی غلطی ہے، یہ نام تو باء اور ذال نقطہ دار سے ہے۔\nمیں کہتا ہوں: بغوی نے \"الکنی\" میں میم اور دال سے لکھا ہے۔ فرماتے ہیں: مصر کے رہائشی تھے پھر بطریق ابن لہیعہ ان کی حدیث نقل کی، اس کے سیاق میں فرماتے ہیں: عن ابی سلمان یہ ایک روایت میں ہے جبکہ دوسری میں ہے: عن ابی سلمان۔ متن میں فرماتے ہیں: پھر اسے جہاں تک میرا خیال ہے تیسری یا چوتھی بار لایا گیا، آپ نے اس کے بارے میں حکم دیا تو اسے کنوئیں کی لکڑی پر رکھا گیا اور اس کی گردن قلم کی گئی۔"],[7825,"§۹۲۱۴ ۔ یامین بن عمیر\n(1) ابن کعب ابو کعب النضیر کی۔ ابو عمر نے ان کا ذکر کیا ہے کہ اکابر صحابہ رضی اللہ عنہم میں سے ہیں۔ اسلام لائے تو ان کا مال محفوظ ہو گیا۔ بنی نضیر میں سے ان کے اور ابو سعید بن عمرو بن وہب کے علاوہ کسی کا مال محفوظ نہ رہا۔ یہ بات ابن اسحاق نے عن عبداللہ بن ابی بکر بن محمد بن عمرو بن حزم سے نقل کی ہے۔ ابن اسحاق ہی فرماتے ہیں: مجھے معلوم ہوا کہ یامین بن کعب، ابو لیلیٰ عبد الرحمن بن کعب اور عبداللہ بن مغفل سے ملے تو وہ دونوں رو رہے تھے، پوچھا تو انہوں نے بتایا: ہمیں نبی کریم صلی اللہ علیہ وسلم کے پاس سواری کا کوئی جانور نہیں ملا، تو انہوں نے ان دونوں کو ایک آب بردار اونٹ دیا۔ ابن اسحاق کا قول ہے:(2) آل یامین کے کسی شخص نے مجھے بتایا کہ نبی کریم صلی اللہ علیہ وسلم نے یامین سے فرمایا: تم نے اپنے چچا زاد\nعمرو بن جحاش کو دیکھا نہیں اور جو اس نے میرے قتل کا ارادہ کیا تھا، یعنی واقعہ بنی نضیر میں، اس نے آپ پہ چکی کا پاٹ گرا کر آپ کو قتل کرنا چاہا تھا، تو جبرائیل علیہ السلام نے آپ کو آگاہ کر دیا۔ آپ اپنی جگہ سے اٹھ گئے تو یامین نے ایک شخص کو عمرو بن جحاش کے قتل کے لیے انعام دے کر تیار کر لیا جس نے اسے موت کے گھاٹ اتار دیا۔","",{"fn":"(1) اسد الغابہ (۵۴۹۷)\n(2) السیرۃ النبویۃ (۱۲۷/۴)"}],[7826,"§۹۲۱۵ ۔ یامین بن یامین اسرائیلی(3)\nابن فتحون نے استیعاب پر اپنے \"ذیل\" میں ان کا ذکر کیا ہے، بحوالہ ماوردی نقل کیا ہے کہ جب عبداللہ بن سلام اسلام لے آئے تو یامین بن یامین نے کہا: میں بھی ایسی گواہی دیتا ہوں جیسی عبداللہ نے دی۔ جس پر یہ آیت نازل ہوئی۔ \"بنی اسرائیل میں سے ایک شخص نے اس کی گواہی جیسی گواہی دی\"(1) سلمہ بن سلام کے حالات میں بھی ان کا ذکر آتا ہے۔ اللہ تعالیٰ کا یہ ارشاد بھی ان کے بارے میں نازل ہوا ہے \"اے وہ لوگو! جو (موسیٰ پر) ایمان لائے اللہ اور اس کے رسول (محمد صلی اللہ علیہ وسلم) پر ایمان لاؤ\"(2) بروایت ابن کلبی عن ابی صالح عن ابن عباس سعد بن شعبہ کے بارے میں ہے۔","",{"fn":"(1) سورۃ الاحقاف: ۱۰\n(2) سورۃ النساء: ۱۳۶\n(3) اسد الغابہ (۵۴۹۸) تجرید (۱۳۲/۲)"}],[7827,"§۹۲۱۶ ۔ یثربی البلوی\nابو رمثہ کے والد جن کا نام رفاعہ بن یثربی ہے۔ طبرانی نے ان کا ذکر کیا ہے ابو داؤد اور طبرانی نے بطریق سفیان ثوری عن زیاد بن لقیط السد وسی روایت کی ہے کہ میں نے ابو رمثہ کو فرماتے سنا: میں اپنے والد کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس آیا، آپ نے پوچھا: کیا یہ تمہارا بیٹا ہے؟ انہوں نے عرض کی: ہاں جی فرمایا: کیا اس سے محبت کرتے ہو؟ لیکن یاد رکھنا اس کے جرم کے تم اور تمہارے بیٹے کا یہ ذمہ دار نہیں۔(1)","",{"fn":"(1) مسند احمد (۲۲۹/۲) المعجم الکبیر (۷۱۳/۲۲) مشکاۃ المصابیح (۳۴۷۱)"}],[7828,"§۹۲۱۷ ۔ یحموم الکندی\nمولیٰ اشعث بن قیس۔ اشعث جب اسلام لائے تو ان کے ساتھ تھے رشاطی بواسطہ ھمدانی نسب یمن میں شعمی سے بحوالہ قریش ایک شخص سے نقل کیا ہے کہ ہم لوگ مسجد نبوی کے دروازے پر کھڑے تھے اچانک کندہ کا وفد آ گیا لوگ جھانک کر دیکھنے لگے۔ فرماتے ہیں: مجھ سے ان سے بہتر وضع قطع والا کوئی نظر نہیں آیا۔ جب ان میں سے درمیانے قد والا شخص داخل ہوا جس کے بال کندھوں تک گر رہے تھے تو میں نے پوچھا: یہ کون ہے؟ لوگوں نے کہا: اشعث بن قیس۔ میں نے کہا: اشعث اللہ کا شکر ہے جس نے اپنے دین کی مدد کی اپنے نبی کو غلبہ عطا کیا اور نہ چاہتے ہوئے بھی تمہیں اور تمہاری قوم کو اس دین میں داخل کر دیا۔\nاتنا ہی کہا تھا کہ ایک سیاہ فام غلام مجھ پہ لپک پڑا جسے سموم کہا جاتا تھا۔ اس نے قسم کھائی کہ ضرور مجھے مار دے گا۔ لیکن درمیان میں چند لوگ آ گئے اور انصار کی ایک جماعت بھڑک اٹھی۔ اشعث نے چیخ کر کہا: رک جاؤ تو وہ مصیبت میرے سر سے ٹلی۔ پھر اشعث نے مجھ سے ملاقات کرنا چاہی تو وہ نوجوان مجھے دے دیا ساتھ میں کچھ چاندی اور چند بکریاں تھیں میں نے یہ اشیاء قبول کر لیں البتہ وہ غلام واپس کر دیا، پھر یہ لوگ کچھ ایام مدینہ منورہ میں رہے اونٹ کا نحر کر کے لوگوں کو گوشت کھلاتے رہے۔"],[7829,"§۹۲۱۸ ۔ یحنس النبال\n(1) ابن اسحاق(2) نے طائف میں سے محاصرے کے دوران نبی کریم صلی اللہ علیہ وسلم کے پاس آ جانے والوں میں ان کا ذکر کیا ہے اسلام لے آئے بعد میں ان کا آقا بھی مسلمان ہو گیا تو آپ نے ان کا ولاء اسے دے دیا وہ ثقیف میں سے آل سیار بن مالک کے غلام تھے۔ واقدی کا بیان ہے یہ خود سیار بن مالک کے غلام تھے۔","",{"fn":"(1) اسد الغابہ (۵۴۹۹) تجرید (۱۳۲/۲)\n(2) السیرۃ النبویۃ (۱۰۱/۴)"}],[7830,"§۹۲۱۹ ۔ یحنس بن وبرہ الازدی\n(1) اموی نے بحوالہ ابن کلبی ان کا ذکر کیا ہے کہ یہ ان لوگوں میں سے تھے جنہوں نے اسود کی بیوی کے ساتھ مل کر جو ان کی رشتہ دار تھی۔ ان کے قتل کی چال چلی تھی۔ وبرہ بن تکنس کا تذکرہ ہو چکا ہے شاید یہ ان کے بیٹے ہیں یا نام الٹ گیا ہے۔ ابن فتحون نے ذیل میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۰) تجرید (۱۳۲/۲)"}],[7831,"§۹۲۲۰ ۔ یحییٰ بن اسعد بن زراہ انصاری\n(1) ان کے والد ہجرت کے پہلے سال فوت ہو گئے تھے بقول ابن حبان: صحابی ہیں، ابن مندہ: صحابی ہونے میں اختلاف ہے۔ جبکہ ابن ابی عاصم(2) اور بغوی وغیرہ نے صحابہ میں ان کا ذکر کیا ہے سب نے بطریق محمد بن عبدالرحمن بن اسعد بن زرارہ روایت کی ہے ہم میں سے جو شخص بھی نبی کریم صلی اللہ علیہ وسلم کے حوالے سے بیان کرتا ہے کہ آپ نے اسعد بن زرارہ کو داغ لگایا تھا۔۔۔۔ الحدیث","",{"fn":"(1) اسد الغابہ (۵۵۰۱) تجرید (۱۳۲/۲)\n(2) الاحاد المثانی (۲۱۹۷)"}],[7832,"§۹۲۲۱ ۔ یحییٰ بن اسد\n(1) ابن حضیر انصاری ابن القداح نے ان کا ذکر کیا ہے کہ اپنے والد کے ہمراہ حدیبیہ میں شریک ہوئے۔ ابو عمر(2) لکھتے ہیں: یاد رکھنے کی عمر میں تھے لیکن مجھے ان کی کسی روایت کا علم نہیں۔ ان کے والد انہی کے نام سے کنیت رکھتے تھے صحیح مسلم میں بطریق عبداللہ ابن حبان عن ابی سعید الخدری ان کا ذکر ثابت ہے کہ اسید بن حضیر ایک دفعہ قرآن پڑھ رہے تھے کہ اچانک ان کا گھوڑا کودنے لگا فرماتے ہیں: مجھے خدشہ ہوا کہیں بیٹی کو نہ کچل دے۔ یعنی ان کے بیٹے کو۔","",{"fn":"(1) اسد الغابہ (۵۵۰۲) استیعاب (۲۷۷۷)\n(2) استیعاب (۱۲۹/۴)"}],[7833,"§۹۲۲۲ ۔ یحییٰ بن حکیم\n(1) ابن حرام قرشی اسدی ابن عبدالبر(2) نے ان کا ذکر کیا ہے کہ حکیم بن حزام اور ان کے بیٹے ہشام، خالد یحییٰ اور عبیداللہ فتح مکہ کے موقع پر اسلام لائے اور شرف صحابیت سے سرفراز ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۳) استیعاب (۲۷۷۸) تجرید: ( )\n(2) استیعاب (۱۲۹/۴)"}],[7834,"§۹۲۲۳ ۔ یحییٰ بن الحنظلیہ\n(1) بقول ابن مندہ: مغازی میں ان کا ذکر ملتا ہے۔ بغوی نے صحابہ میں ان کا ذکر کیا ہے اور بطریق یزید بن ابی مریم عن ابیہ بحوالہ یحییٰ ابن الحنظلیہ۔ جنہیں بیعت رضوان میں شرکت کی سعادت حاصل ہے۔ روایت کی کہ ان کی اولاد نہیں ہوئی تھی، وہ کہنے لگے: اس ذات کی قسم! جس کے دست قدرت میں میری جان ہے اگر اسلام میں میرا بیٹا پیدا ہوا جس کی وجہ سے میں ثواب(2) کی امید رکھوں مجھے دنیا اور اس کی چیز سے زیادہ محبوب ہے۔ اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۴) تجرید (۱۳۳/۲)\n(2) اسد الغابہ (۳۲۷/۴) تجرید (۱۳۲/۲)"}],[7835,"§۹۲۲۴ ۔ یحییٰ بن سعد بن زراہ انصاری\n(1) ابن مندہ نے ان کے چچا اسعد بن زرارہ کے حالات میں ان کا تذکرہ کیا ہے اور بطریق بشر ان کے چچا زاد عن شعبہ عن محمد ابن عبدالرحمن بن اسعد بن زرارہ عن عمہ یحییٰ بن سعد روایت کی ہے کہ میں نے اپنے چچا اسعد بن زرارہ (جو محمد بن عبدالرحمن کے نانا ہیں) کو فرماتے سنا کہ انہیں حلق میں ذبحہ نامی بیماری ہوئی (جس سے حلق (گلے) میں درد رہتا ہے)۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں ابو امامہ کی طرف سے معذور ہو کر رہوں گا\"۔ پھر ایک نے انہیں اپنے ہاتھ سے(2) داغا۔۔۔۔ (حدیث)\nمیں کہتا ہوں: سیدنا اسعد کی وفات ہجرت کے پہلے سال ہوئی تو جب یحییٰ اس عمر میں ہوں کہ ان سے سماع کر رہے ہوں تو پھر وہ لامحالہ صحابی ہوئے، لیکن مسدد نے اپنی مسند میں عن یحییٰ القطان عن شعبہ عن محمد بن عبدالرحمن انہوں نے اپنے چچا یحییٰ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسعد کو داغ لگایا۔۔۔۔ (حدیث) اس میں یہ نہیں کہا کہ میں نے اسعد کو فرماتے سنا۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۵۰۸) تجرید (۱۳۳/۲)\n(2) ابن ماجہ کتاب الطب باب من اکتوی (۳۴۹۲)"}],[7836,"§۹۲۲۵ ۔ یحییٰ بن عبدالرحمن الانصاری\n(1) ابو موسیٰ نے \"الذیل\" میں ان کا ذکر کیا ہے اور بطریق ہشام بن حسان عن محمد بن عبدالرحمن عن یحییٰ بن عبدالرحمن الانصاری روایت کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے علی سے زندگی اور موت کی حالت میں محبت کی اس کے لیے امن و امان لکھ دیا جائے گا\"۔۔۔۔ (حدیث)(2) اس سند میں احمد بن محمد خلیل کا غلام ہے جو حدیثیں گھڑنے میں مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۹) تجرید (۱۳۳/۲)\n(2) جامع المسانید والسنن (۴۱۰/۱۲)"}],[7837,"§۹۲۲۶ ۔ یحییٰ بن عمیر\n(1) ابن حارث بن زائدہ بن کندہ بن ثعلبہ بن حارث انصاری۔ ابن حبان لکھتے ہیں: شرف صحابیت سے مشرف ہیں، ان کے والد کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۳) تجرید (۱۳۳/۲)"}],[7838,"§۹۲۲۷ ۔ یحییٰ بن نفیر\nبقول بعض نفیر۔ یہ تاریخ حمص کے مصنف کا قول ہے۔ پہلا قول ابن ابی حاتم نے کسی سے نقل کیا ہے اور یہ ابو زہیر نمیری کا نام ہے۔ لکھتے ہیں: میرے والد اس کے بارے نابلد ہیں۔ بقول بعض ان کا نام فلاں بن شرحبیل ہے کنیت سے مشہور ہیں کنیتوں میں (ت ۹۹۳۷) میں تذکرہ ہونا ہے۔"],[7839,"§۹۲۲۸ ۔ یربوع بن عمرو\nابن کعب بن عبس بن حرام بن حبیب بن عامر بن غنم بن عدی بن النجار۔ عدوی اور طبری کا بیان ہے: اُحد اور بعد کے معرکوں میں شریک ہوئے۔ ان کی اولاد نہیں۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[7840,"§۹۲۲۹ ۔ یربوع (الجعد کے والد)\n(1) بقول ابن مندہ: ان سے ان کا بیٹا الجعد ایک منکر حدیث بروایت عبداللہ بن محمد یعنی بلوی(2) روایت کرتا ہے۔","",{"fn":"(1) جامع المسانید والسنن (۴۱۱/۱۲) اسد الغابہ (۳۲۹/۴)\n(2) کتاب السنۃ (۳۶۲/۱) الترغیب والترھیب (۴۱۸/۴)"}],[7841,"§۹۲۳۰ ۔ یزید بن الاخنس السلمی\n(1) ان کا تذکرہ ان کے والد کے حالات میں ہوا ہے، اور کنیتوں میں ابو الاعور السلمی کے سوانح میں ان کا ذکر ہے۔ طبرانی کی بطریق بقیہ بحوالہ یزید بن الاخنس روایت ہے کہ جب یہ مسلمان ہوئے تو سوائے ایک خاتون کے ان کے تمام اہل خانہ اسلام لے آئے۔ جس پر اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم پر یہ آیت نازل فرمائی: \"اور تمہیں بھی کافر عورتیں روک رکھنے کی ضرورت نہیں۔\"(2) حدیث ابی امامہ میں بھی ان کا ذکر ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے مجھ سے وعدہ فرمایا ہے کہ میری اُمت کے ستر ہزار افراد بغیر حساب جنت میں داخل فرمائے گا\"۔(3) تو یزید بن الاخنس کہتے ہیں: اللہ کے رسول! اتنے لوگ! تو آپ کی اُمت میں ایسے ہیں جیسے مکھیوں میں سرخ لکھی اور ایک روایت میں ہے جیسے نیلی لکھی۔ اسے امام احمد رحمہ اللہ نے نقل کیا ہے اور سند صحیح ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۵) استیعاب (۲۷۸۰)\n(2) سورۃ الممتحنہ (۱۰)\n(3) مسند احمد (۲۵۰/۵) المعجم الکبیر (۱۵۵/۸) کنز العمال (۳۲۱۰۲) البدایۃ والنہایۃ (۸۲/۲)"}],[7842,"§۹۲۳۱ ۔ یزید بن اسد بن کرز البجلی\n(1) امیر خالد بن عبداللہ القسری کے دادا۔ ابن سعد(2) نے صحابہ رضی اللہ عنہم کے طبقہ چہارم میں ان کا ذکر کیا ہے۔ لکھتے ہیں: نبی کریم صلی اللہ علیہ وسلم کے پاس آنے والوں میں سے ہیں۔ امام بخاری رحمہ اللہ(3) لکھتے ہیں: نبی کریم صلی اللہ علیہ وسلم سے سماع کیا ہے۔ ابو حاتم الرازی، ابو عبداللہ المقدمی اور ابن حبان کا قول ہے: صحابی ہیں۔ ان کے والد اسد کا تذکرہ حرف الف میں ہو چکا ہے۔ اور ہم نے مسند عبد بن حمید میں بطریق سیار بن ابی الحکم عن خالد بن عبداللہ القسری عن ابیہ عن جدہ روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"یزید بن اسد! جو چیز تم اپنے لیے پسند کرتے ہو وہی (بھلائی کی بات) دوسروں کے لیے پسند کرو\"۔(4) حاکم نے اسے صحیح لکھا ہے۔ یحییٰ بن معین لکھتے ہیں:\nخالد کے گھرانے کے لوگ خالد کے دادا کے صحابی ہونے کا انکار کرتے ہیں، ہشام بن عبد الملک خالد کو ولایت ملنے پر احسان جتلانے کے لیے طویل خط لکھتا ہے، اس میں ہے: یہ تمہارے دادا یزید بن اسد ہی تھے جو صفین میں امیر معاویہ کے ساتھ تھے۔ انہوں نے اپنے خون اور دیت کو ان کے لیے آڑ بنا دیا تھا۔ تو انہوں نے ان سے کیسا برتاؤ کیا۔ اور جو امیر المومنین نے تم سے سلوک کیا ہے اس کے وہ قریب نہ تھے۔\nابو الفرج اصبہانی لکھتے ہیں: یزید بن اسد دور فاروقی میں مسلمانوں کی جماعتوں میں شام گئے اور وہیں رہنے لگے، اہل یمن میں ہر دلعزیز اور صاحب حیثیت تھے۔ امیر معاویہ رضی اللہ عنہ نے انہیں چار ہزار کی نفری میں سیدنا عثمان رضی اللہ عنہ کی حمایت و نصرت کے لیے روانہ کیا تھا۔ جب یہ مدینہ پہنچے تو سیدنا عثمان رضی اللہ عنہ شہادت سے سرفراز ہو چکے تھے۔ انہوں نے کچھ کیے بغیر واپسی کر لی۔ صفین میں امیر معاویہ رضی اللہ عنہ کے ساتھ تھے عبداللہ بن یزید کو اپنے والد کی طرح شرافت و سمجھ حاصل نہیں تھی۔ مبرد لکھتے ہیں: عبداللہ بن یزید معتبر لوگوں میں عقلمند مردوں میں سے تھے۔ عبدالملک بن مروان نے ان سے کہا: تمہارا کیا کتنا مال ہے؟ انہوں نے کہا: دو چیزیں ہیں کہ مجھے ان کے ساتھ ان لوگوں کی کوئی محتاجی نہیں۔ اللہ تعالیٰ (کی تقدیر) پر راضی رہنا اور لوگوں سے بے نیازی۔ ابن حبان نے عبداللہ بن یزید کو ثقات میں شمار کیا ہے۔\nابن سعد(5) لکھتے ہیں: یزید بن الاسود (اسد) نہ کونہ فروکش ہوئے اور نہ انہیں کوئی حکومتی رقبہ ملا۔ وہاں تو خالد نے علاقہ لیا تھا۔ ابن المبارک کتاب الزہد میں فرماتے ہیں: ہمیں ابو بکر بن عیاش نے بتایا کہ عبداللہ بن یزید بن اسد امیر معاویہ کے پاس ان کی اس بیماری میں عیادت کے لیے حاضر ہوئے جس سے ان کی وفات ہوئی، دیکھا کہ وہ بڑی بے صبری کا مظاہرہ کر رہے ہیں۔ کہنے لگے: امیر المومنین! اتنی بے چینی کی کیا وجہ ہے؟ آپ فوت ہو گئے تو جنت ہے اور اگر زندہ رہے تو آپ جانتے ہیں لوگوں کو آپ کی کتنی ضرورت ہے۔ انہوں نے فرمایا: اللہ تمہارے ابا پر رحم کرے وہ ہمارے بڑے خیر خواہ تھے، انہوں نے مجھے ابن الادبر یعنی حجر(6) بن عدی کے قتل سے منع کیا تھا۔","",{"fn":"(1) اسد الغابہ (۵۵۱۶) استیعاب (۲۷۸۲) تجرید (۱۳۴/۲)\n(2) الطبقات الکبریٰ (۱۴۳/۷)\n(3) التاریخ الکبیر (۴۹/۲)\n(4) مسند احمد (۶۴/۴) مجمع الزوائد (۱۳۶۶۷) اتحاف السادۃ المتقین (۲۲۳/۶، ۲۶۴) کنز العمال (۴۴۱۵۴)\n(5) الطبقات الکبریٰ (۱۴۳/۷)\n(6) عمل الیوم واللیلۃ لابن السنی (۷۱۲)"}],[7843,"§۹۲۳۲ ۔ یزید بن الاسود\n(1) بقول بعض: ابن ابی الاسود العامری ایک قول ہے خزاعی، قریش کے حلیف۔ ابن سعد(2) فرماتے ہیں: مدنی ہیں۔ جبکہ خلیفہ کا قول ہے: طائف کے رہائشی ہیں۔ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ انہوں نے آپ کی اقتداء میں نماز پڑھی۔ آپ علیہ السلام جب پلٹتے تو ایک جانب ہو جاتے۔(3) ان سے جابر بن یزید ان کا بیٹا روایت کرتا ہے، ان کی حدیث سنن ثلاثہ میں اس سند سے اور اس کے علاوہ سے مروی ہے، ترمذی نے اسے صحیح قرار دیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۸) استیعاب (۲۷۸۴) تجرید (۱۳۴/۲)\n(2) الطبقات الکبریٰ (۲۷۸/۵)\n(3) ابو داؤد کتاب الصلاۃ باب فیمن صلی فی منزلہ ثم ادرک الجماعۃ (۵۷۵) ترمذی (۲۱۹) نسائی (۸۵۷)"}],[7844,"§۹۲۳۳ ۔ یزید بن الاسود بن سلمہ\nابن حجر بن وہب الکندی بقول ابن کلبی: ان کے والد انہیں رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آئے جب یہ لڑکے تھے۔ آپ نے ان کے لیے دعا فرمائی۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[7845,"§۹۲۳۴ ۔ یزید بن اسید\n(1) ابن ساعدہ انصاری۔ بقول ابن سعد: اپنے والد اور چچا ابو خثیمہ کے ساتھ اُحد میں شریک ہوئے۔(2) ابو عمر(3) نے ان کا اتنا ہی ذکر کیا ہے۔","",{"fn":"(1) مسند احمد (۱۶۰/۴) ابو داؤد الطیالسی (۱۲۴۷)\n(2) اسد الغابہ (۵۵۱۹) استیعاب (۲۷۸۵) تجرید (۱۳۴/۲)\n(3) استیعاب (۱۳۱/۴)"}],[7846,"§۹۲۳۵ ۔ یزید بن انیس\n(1) ابن عبداللہ بن عمرو۔۔۔۔ قرشی، محاربی۔ ابو عبدالرحمن اپنی کنیت سے شہرت رکھتے ہیں۔ ابن یونس لکھتے ہیں: صحابی ہیں اور فتح مصر میں شریک ہوئے، وہیں گھر کے لیے زمین ملی اور وہاں ہی ان کی اولاد سے مصر میں ان کی کوئی روایت نہیں۔ اہل کوفہ میں سے ابو ہمام ان سے روایت کرتے ہیں۔ امام احمد(2) نے بطریق ابی ہمام عبداللہ بن یسار عن ابی عبدالرحمن الغبر کی روایت کی ہے کہ میں غزوہ حنین میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا۔ ہم لوگ چلچلاتی دھوپ اور سخت گرمی والے دن روانہ ہوئے۔ پھر سایہ دار درختوں تلے اترے۔۔۔۔ پھر لمبی حدیث ذکر کی۔ بقول بعض: ان کا نام عبد، کردوس یا حارث ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۲۳) تجرید (۱۳۴/۲)\n(2) مسند احمد (۲۸۶/۵)"}],[7847,"§۹۲۳۶ ۔ یزید بن اوس\n(1) شداد بن اوس کے بھائی۔ خلافت معاویہ میں وفات پائی۔ ایاہی \"تاریخ مظفری\" کے مصنف نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۲۴) استیعاب (۲۷۸۸)"}],[7848,"§۹۲۳۷ ۔ یزید بن بردع\n(1) ابن زید بن عامر بن سواد بن ظفر انصاری ظفری۔ ابو عمر لکھتے ہیں:(2) اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۵۲۵) استیعاب (۲۷۸۹) تجرید (۱۳۵/۲)\n(2) استیعاب (۱۳۲/۴)"}],[7849,"§۹۲۳۸ ۔ یزید بن بہرام\n(1) ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ بقول بعض: یہ اس پانچ شخص کا نام ہے جو نبی صلی اللہ علیہ وسلم کے سامنے سے گدھے پر سوار ہو کر گزرا تھا اور آپ تبوک میں نماز پڑھ رہے تھے (آپ نے اس کے لیے بددعا کی تھی)۔","",{"fn":"(1) اسد الغابہ (۵۵۲۶) تجرید (۱۳۵/۲)"}],[7850,"§۹۲۳۹ ۔ یزید بن تمیم\n(1) مولا ابی ربیعہ۔ ابن یونس نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ان کی یہ حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر خطبہ دیا، حمد و ثناء کے بعد فرمایا: \"لوگو! دو باتیں ایسی ہیں اللہ تعالیٰ نے جسے ان دونوں کے شر سے محفوظ رکھا وہ جنت میں جائے گا۔\" آپ کے ایک صحابی رضی اللہ عنہ کھڑے ہو کر عرض کرنے لگے: اللہ کے رسول صلی اللہ علیہ وسلم! آپ ہمیں وہ دو باتیں نہیں بتاتے؟ آپ صلی اللہ علیہ وسلم نے پھر وہی بات دہرائی، اسی میں ہے: \"جسے اللہ تعالیٰ زبان اور شرمگاہ کے شر سے بچائے۔\"(2) ممکن ہے یہ حدیث مرسل ہو، موطا میں اسی کا مفہوم عن زید بن اسلم عن عطاء بن یسار مرسلاً نقل کیا ہے۔ اصل موصول روایت بخاری میں حدیث سہل بن سعد سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۲۷) تجرید (۱۳۵/۲)\n(2) ترمذی کتاب الزہد باب ما جاء فی حفظ اللسان (۲۴۰۹) المستدرک (۸۰۹/۴) فتح الباری (۳۱۰/۱۱) تجرید التمہید (۹۸) اتحاف السادۃ المتقین (۴۵۰/۷) تفسیر القرطبی (۳۲۷/۹) الاذکار (۲۹۶) کشف الخفاء (۲۵۷/۲)"}],[7851,"§۹۲۴۰ ۔ یزید بن ثابت\n(1) ابن الضحاک انصاری۔ میراث کے ماہر سیدنا زید بن ثابت رضی اللہ عنہ کے بھائی۔ بقول خلیفہ: بدر میں شریک ہوئے، جبکہ اوروں نے اس کا انکار کیا ہے۔ مؤرخین کا کہنا ہے: یمامہ میں شہید ہوئے۔ امام بخاری رحمہ اللہ نے اپنی کتاب صحیح میں ایک تعلیقاً روایت میں خارجہ بن زید بن ثابت سے کتاب الجنائز میں ان کا ذکر کیا ہے، اور نسائی نے بطریق خارجہ بن زید بن ثابت، انہوں نے اپنے چچا سے جنازہ کے لیے کھڑے ہونے کے بارے میں روایت کی ہے۔ نسائی اور ابن ماجہ میں اسی سند سے ایک اور حدیث ہے، جب یمامہ میں ان کی شہادت ہوئی تو خارجہ کی ان سے روایت مرسل ہو گی۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۵۲۸) استیعاب (۲۷۹۰) تجرید (۱۳۵/۲)"}],[7852,"§۹۲۴۱ ۔ یزید بن ثابت انصاری\nاز بنی دینار بن النجار خزیمہ بن ثابت رضی اللہ عنہ کے بھائی۔ ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔"],[7853,"§۹۲۴۲ ۔ یزید بن ثعلبہ انصاری\nبقول ابن حبان: صحابی ہیں۔"],[7854,"§۹۲۴۳ ۔ یزید بن ثعلبہ\n(1) ابن خزیمہ بن اصرم بن عمرو بن عمارہ بن مالک الجلوی۔ ابو عبدالرحمن، بنی سالم بن عوف بن الخزرج کے حلیف۔ ابن اسحاق(2) نے شرکاء بیعت عقبہ ثانیہ میں ان کا ذکر کیا ہے۔ طبری(3) لکھتے ہیں: دونوں بیعتوں میں شریک ہوئے۔ ان کے جد اعلیٰ کا نام عمارہ ہے اور لفظ ثعلبہ، زاء سے الدار قطنی نے قلمبند کیا ہے اور یہ ابن اسحاق کا قول ہے جبکہ ابن کلبی نے ثعلبہ زا کے سکون سے لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۲۹) استیعاب (۲۷۹۰) تجرید (۱۳۵/۲)\n(2) السیرۃ النبویۃ (۵۶/۲) (۸۱/۲)\n(3) تفسیر الطبری (۵۹۹/۲)"}],[7855,"§۹۲۴۴ ۔ یزید بن جاریہ(5)\n(1) ابن مجمع بن العطاف بن ضبیعہ بن زید بن مالک بن عوف بن عمرو بن عوف بن مالک بن الاوس انصاری۔ ابو عبدالرحمن، ابن سعد وغیرہ نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: یزید بن جاریہ بقول بعض: زید، انہوں نے دونوں کو ایک قرار دیا ہے۔ درست یہ ہے کہ دونوں بھائی ہیں۔ الدار قطنی نے یزید بن جاریہ بن مجمع اور یزید میں فرق کیا ہے جن کے نام میں اختلاف ہے۔ بقول بعض: یزید، بقول بعض: زید بن جاریہ۔ وہ دونوں کے بارے میں فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ دوسری شخصیت امیر معاویہ سے اور ان سے الحکم بن مبینا روایت کرتے ہیں۔ خطیب نے ان کا تعاقب کیا ہے۔ ابن ماکولا(2) نے الدار قطنی کی بات کو درست قرار دیا ہے۔ لکھتے ہیں: مجھے معلوم نہیں خطیب کو اس بارے میں یقینی بات کہاں سے حاصل ہوئی۔\nمیں کہتا ہوں: یزید کی الحکم سے مروی روایت ابو داؤد کی کتاب فضائل الانصار اور سنن نسائی میں ہے اور حدیث یزید بن جاریہ بن مجمع سے وہ روایت جو بغوی، ابن شاہین، ابن السکن، ابن مندہ، الازرق اور الازدی وغیرہ نے بطریق ثوری عن عاصم بن عبداللہ، عن عبدالرحمن بن یزید بن جاریہ عن ابیہ نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر ہم سے خطاب کرتے ہوئے فرمایا: اپنے غلام لونڈیوں کا خیال رکھو! اپنے غلاموں کا خیال رکھو! جو چیز تم کھاتے ہو اس میں سے انہیں بھی دو۔ حدیث۔ اس کے آخر میں ہے: اگر تم انہیں معاف نہیں کرتے تو اللہ کے بندوں کو فروخت کر دو اور انہیں عذاب نہ دو۔(3) اور ابن ابی خیثمہ کی کتاب میں ان کی اپنے والد سے عن عبدالرحمن بن مہدی عن سفیان لکھا ہے۔۔۔۔ پھر ان الفاظ میں اس کا ذکر کیا ہے۔ عن عبدالرحمن بن یزید عن ابیہ۔ ان کے ہاں دادا کے ذکر کے بغیر لکھی ہے تو انہوں نے انہیں یزید بن رکانہ سمجھ لیا۔ جس سے ان کا عنوان قائم کر دیا جو ان کا وہم ہے۔ ابن عبدالبر(4) نے اس کی طرف اشارہ کیا ہے۔ ابن اسکن لکھتے ہیں ہارون بن عیسیٰ نے ہمیں بحوالہ داؤد بتایا کہ میں نے امام احمد سے پوچھا: کیا یزید صحابی ہیں؟ انہوں نے فرمایا: مجھے اس کا علم نہیں اور یہ مجمع کے بھائی ہیں۔\nمیں کہتا ہوں: انہوں نے اس میں توقف اختیار کیا ہے اس واسطے کہ ان کی روایت میں لکھا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: رہی وہ روایت جس میں ہے ہم سے رسول اللہ صلی اللہ علیہ وسلم نے خطاب فرمایا۔ یا میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا جیسے الفاظ کا تقاضا ہے کہ صحابی ہوں۔ ان کی ایک حدیث وہ بھی ہے جو ابن مندہ نے بطریق یزید بن ہارون عن مجمع بن یحییٰ روایت کی ہے کہ مجھ سے میرے چچا خالد بن یزید بن معاویہ نے بحوالہ اپنے والد بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس شخص نے زکوٰۃ ادا کی وہ شح (قلبی کنجوسی) سے بری ہے۔۔۔۔(6) حدیث\nاسی سند سے مجمع بن یحییٰ تک مروی ہے ہم سے سوید بن عامر نے بحوالہ یزید بن جاریہ بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اپنی رشتہ داریوں کو تروتازہ رکھو خواہ (کچھ اور نہ دے سکو) سلام کرنے سے۔ یونس بن بکیر نے \"زیادات المغازی\" میں عن ابراہیم بن اسماعیل عن مجمع بن جدہ یزید بن جاریہ روایت کی ہے کہ ہم نے خیبر سے ملنے والے حصے کے ذریعے جوڑے کے بدلے جوڑا خریدا۔ اسے عبید بن یعیش نے یونس سے نقل کیا تو کہا: زید ابو عمر(7) لکھتے ہیں: پہلا قول زیادہ صحیح ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۰) استیعاب (۲۷۹۴) تجرید (۱۳۵/۲)\n(2) الاکمال (۴/۲)\n(3) مسند احمد (۳۵/۴) (۳۶/۴) مجمع الزوائد (۷۲۱۲) الترغیب والترھیب (۲۱۴/۳)\n(4) استیعاب (۱۳۳/۴)\n(5) الدر المنثور (۱۶۰/۲) کنز العمال (۲۵۰۱۳)\n(6) المعجم الکبیر (۲۴۱/۴)، الدر المنثور (۱۹۶/۴، ۱۹۷) زاد المسیر (۲۱۶/۸) تفسیر ابن کثیر (۳۰/۸) کنز العمال (۱۵۸۰)\n(7) استیعاب (۱۳۳/۴)"}],[7856,"§۹۲۴۵ ۔ یزید بن جاریہ\nبقول بعض: سابقہ شخصیت میں ذکر ہوا ہے۔"],[7857,"§۹۲۴۶ ۔ یزید بن الجراح\n(1) وہ ابن عبداللہ بن الجراح ہیں تذکرہ ہو گا۔","",{"fn":"(1) اسد الغابہ (۵۵۳۱)"}],[7858,"§۹۲۴۷ ۔ یزید بن جمرہ بن عوف\nاپنے والد کے ساتھ حرف جیم میں مذکور ہوئے۔"],[7859,"§۹۲۴۸ ۔ یزید بن الحارث\n(1) ابن قیس بن مالک بن احمر بن حارثہ بن ثعلبہ بن کعب بن حارث بن الخزرج۔ ابن فُسحم انصاری خزرجی سے جانے پہچانے جاتے ہیں۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب اور اسی طرح ابن اسحاق(2) نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن حبان فرماتے ہیں: بدر میں شہادت پائی۔ اپنے ہاتھ میں موجود چند کھجوریں پھینکیں اور مردانہ وار لڑتے لڑتے شہید ہو گئے۔ ابن ہشام اور ابن کلبی کا بیان ہے سحم ان کی والدہ کا نام ہے جو بنی قین سے تعلق رکھتی تھیں۔ ابن عبدالبر(3) نے نقل کیا ہے یہ ان کا لقب ہے۔ ایک قول کے مطابق: نبی صلی اللہ علیہ وسلم نے ان میں اور ذوالشمالین میں بھائی بندی قائم کی تھی۔","",{"fn":"(1) اسد الغابہ (۵۵۳۲) استیعاب (۲۷۹۳) تجرید (۱۳۵/۲)\n(2) السیرۃ النبویۃ (۲۶۵/۲) (۲۵۲/۲)\n(3) استیعاب (۱۳۴/۴)"}],[7860,"§۹۲۴۹ ۔ یزید بن حاطب\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے کہ جعفر المستغفری نے ان کا ذکر کیا ہے کہ اُحد میں شہید ہوئے۔ میں کہتا ہوں: شاید یہ زید بن حاطب ہیں جن کا حرف زاء میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۳) استیعاب (۲۷۹۴) تجرید (۱۳۵/۲)"}],[7861,"§۹۲۵۰ ۔ یزید بن حُجَر\nعمرو بن سعد میں تذکرہ ہوا ہے۔"],[7862,"§۹۲۵۱ ۔ یزید بن حرام\nابن خدام میں ان کا ذکر ہو گا۔"],[7863,"§۹۲۵۲ ۔ یزید بن حصین\n(1) ابن نمیر مصری۔ نبی صلی اللہ علیہ وسلم سے سبا کے بارے میں روایت کرتے ہیں۔ ان سے علی بن رباح روایت کرتے ہیں۔ ایسا ہی ابن ابی حاتم نے ان کا ذکر کیا ہے۔ ان کا \"مصری\" کہنا وہم ہے۔ صرف اتنا کہا جاتا ہے کہ وہ مروان بن الحکم کے ساتھ مصر گئے۔ وہاں علی ابن رباح نے ان سے سماع کیا۔ بغوی، ابن السکن اور طبرانی(2) وغیرہ نے بطریق ابن وہب عن موسیٰ بن علی بن رباح عن ابیہ عن یزید ابن حصین بن نمیر روایت کی ہے۔ ایک شخص نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! سبا کے متعلق آپ کی کیا رائے ہے مرد تھا یا عورت؟ آپ نے فرمایا: وہ مرد تھا، جس کے دس بیٹے ہوئے۔۔۔۔ حدیث۔ بقول بعض: یہ یزید اس گورنر کے والد ہیں جو واقعہ حرہ میں یزید بن معاویہ کی طرف سے مقرر تھا جس نے مکہ کا محاصرہ کیا۔ آخری قسم میں تذکرہ ہو گا لہذا ان کی حدیث مرسل ہوئی۔ جہاں تک مجھے معلوم ہوتا ہے وہ اور ہیں۔ اس واسطے کہ علی بن رباح، حصین بن نمیر کے ہم عصر ہیں جو مذکورہ امیر یزید کے والد ہیں۔ واللہ سبحانہ و تعالیٰ اعلم","",{"fn":"(1) اسد الغابہ (۵۵۳۷) تجرید (۱۳۶/۲)\n(2) معجم الکبیر (۲۴۰/۱۲)"}],[7864,"§۹۲۵۳ ۔ یزید بن حکیم\n(1) بقول بعض: یزید ابو حکیم۔ ان کی حدیث ابو داؤد طیالسی(2) نے عن ہمام عن عطاء بن السائب عن حکیم بن یزید عن ابیہ کی سند سے نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لوگوں کو چھوڑو! اللہ تعالیٰ بعض کو بعض کے ذریعے رزق دیتا ہے اور جب تم میں سے کوئی اپنے بھائی سے مشورہ طلب کرے تو اسے خیر خواہانہ مشورہ دے۔ ایسا ہی علی بن الجعد اور ابو سلمہ البوزکی نے حماد بن سلمہ سے بحوالہ عطاء نقل کیا ہے۔\nمیں کہتا ہوں: میں نے کنیتوں میں اس بارے میں اختلاف کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۸) تجرید (۱۳۶/۲)\n(2) مسند ابی داؤد طیالسی (۱۸۵)"}],[7865,"§۹۲۵۴ ۔ یزید بن حویرث الانصاری\nابو عمر لکھتے ہیں: ابن کلبی نے جنگ صفین میں سیدنا علی کا ساتھ دینے والے صحابہ میں ان کا ذکر کیا ہے۔"],[7866,"§۹۲۵۵ ۔ یزید بن خارجہ انصاری\nبقول ابن حبان: صحابی ہیں۔"],[7867,"§۹۲۵۶ ۔ یزید بن خالد الجرمی\nطبرانی نے صحابہ میں ان کا ذکر کیا ہے اور ان کی کوئی روایت نہیں لکھی۔"],[7868,"§۹۲۵۷ ۔ یزید بن خالد العصری(3)\n(1) ابو موسیٰ نے ذیل میں بحوالہ ابن مردویہ ان کا ذکر کیا ہے اور ابن مردویہ نے \"مَنْ کَذَبَ عَلَیَّ\" حدیث کے طریق میں بطریق عبدالرحمن بن عمرو بن جبلہ عن سعید بن عبدالرحمن بن یزید بن خالد ان کا ذکر کیا ہے فرماتے ہیں: مجھ سے میرے والد نے بحوالہ اپنے دادا بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے جان بوجھ کر میرے متعلق جھوٹ بولا تو اسے اپنا ٹھکانا جہنم سمجھ لینا چاہیے۔(2) اور عبدالرحمن متروک الحدیث راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۱) تجرید (۱۳۶/۲)\n(2) بخاری کتاب العلم باب اثم من کذب علی النبی صلی اللہ علیہ وسلم (۱۰۶)\n(3) مسلم (۲) جامع المسانید (۴۲۶/۱۲)"}],[7869,"§۹۲۵۸ ۔ یزید بن خدارہ\nبعد والی شخصیت میں تذکرہ ہوتا ہے۔"],[7870,"§۹۲۵۹ ۔ یزید بن خدام\nابن سبیع ابن خنساء بن سنان۔۔۔۔ انصاری اسلمی۔ ابن اسحاق نے شرکاء بدر میں ان کا ذکر کیا ہے مغازی موسیٰ کے نسخوں میں اختلاف ہے۔ بعض میں اسی طرح ہے اور بعض میں حرام اور خُدارہ لکھا ہے۔"],[7871,"§۹۲۶۰ ۔ یزید بن خُوط\nخُوط بن یزید میں تذکرہ ہوا ہے۔"],[7872,"§۹۲۶۱ ۔ یزید بن رُقیش\n(1) ابن رکاب بن یعمر الاسدی۔ موسیٰ بن عقبہ اور ابن اسحاق(2) نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن حبان لکھتے ہیں: بقول بعض: انہیں شرف صحابیت حاصل ہے۔ ابو عمر(3) کا بیان ہے۔ جس نے انہیں اربد بن رقیش لکھا ہے اس سے غلطی ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۵۴۲) استیعاب (۲۷۹۸) تجرید (۱۳۶/۲)\n(2) السیرۃ النبویۃ (۲۴۲/۲)\n(3) استیعاب (۱۳۵/۴)"}],[7873,"§۹۲۶۲ ۔ یزید بن رکانہ\n(1) ابن عبد یزید بن ہاشم بن المطلب بن عبد مناف مطلبی۔ ابو عمر(2) لکھتے ہیں: یہ اور ان کے والد صحابی ہیں اور دونوں کو روایت کا شرف حاصل ہے۔ ان سے ان کے دونوں بیٹے علی اور عبدالرحمن اور ابو جعفر الباقر روایت کرتے ہیں۔ ابن قانع بطریق یزید بن ابی صالح عن علی بن یزید بن رکانہ روایت کرتے ہیں کہ ان کے والد نے انہیں خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے رکانہ کو مکہ کے بالائی حصے سے آواز دے کر فرمایا: رکانہ! اسلام لے آؤ! مگر وہ نہ مانے۔ آپ نے فرمایا: اگر میں اس درخت کو بلاؤں۔ پاس ہی ایک درخت کھڑا تھا۔ اور وہ میری بات مان لے تو کیا تم اسلام لے آؤ گے؟ انہوں نے کہا: ہاں جی۔۔۔۔ پھر وہ حدیث ذکر کی۔ ادھر رکانہ کے حالات میں بیان ہو چکا ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے کشتی لڑی تھی رکانہ کا کشتی والا واقعہ مشہور ہے۔ چنانچہ \"خطیب المؤتلف\" میں بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ یزید بن رکانہ نبی صلی اللہ علیہ وسلم کے پاس آئے اس وقت ان کے ساتھ تین سو بکریاں تھیں کہنے لگے: محمد؟\n(صلی اللہ علیہ وسلم) کیا مجھ سے کشتی لڑو گے؟ آپ نے فرمایا: میں نے اگر تمہیں پچھاڑ لیا تو مجھے کیا دو گے؟ انہوں نے کہا: سو ۱۰۰ بکریاں، پھر کشتی ہوئی تو آپ نے انہیں پچھاڑ لیا، پھر وہ کہنے لگے: دوبارہ کرنی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اب کی بار مجھے کیا انعام دو گے؟ انہوں نے کہا: اور سو(۱۰۰) بکریاں۔ پھر کشتی ہوئی تو آپ نے دوبارہ انہیں پچھاڑ لیا۔ تیسری بار انہوں نے کہا: محمد! (صلی اللہ علیہ وسلم) تم سے پہلے کوئی مجھے زمین پر نہیں گرا سکا اور نہ مجھے تم سے پہلے اتنا کسی سے بغض تھا جتنا تم سے تھا۔ اب میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی دعا و پکار اور عبادت کے لائق نہیں۔ اور آپ اللہ کے (آخری) رسول ہیں۔ آپ نے انہیں چھوڑ کر اٹھے اور ان کی بکریاں واپس کر دیں۔\nابن قانع ہی اور طبرانی نے بطریق حسین بن زید بن علی انہوں نے اپنے چچا جعفر بن محمد بن علی انہوں نے اپنے والد سے بحوالہ یزید بن رکانہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم جب جنازہ پڑھاتے تو تکبیر کے بعد فرماتے: ((اللَّهُمَّ عَبْدُكَ وَ ابْنُ عَبْدِكَ احْتَاجَ إِلَى رَحْمَتِكَ وَ أَنْتَ غَنِيٌّ عَنْ عَذَابِهِ إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ وَ إِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْهُ))(3) \"اے اللہ! یہ تیرا بندہ ہے اور تیرے بندے کا بیٹا ہے جو تیری رحمت کا محتاج ہے تجھے اسے عذاب دینے کی چنداں ضرورت نہیں۔ اگر یہ نیکوکار تھا تو اس کے ساتھ اچھا برتاؤ کرنے میں اضافہ فرما اور اگر سیاہ کار تھا تو اس سے درگزر فرما۔\" اور جتنی مقدار اللہ چاہتا آپ دعا پڑھتے۔\nابو یعلیٰ، بغوی، ابن شاہین اور ابن مندہ نے ان کے حالات میں بطریق الزبیر بن سعید عن عبداللہ بن علی بن یزید بن رکانہ عن ابیہ عن جدہ روایت کی ہے میں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں اپنی بیوی کو طلاق بائنہ دے دی۔ یہ واقعہ ان کے والد رکانہ کا ہے کیونکہ ضمیر علی کی طرف راجع ہے نہ کہ عبداللہ کی جانب۔ (یعنی عبداللہ کے دادا یزید بنتے ہیں اور علی کے دادا رکانہ) اس پر امام شافعی کی روایت جو بطریق نافع بن عجیر عن رکانہ بن عبد یزید مروی ہے دلالت کرتی ہے کہ رکانہ(4) نے اپنی بیوی کو طلاق دی۔ اسی طرح ابو داؤد وغیرہ نے اسے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۴) استیعاب (۲۷۹۹) تجرید (۱۳۶/۲)\n(2) استیعاب (۱۳۵/۴)\n(3) معجم الکبیر (۲۷۷/۸) مجمع الزوائد (۲۴/۳)\n(4) جامع المسانید (۴۲۷/۱۲)"}],[7874,"§۹۲۶۳ ۔ یزید بن زمعہ\n(1) ابن الاسود بن المطلب بن اسد بن عبدالعزی قرشی اسدی۔ ان کی والدہ قریبہ بنت ابی امیہ، سیدہ ام سلمہ کی بہن ہیں۔ سابقین میں سے ہیں۔ بقول ابن کلبی: حبشہ ہجرت کی۔ ابن سعد(2) لکھتے ہیں: نہیں بلکہ یہ مسلمانان فتح مکہ میں سے ہیں۔ زبیر کا قول ہے: معروف بن خربوز نے جاہلیت میں جن لوگوں کو قریش کی سرداری حاصل رہی، ان میں ان کا ذکر کیا ہے۔ اور وہ اسلام لانے تک برقرار رہی۔ موسیٰ بن عقبہ اور ابن اسحاق(3) وغیرہ نے غزوہ حنین کے شہداء میں ان کا ذکر کیا ہے۔ زبیر بن بکار فرماتے ہیں: طائف میں شہید ہوئے۔ زید بن زمعہ کے حالات میں بیان ہو چکا ہے کہ حنین میں شہید ہوئے ہیں یہ ممکن سمجھتا ہوں کہ دونوں بھائی ہوں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۵۴۵) استیعاب (۲۸۰۰) تجرید (۱۳۶/۲)\n(2) استیعاب الکبریٰ (۸۹/۳)\n(3) السیرۃ النبویۃ (۷۹/۴)"}],[7875,"§۹۲۶۴ ۔ یزید بن ابی زیاد\n(1) بقول بعض: یزید بن زیاد الاسلمی۔ صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں۔ ان سے یزید بن ابی حبیب روایت کرتے ہیں۔ یہ ابن یونس کا قول ہے۔ ابن مندہ لکھتے ہیں: ہمیں ان کی کوئی مسند حدیث معلوم نہیں۔ نعیم بن حماد نے \"کتاب الفتن\" میں بطریق ابی قبیل عن یزید ابن زیاد الاسلمی۔ جو صحابی ہیں۔ ایک موقوف روایت نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۶) تجرید (۱۳۷/۲)"}],[7876,"§۹۲۶۵ ۔ یزید بن زید\n(1) ابن حصین الخطمی۔ دار قطنی فرماتے ہیں: عبداللہ اور ان کے والد صحابی ہیں۔ طبری لکھتے ہیں: اُحد میں شریک ہوئے۔ عسکری وغیرہ نے صحابہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۷)"}],[7877,"§۹۲۶۶ ۔ یزید بن السائب\n(1) السائب بن یزید کے والد، صحابی ہیں۔ ترمذی وغیرہ کا قول ہے: یہ بعد والے ہیں۔","",{"fn":"(1) تجرید (۱۳۷/۲)"}],[7878,"§۹۲۶۷ ۔ یزید بن سعید\n(1) ابن ثمامہ بن الاسود بن عبداللہ بن الحارث بن الولادہ الکندی السائب بن یزید جو ابن اخت النمر سے مشہور ہیں، ان کے والد۔ بنی امیہ بن عبد شمس کے حلیف تھے۔ بقول بعض: یہ یزید بن عبداللہ بن سعید بن ثمامہ بن شیطان بن حارث بن عمرو بن معاویہ الکندی ہیں۔ زہری فرماتے ہیں: سعید بن المسیب نے فرمایا کہ نبی کریم صلی اللہ علیہ وسلم سیدنا ابو بکر اور عمر فاروق رضی اللہ عنہ نے کوئی قاضی مقرر نہیں کیا تھا، یہاں تک کہ جب سیدنا عمر کی خلافت کا آدھا عرصہ بیت گیا تو آپ نے یزید ابن اخت النمر سے فرمایا: \"چھوٹے موٹے کاموں میں میری مدد کیا کرو۔\"(2) ابن سعد لکھتے ہیں: سیدنا عمر رضی اللہ عنہ نے انہیں بازار پر مقرر کیا تھا۔ امام بخاری صلی اللہ علیہ وسلم نے صحیح میں حدیث السائب بن یزید سے نقل کیا ہے، فرمایا: میرے والد نے جب رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کیا تو میں چھ سال کا تھا۔ اور ابن شاہین کی کتاب میں ان الفاظ سے لکھی ہے: \"مجھے میرے والد نے حج کرایا۔\"\nابو داؤد نے بطریق حفص بن ہاشم بن عتبہ عن السائب بن یزید عن ابیہ کی سند سے دعا میں چہرے پر ہاتھ پھیرنے کی مرفوع روایت نقل کی ہے۔ اس سند سے ابن لہیعہ ہے۔ ان کی مسند میں ان سے آگے اختلاف ہے۔ اسی طرح ابو داؤد، امام بخاری صلی اللہ علیہ وسلم نے الادب المفرد میں اور ترمذی نے (اسے حسن قرار دیا ہے)۔ بطریق عبداللہ بن السائب عن ابیہ عن جدہ کی سند سے ایک اور حدیث نقل کی ہے: \"تم میں سے کوئی بھی اپنے بھائی کی چیز ہنسی مذاق اور سنجیدگی (Fun & Serious) میں ہرگز نہ لے۔۔۔۔\"(3) (حدیث)","",{"fn":"(1) استیعاب (۲۸۰۲) مجمع الزوائد (۱۹۶/۴)\n(2) بخاری کتاب جزاء الصید باب حج الصبیان (۱۸۵۸)\n(3) بخاری الادب المفرد (۲۴۲) ابو داؤد کتاب الادب (۵۰۰۳) ترمذی کتاب الفتن (۲۱۶۰)"}],[7879,"§۹۲۶۸ ۔ یزید بن ابی سفیان\n(1) ابن صخر بن حرب بن امیہ بن عبد شمس قرشی الاموی۔ شام کے گورنر اور خلیفہ امیر معاویہ رضی اللہ عنہ کے بھائی۔ فاضل صحابہ رضی اللہ عنہم میں سے ایک مسلمانان فتح مکہ سے تعلق رکھتے ہیں۔ نبی صلی اللہ علیہ وسلم نے بنی فراس کی زکوٰۃ وصولی پر انہیں مقرر کیا، جو رشتے میں ان کے ماموں لگتے تھے۔ یہ ابن بکار کا قول ہے۔ ابو عمر(2) کا قول ہے: سیدنا ابو سفیان کے بیٹوں میں سب سے افضل تھے، جس کی وجہ سے انہیں \"یزید الخیر\" کہا جاتا تھا۔ ان کی والدہ ام الحکم زینب بنت نوفل بن خلف بنی کنانہ سے تعلق رکھتی ہیں۔ ابو خالد کنیت تھی۔ سیدنا ابو بکر جب ۱۲ھ حج سے واپس ہوئے تو انہیں اجناد کا امیر مقرر کیا۔ سیدنا عمر رضی اللہ عنہ نے انہیں فلسطین کا گورنر مقرر کیا۔ اور جب معاذ بن جبل کا انتقال ہوا تو انہوں نے انہیں دمشق میں اپنا نائب بنایا تھا تو سیدنا عمر رضی اللہ عنہ نے انہیں اسی پر برقرار رکھا ہے۔ ابن المبارک نے کتاب الزہد میں روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے یزید بن ابی سفیان کے پیٹ پر سے کپڑا ہٹا ہوا دیکھا تو ان کی نرم جلد نظر آئی کوڑا لہرایا۔ فرمانے لگے: کیا کسی کافر کی جلد ہے؟ اسی طرح نافع سے روایت کرتے ہیں، فرمایا: میں نے ابن عمر رضی اللہ عنہ کو فرماتے سنا کہ سیدنا عمر رضی اللہ عنہ کو معلوم ہوا کہ یزید بن ابی سفیان رضی اللہ عنہ رنگ برنگے کھانے کھاتے ہیں پھر ان کا ان کے ساتھ پیش آمدہ واقعہ نقل کیا۔ اسی میں ہے: یزید! کیا کھانے کے اوپر کھانا؟ اس ذات کی قسم جس کے قبضہ قدرت میں میری جان ہے، اگر تم لوگ ان کے طریقے کے مخالف چلو گے تو ایسا کرنا تمہیں ضرور ان کے ڈگر سے ہٹا دے گا۔\" ابن ساعد کا قول ہے: اس میں ابن المبارک منفرد ہیں۔\nمیں کہتا ہوں: اہل شام کے علاوہ لوگوں میں اسماعیل ضعیف ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم اور سیدنا ابو بکر الصدیق رضی اللہ عنہ سے روایت کی ہے۔ ان سے ابو عبداللہ الاشعری، عیاض الاشعری، عبادہ بن امیہ، انہوں نے ابو سفیان کے گھرانے سے کوئی بیٹا یادگار نہیں چھوڑا۔ بقول بعض: ان کا انتقال ۱۸ھ طاعون عمواس میں ہوا، ولید بن مسلم کا قول ہے: نہیں بلکہ ان کی وفات تاخیر سے ہوئی یہاں تک کہ فتح قساریہ(3) کے بعد ۱۹ھ میں ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۵۵۰) استیعاب (۲۸۰۱) تجرید (۱۳۷/۲)\n(2) استیعاب (۱۳۶/۴)\n(3) اسد الغابہ (۳۴۲/۴)"}],[7880,"§۹۲۶۹ ۔ یزید بن السکن\n(1) امام بخاری صلی اللہ علیہ وسلم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، یہی ابن حبان کا قول ہے۔ ابو عمر(2) لکھتے ہیں: زیاد بن السکن کے بھائی ہیں۔ انہوں نے اپنے بھائی کی شہادت کا واقعہ نقل کیا۔","",{"fn":"(1) استیعاب (۲۸۰۳) تجرید (۱۳۷/۲)\n(2) اسد الغابہ (۵۵۵۲) استیعاب (۲۸۰۴) تجرید (۱۳۷/۲)"}],[7881,"§۹۲۷۰ ۔ یزید بن السکن\n(1) اسماء کے والد۔ ان کے دادا کا نام رافع بن امرئ القیس بن زید بن عبد الاشہل ہے۔ ابن سعد ان کا تذکرہ کرتے ہوئے لکھتے ہیں: یہ اور ان کا بیٹا عامر دونوں اُحد میں شہید ہوئے۔ ان کی بیٹی اسماء بیعت کرنے والی صحابیات میں سے ہے اور ان کا بیٹا عمرو احد میں شہید ہوا۔","",{"fn":"(1) استیعاب (۲۸۰۳) تجرید (۱۳۷/۲)"}],[7882,"§۹۲۷۱ ۔ یزید بن سلمہ\nابن یزید بن مشجع الجعفی۔ انہیں آنے کی سعادت حاصل ہے، کوفہ فروکش ہوئے۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں اور ان سے علقمہ بن وائل، یزید بن مرہ، سعید بن اشبوع روایت کرتے ہیں۔ ترمذی وغیرہ نے بطریق سعید بن مسروق عن سعید بن عمرو بن اشبوع روایت کی ہے کہ یزید بن سلمہ الجعفی نے عرض کی: اللہ کے رسول! میں آپ سے کئی احادیث سن چکا ہوں، مجھے خدشہ ہے بعد والی کی وجہ سے پہلی والی کو بھول نہ جاؤں۔ آپ مجھے کوئی مختصر سی بات تعلیم فرمائیں۔ آپ نے فرمایا: \"جو باتیں تمہیں معلوم ہیں ان میں اللہ سے ڈرو۔\"(1) اس کے بعد فرماتے ہیں: اس کی اسناد متصل نہیں۔ میرے نزدیک ابن اشبوع نے یزید بن سلمہ کا زمانہ نہیں پایا ہے۔ بغوی نے ان یزید بن سلمہ کا علیحدہ ذکر کیا ہے یہ وہ جعفی ہیں جن سے علقمہ بن وائل روایت کرتے ہیں، لیکن ان کا جعفی ہونا ترمذی کی صرف اسی روایت میں لکھا ہے، اور جیسا کہ انہوں نے کہا ہے، یہ منقطع ہے۔","",{"fn":"(1) ترمذی کتاب العلم باب ما جاء فی فضل الفقہ علی العبادۃ (۲۶۹۲) کنز العمال (۵۶۲۵) الدر المنثور (۳۷۲/۱)"}],[7883,"§۹۲۷۲ ۔ یزید بن سلمہ الضمری\n(1) بغوی وغیرہ نے صحابہ صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے، ابو عمر(2) لکھتے ہیں: بصرہ فروکش ہوئے، ان سے ان کا بیٹا عبدالحمید روایت کرتا ہے، جس بات میں تامل ہے۔ بغوی، ابن قانع اور مستغفری وغیرہ بطریق عثمان الحسنی عن عبدالحمید بن یزید الضمری عن ابیہ یزید ابن سلمہ روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے (نماز میں) کوے کی طرح ٹھونگ مارنے، درندے کی طرح بیٹھنے، اور آدمی کو نماز کے لیے ایسی مخصوص جگہ بنانے جیسے اونٹ اختیار کرتا ہے۔ یزید بن زریع کی عثمان سے مروی \"نسب الانصار\" میں لکھی روایت میں ہے، ابن الاثیر(3) فرماتے ہیں: جماعت کا ضمری کہنا صحیح ہے، ابن مندہ نے یہ حدیث سابقہ شخصیت کے حالات میں لکھ دی ہے جو ان کا وہم ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۳) استیعاب (۲۸۰۵) تجرید (۱۳۷/۲)\n(2) استیعاب (۱۳۷/۴)\n(3) اسد الغابہ (۲۴۲/۴)"}],[7884,"§۹۲۷۳ ۔ یزید بن سنان\n(1) ابن ابی حاتم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو عمر(2) لکھتے ہیں: نبی کریم صلی اللہ علیہ وسلم سے یہ ارشاد سنا ہے، کعبہ کی قسم نہ کھاؤ۔\" بغوی کی روایت میں ہے کسی نے ابن معین سے حدیث یزید بن سنان کے بارے میں پوچھا \"میں نے عرض کی: اللہ کے رسول!(3)\" تو یحییٰ بن معین نے فرمایا: ان کے گھرانے کے لوگوں کا کہنا ہے ان کی نبی صلی اللہ علیہ وسلم سے ملاقات نہیں ہوئی ہے، اور نہ آپ کو دیکھا ہے۔ بغوی۔ بطریق عبدالرحمن بن یحییٰ بن جابر وہ اپنے والد سے روایت کرتے ہیں، میں نے یزید بن سنان کو فرماتے سنا: نبی کریم صلی اللہ علیہ وسلم فرمایا کرتے تھے ((لا و ابیک)) (تیرے باپ کی قسم)۔ یہاں تک کہ اس سے بھی منع فرما دیا اور ارشاد فرمایا: \"کعبہ کی قسم نہ\nکھاؤ۔\" اس کے ابتدائی الفاظ ابن مندہ نے بطریق محفوظ بن علقمہ عن ابیہ عن ابن عائذ نقل کیے ہیں۔ فرماتے ہیں: یزید بن سنان نے فرمایا۔۔۔۔ پھر اس کا ذکر کیا۔ ابن مندہ فرماتے ہیں: اس کی اسناد میں تامل ہے۔ ابو نعیم لکھتے ہیں: ان کے صحابی ہونے میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۵) استیعاب (۲۸۰۷) تجرید (۱۳۷/۲)\n(2) استیعاب (۱۳۷/۴)\n(3) مسند احمد (۵۳۷۵)"}],[7885,"§۹۲۷۴ ۔ یزید بن سوید الصدفی\nبقول ابن یونس: صحابی ہیں اور فتح مصر میں شریک ہوئے۔ لکھتے ہیں: مؤرخین نے اپنی کتابوں میں ان کا ذکر کیا ہے۔"],[7886,"§۹۲۷۵ ۔ یزید بن سیف\n(1) ابن حارثہ التمیمی الیربوعی، ابن ابی حاتم بحوالہ اپنے والد نقل کرتے ہیں: صحابی ہیں، یہی ابن حبان کا قول ہے۔ ابو عمر(2) لکھتے ہیں: یزید بن سیف۔ بقول بعض: ابن یوسف التمیمی الیربوعی عریف کے بارے میں روایت کرتے ہیں۔ ان کی اولاد سے ان کی حدیث مروی ہے۔ بغوی، ابن اسکن، طبرانی اور ابن قانع بطریق مودود بن حارث بن ضریب بن یزید بن سیف بن حارثہ روایت کرتے ہیں، فرمایا: ہم سے ہمارے والد نے بحوالہ اپنے والد کے دادا یزید بن سیف بیان کیا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگا: اللہ کے رسول! میں بنی تمیم کا شخص ہوں، میرا سارا مال ضائع ہو گیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (فی الحال) میرے پاس کوئی مال نہیں۔ پھر فرمایا: کیا میں تمہیں تمہاری قوم کا ناظم نہ بنا دوں؟ میں نے عرض کی نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یقیناً ناظم جہنم میں سختی سے دھکیلا جاتا ہے۔\"(3) ابن قانع کی روایت میں ان کے دادا کے نسب سے یزید بن حارثہ لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۶) استیعاب (۲۸۰۸)\n(2) استیعاب (۱۳۸/۴)\n(3) المعجم الکبیر (۲۴۸/۲۲) الترغیب والترھیب (۵۷۰/۱) کنز العمال (۱۴۹۷۸) جمع الجوامع (۴۲۸۹)"}],[7887,"§۹۲۷۶ ۔ یزید بن شجرہ\n(1) ابن ابی شجرہ الرھاوی صحابی ہونے میں اختلاف ہے۔ عباس دوری بحوالہ ابن معین لکھتے ہیں: صحابی ہیں۔ یہی امام بخاری کا قول ہے، ابن حبان فرماتے ہیں۔ بقول بعض: صحابی ہیں۔ ایسا ہی ابن ابی حاتم نے لکھا ہے۔ ابن مندہ فرماتے ہیں: بعض انہیں صحابی کہتے ہیں۔ لیکن اس کا کوئی ثبوت نہیں۔ ابو زرعہ کا قول ہے: ان کے صحابی ہونے کی بات صحیح نہیں ہے اور جو لوگ صحابی نہیں کہتے ہیں ان کی بات غلط ہے۔ یزید بن ابی زیاد عن مجاہد عن یزید بن شجرہ (جو صحابی ہیں) روایت کرتے ہیں۔ بقول ابو حاتم: یہ غلط ہے۔ ابو زرعہ فرماتے ہیں: عن ابن فضیل عن یزید اسی جیسے الفاظ منقول ہیں۔ پھر لکھتے ہیں: ابن فضیل نے عن یزید غلط روایت کی ہے۔ ابو عمر(2) لکھتے ہیں: مجاہد سے ایک حدیث جہاد کے بارے میں منقول ہے، جس کی اسناد مضطرب ہے۔ میں کہتا ہوں: حدیث ابن فضیل کو ہم نے خرائطی کی \"مکارم الاخلاق\" میں عن علی بن حرب بحوالہ ان کے نقل کیا ہے اس سے الفاظ ہیں: یزید بن شجرہ اپنے ساتھیوں میں کھڑے ہو کر کہنے لگے: لوگو! صبح و شام تمہارا سبز، زرد اور سرخ رنگ کے لوگوں سے مقابلہ ہو چکا ہے، اور گھروں میں کوئی نہیں۔ تو جب تمہارا دشمن سے آمنا سامنا ہو تو قدم قدم بھر کر چلنا کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم\nکو فرماتے سنا ہے: \"آدمی جو بھی ایک قدم بھرتا ہے تو حورعین اسے جھانک کر دیکھتی ہے۔\" (حدیث)(3) ایسا ہی ابو بکر بن ابی شیبہ نے محمد بن فضیل سے نقل کیا ہے، بغوی لکھتے ہیں: اسے حصین نے مجاہد سے بحوالہ یزید بن شجرہ موقوفاً نقل کیا ہے، یہی درست ہے۔\nمیں کہتا ہوں: اسی روایت کو ہم نے \"الغیلانیات\" میں نقل کیا ہے کہ ہم سے محمد بن یونس، یحییٰ بن کثیر، شعبہ، اعمش، مجاہد ان کے سلسلہ سند سے یزید بن شجرہ سے مروی ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔۔ پھر اس حدیث کا ایک گوشہ ذکر کیا۔\nمحمد بن یونس الکذب کی ضعیف راوی ہے۔ محفوظاً اعمش سے موقوف روایت ہے، اسے بھی بغوی نے بطریق خالد الواسطی سے بحوالہ یزید مرفوعاً نقل کیا ہے اور ابو نعیم بطریق مسعود بن سعد عن یزید اسی طرح نقل کرتے ہیں۔ ایک روایت میں فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔ اسے عبداللہ بن المبارک نے \"کتاب الزہد\" میں عن زائدہ عن منصور بن مجاہد موقوفاً نقل کیا ہے، اور ابن مندہ نے بطریق اعمش عن مجاہد اور بیہقی نے بطریق شعبہ روایت کی ہے، فرماتے ہیں: میری طرف منصور نے خط بھیجا، میں نے یہ ان کے سامنے عن مجاہد پڑھی۔ پھر طویل موقوف روایت نقل کی۔ اس کے الفاظ ہیں: عن یزید بن شجرہ وہ رہا کے رہنے والے تھے، امیر معاویہ انہیں لشکروں پر مقرر کرتے رہتے تھے، ایک دن انہوں نے ہم سے خطاب کیا، حمد الہی اور ثناء کے بعد فرمایا۔۔۔۔ اسی میں یزید بن شجرہ سے آگے ایک اور اختلاف ہے۔ جیسا کہ خدار کے حالات میں بطریق زہری عن یزید بن شجرہ عن خدار مرفوعاً بیان ہو چکا ہے۔\nیزید بن شجرہ سے ایک اور حدیث بھی مروی ہے، جسے ابن مندہ نے ضعیف سند کے ذریعے نقل کیا ہے، جو بروایت خالد بن العلاء عن مجاہد بحوالہ ان کے منقول ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم ایک جنازہ کے لیے نکلے تو لوگوں نے کہا: بہتر آدمی تھا، اور اس کی تعریف کی۔ اتنے میں جبرائیل علیہ السلام آ گئے، کہنے لگے: یہ شخص ایسا نہ تھا جیسا کہ ان لوگوں نے کہا، لیکن تم لوگ زمین میں اللہ تعالیٰ کے گواہ ہو۔ اس کے وہ گناہ معاف کر دیے گئے جو انہیں معلوم نہیں تھے۔ لکھتے ہیں: غریب ہے اور ان کی مسند میں دو ضعیف راوی ہیں۔\nابن سعد(4) نے بعض صحابہ رضی اللہ عنہم کے ساتھ اہل شام کے پہلے طبقے میں ان کا ذکر کیا ہے، لکھتے ہیں: امیر معاویہ کی خلافت کے آخری ادوار میں اٹھاون ۵۸ھ میں فوت ہوئے۔ یہی تاریخ واقدی ہے ابو عبید اور خلیفہ نے بیان کی ہے۔ لکھتے ہیں: امیر معاویہ نے انہیں ۳۹ھ میں مکہ کا گورنر بنایا تھا۔ تو یہ تمیم بن عباس سے جھگڑ پڑے جو سیدنا علی رضی اللہ عنہ کی طرف سے وہاں کے والی تھے۔ تو ابو سعید ان دونوں کے درمیان سفیر بنے اور اس بات پر صلح ہو گئی کہ اس سال شیبہ الجھنی لوگوں کو حج کرائیں گے، مفضل القلابی نے اس کا مفہوم نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۷) استیعاب (۲۸۰۹) تجرید (۱۳۷/۲)\n(2) استیعاب (۱۳۸/۴)\n(3) مجمع الزوائد (۲۹۴/۵) المعجم الکبیر (۶۴۲/۲۲) مسند البزار (۱۷۱۲، ۱۷۱۳) جامع المسانید (۴۳۳/۱۲)\n(4) الطبقات الکبریٰ (۱۵۶/۷)"}],[7888,"§۹۲۷۷ ۔ یزید بن شراحیل\n(1) زید میں تذکرہ ہوا ہے۔","",{"fn":"(1) تجرید (۱۳۸/۲)"}],[7889,"§۹۲۷۸ ۔ یزید بن شریح\n(1) صحابی ہیں۔ ان سے جوے کے بارے میں روایت ہے جو ابوعمر کا قول ہے۔ بغوی لکھتے ہیں: مجھے ان کے صحابی ہونے میں شک ہے اور یہ روایت نقل کی ہے: تین چیزیں جو ہیں: سٹے بازی، شطرنج کھیلنا اور کبوتر کو سیٹی بجا کر بلانا۔ اس روایت کو ابوداؤد نے مراسیل میں بروایت ابن عیاش نقش کیا ہے لہذا یزید بن شریح ان کے نزدیک صحابی نہیں۔ تابعین میں یزید بن شریح الحمصی صغار تابعین سے ہیں جو اصاغر صحابہ رضی اللہ عنہم جیسے ابو امامہ اور اکابر تابعین جیسے کعب، ابن محیرز سے روایت کرتے ہیں۔ اگر حدیث بیان کرنے والے ہی ہیں تو یقینا صحابی نہیں، اور اگر کوئی اور ہیں تو احتمال ہے۔","",{"fn":"(1) استیعاب تجرید (۱۳۸/۲)"}],[7890,"§۹۲۷۹ ۔ یزید بن شیبان الازدی\n(1) بقول بعض: الدیلی۔ عمرو بن عبد اللہ بن صفوان الجمعی کے ماموں ابن ابی حاتم فرماتے ہیں: صحابی ہیں، ان سے عمرو روایت کرتے ہیں کہ ہمارے پاس ابن مربع آئے، ہم عرفہ میں تھے، کہنے لگے تمہارے پاس رسول اللہ صلی اللہ علیہ وسلم آئے ہیں اور فرما رہے ہیں: اپنے مشاعر (جہاں رسوم حج ادا کرنے کے مقامات) پر ٹھہرے رہو\"۔۔۔۔۔ (حدیث)(2) واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۵۶۱) استیعاب (۳۸۱۱) تجرید (۱۳۸/۲)\n(2) ابوداؤد کتاب المناسک باب موضع الوقوف بعرفہ (۱۹۱۹) مسند احمد (۱۳۷/۴) مشکاۃ المصابیح (۲۵۹۵) کنز العمال (۱۲۰۶۵)"}],[7891,"§۹۲۸۰ ۔ یزید بن الصلت\nعدی بن کامل میں محمد بن حمران کے حالات میں ان کی حدیث ان کی عطیہ بن یزید بن الصلت کی روایت سے بحوالہ ان کے والد مروی ہے میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں ایک غزوے میں شرکت کی تو آپ نے گھڑ سوار کو دہرا حصہ اور پیدل کو اکہرا حصہ دیا۔ اسے ابن حمران نے عن سلیمان الشاذکونی (جو بہت کمزور روایتیں نقل کرتا ہے) سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہیں دو مسلمانوں کی تلواریں سونتی ہوئی نظر آئیں تو اس وقت اپنے گھر سے نہ نکلنا\"۔(1)","",{"fn":"(1) الکامل فی الضعفاء (۲۲۵۲/۶)"}],[7892,"§۹۲۸۱ ۔ یزید بن ضرار\n(1) الشماخ کے بھائی۔ مَزْرَد میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) تجرید (۱۳۸/۲)"}],[7893,"§۹۲۸۲ ۔ یزید بن ضمرہ\n(1) ابن العیص بن منقذ بن وہب الخزاعی۔ طبری نے بحوالہ ابن کلبی ذکر کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ حنین میں شریک ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: \"الجمہرۃ\" میں ان کا نسب یوں لکھا ہے: \"وہب بن براء بن غاضرہ بن حبیشہ بن کعب\"۔","",{"fn":"(1) اسد الغابہ (۵۵۶۴) تجرید (۱۳۸/۲)"}],[7894,"§۹۲۸۳ ۔ یزید بن طعمہ\n(1) ابن جاریہ بن لوذان الانصاری العظمی۔ بقول ابوعمر: ابن کلبی نے جنگ صفین میں سیدنا علی رضی اللہ عنہ کے طرفدار صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۵) تجرید (۱۳۸/۲)"}],[7895,"§۹۲۸۴ ۔ یزید بن طلحہ\n(1) طلحہ بن زید میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۶)"}],[7896,"§۹۲۸۵ ۔ یزید بن ظبیان السدوسی\n(1) خمخام کے حالات میں ان کے آنے کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۸) تجرید (۱۳۸/۲)"}],[7897,"§۹۲۸۶ ۔ یزید بن عامر\n(1) بن الاسود بن حبیب بن سواءۃ بن عامر بن صعصعہ۔ ابو حاجر السوائی۔ بقول ابو حاتم: صحابی ہیں۔ نماز کے بارے میں نبی صلی اللہ علیہ وسلم سے نقل کرتے ہیں، جسے ابو داؤد نے بطریق نوح بن صعصعہ بحوالہ ان کے نقل کیا ہے۔ پھر طبرانی نے اسی سند سے اسے روایت کیا ہے۔ پہلے حنین میں کفار کی جمعیت کے ساتھ شریک ہوئے پھر اسلام لے آئے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۹) استیعاب (۲۸۱۳) تجرید (۱۳۸/۲)"}],[7898,"§۹۲۸۷ ۔ یزید بن عامر\n(1) ابن حدیدہ بن غنم بن سواد بن کعب بن سلمہ انصاری، ابو المنذر الخزرجی۔ ابن اسحاق(2) نے بیعت عقبہ کے شرکاء میں ان کا ذکر کیا ہے۔ بقول ابو عمر: اس میں کسی کو اختلاف نہیں، ابن اسحاق ہی نے اہل بدر میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۰) تجرید (۱۵۸/۲)\n(2) السیرۃ النبویۃ (۸۰/۲)"}],[7899,"§۹۲۸۸ ۔ یزید بن عبایہ\n(1) ابن نجیر بن خالد بن خلاس بن مرہ بن زید بن مالک بن جنادہ بن معن الباہلی۔(2) ابو عمر نے ان کا مختصر ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کی حدیث ابراہیم بن المستمر نے عن زیاد بن قریع یزید بن عبایہ عن ابیہ عن جدہ یزید کی سند سے نقل کی ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ نے ان کے سر پر دست شفقت پھیرا، وہ اپنی زکوۃ(3) لائے تھے۔ عبایہ کا ذکر حرف عین میں ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۱) استیعاب (۲۸۱۴) تجرید (۱۳۸/۲)\n(2) استیعاب (۱۳۹/۴)\n(3) اسد الغابہ (۳۴۱/۴)"}],[7900,"§۹۲۸۹ ۔ یزید بن عبد اللہ البجلی\n(1) ان سے ان کا بیٹا حمید بن یزید فضیلت جریر کی روایت نقل کرتے ہیں۔ ان کی حدیث ان کی اولاد سے مروی ہے۔ ابو عمر(2) نے ان کا بھی مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۲) استیعاب (۲۸۱۵) تجرید (۱۳۹/۲)\n(2) استیعاب (۱۳۹/۴)"}],[7901,"§۹۲۹۰ ۔ یزید بن عبد اللہ\n(1) ابن الجراح الفہری۔ ابو عبیدہ کے بھائی جو عشرہ مبشرہ میں سے ہیں۔ عامر کے حالات میں ان کا نسب بیان ہو چکا ہے۔ بقول ابن حبان: صحابی ہیں۔ یہی بات مستغفری نے ان کے اتباع میں کی ہے۔ اور یہی قول ابن مندہ کا باضافہ ان الفاظ کے ہے: ہمیں ان کی کوئی مسند حدیث معلوم نہیں۔ قیس بن الربیع نے عن عبد الملک بن المغیرہ عن فیروز بن بادی عن ابیہ بحوالہ یزید بن الجراح روایت کی ہے کہ انہوں نے ان کے ہاں ایک نصرانی عورت سے شادی کر لی تھی۔ شاید یہ اپنے دادا کے نسب سے ذکر ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۳) تجرید (۱۳۹/۲)"}],[7902,"§۹۲۹۱ ۔ یزید بن عبد اللہ الکندی\n(1) ابن مندہ نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کی حدیث یحیی بن یزید النوفلی نے عن ابیہ عن یزید بن خصیفہ بن یزید بن عبد اللہ الکندی عن ابیہ عن جدہ کی سند سے نقل کی ہے۔(2)\nمیں کہتا ہوں: نوفلی ضعیف راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۵) تجرید (۱۳۹/۲)\n(2) اسد الغابہ (۳۴۶/۴)"}],[7903,"§۹۲۹۲ ۔ یزید بن عبد المدان\n(1) ابن الدیان بن قطن بن مالک بن ربیعہ بن کعب بن الحارث بن کعب بن عمر والحارثی، ابو المنذر کنیت تھی اور والد کا نام عمرو اور دادا کا نام یزید تھا۔ عبد المدان، اور الدیان لقب ہیں۔ بقول ابن سعد: شاعر تھے۔ مغازی میں ابن اسحاق(2) لکھتے ہیں: پھر رسول اللہ صلی اللہ علیہ وسلم نے ربیع الثانی یا جمادی الاولی کے مہینے ۱۰ھ بنی حارث بن کعب کی طرف سیدنا خالد بن الولید رضی اللہ عنہ کو روانہ کیا۔ اس کے بعد ان کے اسلام لانے کی حدیث نقل کی جس میں سیدنا خالد بن الولید رضی اللہ عنہ نے اس کا خط نبی کریم صلی اللہ علیہ وسلم کی طرف بھیجا۔ جس کا جواب تھا کہ قبول کیا جائے۔ آپ کے ساتھ ان کا وفد تھا۔ جب آپ واپس آئے تو آپ کے ساتھ قیس بن الحصین ذو الغصہ، یزید بن عبد المدان، یزید بن المحجل، عبد اللہ بن قریط، شداد بن عبد اللہ، عمرو بن عمرو السبائی تھے۔ جب یہ لوگ آئے، تو آپ نے پوچھا: یہ کون لوگ ہیں؟ پھر وہ حدیث ذکر کی۔ اس حدیث کو واقدی نے بطریق عکرمہ بن عبد الرحمن بن حارث مسند بیان کیا ہے، اس میں عبد اللہ ابن عبد المدان کے نام کا اضافہ کیا ہے۔ اور عبد اللہ بن قریط کا نام عبد اللہ بن قراد، اور عمرو بن عمرو کا عمرو بن عبد اللہ لیا ہے۔ باقی نام اسی طرح ہیں۔ قیس بن الحصین کے حالات میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۹) استیعاب (۲۸۱۶) تجرید (۱۳۹/۲)\n(2) السیرۃ النبویۃ (۱۸۳/۲)"}],[7904,"§۹۲۹۳ ۔ یزید بن عتر\n(1) یزید بن عمرو میں تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۵۸۱) تجرید (۱۳۹/۲)"}],[7905,"§۹۲۹۴ ۔ یزید بن عمرو النمیری\n(1) بقول بعض: یزید بن المعتمر دولابی نے بطریق دلہم العجلی، عائذ بن ربیعہ روایت کی ہے کہ مجھ سے قرہ بن دعموص، قیس بن عاصم، ابو زہیر بن معاویہ، یزید بن عمرو، حارث بن شریح سب نے بیان کیا: ہم وفد کی صورت میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ ہم نے بیک زبان عرض کی: ہمیں وصیت فرمائیے! آپ صلی اللہ علیہ وسلم نے فرمایا: نماز قائم رکھنا، زکوۃ دینا، بیت اللہ کا حج کرنا، رمضان کے روزے رکھنا، رمضان کی ایک رات ہے جو ہزار مہینوں سے افضل ہے اور وہ حدیث ذکر کی۔ اسے ابو عمر(2) نے اسی سند سے نقل کیا ہے لیکن انہوں نے عنوان سوانح میں لکھا: یزید بن عمرو انیمی، حالانکہ ایسا نہیں۔ بلکہ وہ نمیری اور ہیں جیسا کہ ان کے حالات میں بیان ہوا ہے۔ باوردی نے اسی سند کے ذریعہ عن عائذ بن ربیعہ عن عباد بن زید عن قرہ بن دعموص و یزید بن معتمر پھر اس کا مفہوم نقل کیا۔ اسی پر رشاطی نے جزم کیا ہے لیکن یہ بھی نقل کیا ہے کہ انہیں یزید بن عمرو بھی کہا جاتا ہے۔\nمیں کہتا ہوں: احتمال ہے کہ دو ہوں۔ مستغفری فرماتے ہیں: یزید بن عتر امیری نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ایسا ہی ابن فتحون نے اپنے استدراک میں ذکر کیا ہے، لیکن ان کے استدراک میں تامل ہے۔ اس واسطے کہ ابو عمر نے ان کا ذکر کیا ہے البتہ انہوں نے \"یزید بن عمرو\" لکھا۔","",{"fn":"(1) اسد الغابہ (۵۵۸۳) استیعاب (۲۸۱۷) تجرید (۱۳۹/۲)\n(2) استیعاب (۱۴۰/۴)"}],[7906,"§۹۲۹۵ ۔ یزید بن عمرو\n(1) ابن حدیدہ انصاری خزرجی۔ ابو قطبہ ابن اسحاق نے شرکاء بیعت عقبہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۴) تجرید (۱۳۹/۲)"}],[7907,"§۹۲۹۶ ۔ یزید بن عمیرہ\n(1) شبیب بن قرہ کے حالات میں ان کا ذکر ہو چکا ہے۔ بقول بعض: زید بن عمیر ہیں۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[7908,"§۹۲۹۷ ۔ یزید بن قتادہ\n(1) بقول ابو عمر: ان سے حسان بن بلال روایت کرتے ہیں، ان کے صحابی ہونے میں تامل ہے۔ طبرانی، ابو نعیم نے اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ان کی حدیث کے سیاق میں ان کے صحابی ہونے کی کوئی وضاحت نہیں، البتہ غور سے اس بات کو حاصل کیا جا سکتا ہے، قتادہ بن زید کے حالات میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۸) تجرید (۱۳۹/۲)"}],[7909,"§۹۲۹۸ ۔ یزید بن قتافہ\n(1) ہلب کا نام جن کا تذکرہ ھاء میں ہوا ہے (ت ۸۹۹۵ ج سوم)۔","",{"fn":"(1) اسد الغابہ (۵۵۸۹) تجرید (۱۳۹/۲)"}],[7910,"§۹۲۹۹ ۔ یزید بن قیس\n(1) ابن خارجہ بن جذیمہ داری۔ سیدنا تمیم کے خاندان سے، ابن اسحاق(2) نے ان لوگوں میں ان کا ذکر کیا ہے جن کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے خیبر کی عمدہ کھجوروں کے سو وسق دینے کا حکم دیا۔ طبری لکھتے ہیں: وفد میں آئے تو اسلام قبول کیا، نبی صلی اللہ علیہ وسلم نے خیبر سے ان کا حصہ لگایا۔ واقدی کی کتاب میں نعیم بن اوس اور الطیب بن عبد اللہ داری حالات میں ان کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۰)\n(2) السیرۃ النبویۃ (۲۷۴/۳)"}],[7911,"§۹۳۰۰ ۔ یزید بن قیس\n(1) ابن خظیم بن عدی بن عمرو بن سواد بن ظفر انصاری ظفری۔ مشہور شاعر کے فرزند۔ انہی سے اس کی کنیت تھی۔ عدوی لکھتے ہیں: اُحد میں شریک ہوئے۔ اس دن ان کے جسم پر بارہ(۱۲) کاری زخم آئے۔ اسی روز آپ صلی اللہ علیہ وسلم نے ان کا نام \"حاسر\" رکھا۔ ابو عمر، ابن کلبی کی پیروی میں لکھتے ہیں: تمام معرکوں میں شریک رہے اور جسر ابی عبید میں شہادت پائی۔","",{"fn":"(1) اسد الغابہ (۵۵۹۱) استیعاب (۲۸۲۰) تجرید (۱۲۱۰/۲)"}],[7912,"§۹۳۰۱ ۔ یزید بن قیس\n(1) ابن ہانی بن حجر بن شرحبیل بن عدی بن ربیعہ بن معاویہ الاکرمین الکندی۔ بقول ابن کلبی: نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابن سعد و طبری نے اور ابن فتحون و ابن الاثیر نے اپنے اپنے استدراک میں صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ البتہ ابن سعد و طبری اور ابن فتحون کی کتابوں میں قین کی جگہ کیس لکھا ہے اور \"الجمہرۃ\" کے معتبر نسخے میں یہ نام میں نے کئیس لکھا دیکھا ہے۔","",{"fn":"(1) استیعاب (۱۴۰/۴)"}],[7913,"§۹۳۰۲ ۔ یزید بن قیس\n(1) یزید بن وقش میں تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۴) تجرید (۱۲۱۰/۲)"}],[7914,"§۹۳۰۳ ۔ یزید بن قیس\n(1) سعید کے بھائی مستغفری نے ان کا ذکر کیا ہے کہ مہاجرین اولین سے ہیں۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۳۵۰/۴)"}],[7915,"§۹۳۰۴ ۔ یزید بن کعابہ\n(1) تجرید میں حرف زاء کے تحت زید بن کعابہ لکھا ہے جبکہ درست یزید ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۲) تجرید (۱۲۱۰/۲)"}],[7916,"§۹۳۰۵ ۔ یزید بن کعب\n(1) ابن عمرو الانصاری۔ عدوی نے ان کا ذکر کیا ہے کہ یہ ان کے والد اور ان کے بھائی حبیب صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں۔ یزید اور ان کے بھائی واقعہ حرہ میں شہید ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۳) تجرید (۱۲۱۰/۲)"}],[7917,"§۹۳۰۶ ۔ یزید بن کعب البہزی\n(1) زید میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۵) استیعاب (۲۸۲۱) تجرید (۱۴۰/۲)"}],[7918,"§۹۳۰۷ ۔ یزید بن کعب\nابن ابی السیر، تذکرہ ہوتا ہے۔"],[7919,"§۹۳۰۸ ۔ یزید بن کیس\n(1) یزید بن قیس میں ذکر ہوا ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[7920,"§۹۳۰۹ ۔ یزید بن مالک\n(1) ابن عبد اللہ البجلی۔ بقول ابن حبان: صحابی ہیں، اوروں کا کہنا ہے یہ ابو سرہ ہیں جن کا تذکرہ کنیتوں میں ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۷) استیعاب (۲۸۲۲) تجرید (۱۴۰/۲)"}],[7921,"§۹۳۱۰ ۔ یزید بن المحجل الحارثی\n(1) یزید بن عبد المدان اور قیس بن حصین کے حالات میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۸) تجرید (۱۴۰/۲)"}],[7922,"§۹۳۱۱ ۔ یزید بن مربع\n(1) ابن مندہ نے ان کا ذکر کیا ہے اور حدیث میں بغیر نام کے ابن مربع آیا ہے، بقول بعض: ان کا نام زید یا عبد اللہ ہے۔ شماخ بن ضرار نے یزید بن زید بن مربع بن قیطی بن عمرو بن زید بن جشم اوسی کی مدح سرائی کی ہے، شاید وہ یہی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۹۹)"}],[7923,"§۹۳۱۲ ۔ یزید بن مسافع\nابن طلحہ بن ابی طلحہ بن عبد الدار قرشی عبدری۔ ان کا والد اُحد میں کافر مارا گیا۔ زبیر بن بکار اور بلاذری نے ان کا ذکر کیا ہے، دونوں کا کہنا ہے کہ وہ حرہ کے روز قتل ہوئے۔ شاید مسلمانان فتح مکہ میں سے تھے۔ ورنہ کم از کم انہوں نے ساڑھے چھ(۶۵۰) سال پائے ہوں گے۔ اس بنا پر وہ اس قسم سے ہوئے۔ بقول ابن زبیر ان کی والدہ خزرجیہ ہے۔"],[7924,"§۹۳۱۳ ۔ یزید بن معاویہ\nابن الاسود بن المطلب بن اسد بن عبد العزیٰ، قرشی اسدی ابو حنظلہ۔ بلاذری نے دوسری بار کے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ خیبر میں شہید ہوئے، بقول بعض: طائف میں شہادت پائی۔"],[7925,"§۹۳۱۴ ۔ یزید بن معاویہ البکائی\n(1) بقول ابن حبان و مستغفری: صحابی ہیں۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، جبکہ ابن حبان اس سے بے خبر رہے اس لیے دوبارہ تابعین میں ان کا ذکر کر دیا۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[7926,"§۹۳۱۵ ۔ یزید بن معبد الیمامی\n(1) بقول ابن ابی حاتم(2) انہیں آنے کی سعادت حاصل ہے، ان سے ان کا بیٹا معبد روایت کرتا ہے۔ ابو عمر(3) لکھتے ہیں جس کا مفہوم یہی ہے۔ اور یہ اضافہ نقل کیا ہے یہ بھی قیسی ہیں۔ ابن مندہ کا قول ہے: معبد کے دونوں بیٹے یزید اور قیس صحابی ہیں، ان کی حدیث ابن قانع، طبرانی،(4) اور ابن شاہین نے بطریق ایوب بن عتبہ عن معبد بن یزید عن ابیہ یزید بن معبد روایت کی ہے۔ فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا، آپ نے مجھ سے یمامہ کے بارے میں پوچھا: ان لوگوں کی کتنی تعداد ہے؟ میں نے بنی عبد اللہ بن الدول کے بارے میں کچھ کہنا چاہا پھر مجھے خدشہ ہوا کہیں میں آپ سے جھوٹ بول دوں گا۔ میں نے عرض کی: ان میں بنی عقبہ میں۔ آپ نے فرمایا: تم نے سچ کہا۔ اہل نسب کے ربعی اور حنفی کہنے میں کوئی فرق نہیں۔ اس واسطے کہ دول بنی حنیفہ کا بطن ہے۔ اور حنیفہ ربیعہ کا قبیلہ ہے۔ رہی ابو عمر کی قیسی کہنے کی بات تو اہل نسب نے ان پر نکیر کی ہے۔ ان لوگوں کا کہنا ہے: درست یہ ہے کہ وہ حنفی ہیں۔ ابن ابی عاصم نے بطریق رباط بن عبد الحمید عن ھائی بن یزید عن ابیہ روایت کی ہے کہ ان کے بھائی قیس بن معبد اور جاریہ بن ظفر کے درمیان ایک چراگاہ پہ جو ان میں مشترکہ تھی جھگڑا ہو گیا تو قیس نے اس کے ہاتھ پہ وار کر کے کاٹ دیا اور جاریہ نے بھی جوابی حملہ کیا، پھر دونوں اس چراگاہ کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم سے کرانے گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اپنا ہاتھ دے دو\"۔ اس نے انکار کیا، آپ صلی اللہ علیہ وسلم نے پھر مجھ سے فرمایا: \"مجھے اپنے بھائی کا وار دے دو\"۔ میں نے عرض کی: اللہ کے رسول! یہ آپ کے لیے ہے تو آپ نے مجھے رزق اور اولاد کی دعا دی اور قیس بن معبد کے مال میں جاریہ بن ظفر کے ہاتھ کی دیت کا فیصلہ فرمایا۔","",{"fn":"(1) اسد الغابہ (۵۶۰۲) استیعاب (۲۸۲۴) تجرید (۱۴۰/۲)\n(2) الجرح والتعدیل (۲۸۶/۹)\n(3) استیعاب (۱۴۱/۴)\n(4) المعجم الکبیر (۲۴۶/۲۲)"}],[7927,"§۹۳۱۶ ۔ یزید بن المعتمر\nیزید بن عمرو میں تذکرہ ہوا ہے۔"],[7928,"§۹۳۱۷ ۔ یزید بن المنذر\n(1) ابن سرح بن مختاس ابن سنان بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاری خزرجی اسلمی۔ ابن اسحاق(2) نے شرکاء بیعت عقبہ میں ان کا ذکر کیا ہے۔۔۔۔ اور اسی طرح۔۔۔۔","",{"fn":"(1) تجرید (۱۴۰/۲)\n(2) السیرۃ النبویۃ (۷۹/۲)"}],[7929,"§۹۳۱۸ ۔ یزید بن ابی منصور\n(1) بقول مستغفری، بعض کا کہنا ہے: صحابی ہیں، اس میں اختلاف ہے پھر بطریق لیث عن دوید بن نافع عن یزید بن ابی منصور (جو صحابی ہیں) روایت کی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میری اُمت کے بہترین لوگوں پہ تیزی طاری ہوگی\"۔(2) پھر لکھتے ہیں: اس میں لیث سے آگے اختلاف ہے۔\nمیں کہتا ہوں: اسے عبد الرحمن بن ابان نے لیث سے نقل تو کیا ہے لیکن انہوں نے کہا: دوید عن ابی منصور (جو صحابی ہیں) اور حسن بن سفیان نے اپنی مسند میں عن الربیع الزھرانی بحوالہ ان کے نقل کی ہے۔ اور عن قتیبہ عن اللیث نقل کی ہے لیکن یوں نہیں کہا: \"انہیں شرف صحابیت حاصل ہے\"۔ یونس بن محمد اور علی بن غراب وغیرہ نے ان کی متابعت کی ہے اس کی مزید تفصیل ان شاء اللہ کنیتوں میں ابو منصور کے حالات میں بیان ہوگی۔\nمیں کہتا ہوں: تابعین میں یزید بن ابی منصور وہ ہیں جن کا تذکرہ ابن یونس نے لکھا ہے کہ بصری ہیں، مصر پھر افریقا سکونت اختیار کر لی اس کے بعد بصرہ لوٹ آئے۔ سیدنا انس سے روایت کرتے ہیں۔ ابن ابی حاتم(3) نے یہ اضافہ نقل کیا ہے: ذو اللحیہ کلابی سے روایت کرتے ہیں۔ ابن حبان نے ان کا ذکر تو کیا ہے لیکن تبع تابعین میں۔","",{"fn":"(1) اسد الغابہ (۵۶۰۵) تجرید (۱۴۰/۲)\n(2) المعجم الکبیر (۱۹۴/۱۱) المطالب العالیہ (۳۲۳۱) الکامل (۱۱۴۸/۳) العلل (۲۴۷/۲) التذکرۃ (۱۹۰)\n(3) الجرح والتعدیل (۲۹۱/۹)"}],[7930,"§۹۳۱۹ ۔ یزید بن مہار خسرو الیمامی\n(1) اصلا فارسی ہیں۔ ابن السکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا اور بطریق ولید بن یزید بن معلی بن عباس بن یزید بن شرحبیل بن یزید بن مہار خسرو، ان کی خاندانی سند سے روایت کی ہے، فرماتے ہیں: اہل فارس کے جوان موٹے ریشم کا لباس پہنے سونے کے حلقے (بٹن) لگائے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ اور یزید آپ کے پاس سفید کپڑوں میں ملبوس آئے۔ آپ نے فرمایا: تم لوگ اس کی مشابہت نہیں کر سکتے جو دنیا سے بے رغبت اور آخرت کی رغبت رکھنے والا ہے۔ ابن مندہ نے اسے تعلیقا نقل کر کے لکھا ہے، ولید بن یزید نے یہ روایت کی ہے۔ پھر اپنی سند سے اسے مختصر ذکر کیا ہے کہ عن ابیہ عن یزید وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سفید کپڑوں میں آئے۔ آپ علیہ السلام نے ان کا نام \"زاہد\"(2) رکھا، یہی طرز ابو نعیم کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۰۶) تجرید (۱۴۱/۲)\n(2) جامع المسانید (۴۴۳/۱۲)"}],[7931,"§۹۳۲۰ ۔ یزید بن نبیشہ\nقرشی عامری۔ ابن عساکر نے ان کا ذکر کیا ہے کہ بقول بعض صحابی ہیں۔ فتح دمشق میں شریک ہوئے، پھر ایک روایت نقل کی ہے کہ ایک محدث کا بیان ہے یزید بن نبیشہ امیر معاویہ کے پاس آئے اس وقت انہوں نے سیاہ خضاب اپنی داڑھی پر لگا رکھا تھا۔ امیر نے پوچھا: آپ کون؟ انہوں نے کہا: آپ کا عامل یزید بن نبیشہ۔ آپ نے فرمایا: جب تک آپ کی داڑھی اپنے اصلی رنگ میں نہیں آ جاتی اس سے پہلے میرے پاس نہ آنا۔\nابو الحسین رازی نے اپنے دمشقی شیوخ سے روایت کی ہے کہ ہمیشہ کی وہ حویلی جو بازار ریحان میں ہے وہ دمشق پہ امیر معاویہ کے گورنر یزید بن نبیشہ کی ہے۔ دمشق کے دور میں جب وہ فتح ہوا تو وہ ایک گواہ تھے، یہ قریشی صحابی ہیں جن کا تعلق بنی عامر بن لوی سے ہے، صحابی ہیں۔ یہ وہی ہیں جنہیں امیر معاویہ رضی اللہ عنہ نے داڑھی پر سیاہ خضاب لگانے کی وجہ سے اپنے ہاں آنے سے روک دیا تھا۔"],[7932,"§۹۳۲۱ ۔ یزید بن نعامہ\n(1) بقول امام بخاری رحمہ اللہ(2) اور ابن حبان: صحابی ہیں، جبکہ ابو حاتم رازی(3) کا قول ہے: صحابی نہیں۔ ان کی حدیث مرسل ہے، بغوی لکھتے ہیں: ہمیں ان کے بارے میں نبی صلی اللہ علیہ وسلم سے سماع کا پتہ نہیں۔ ترمذی \"العلل\" میں بحوالہ امام بخاری رحمہ اللہ و شیخی نقل کرتے ہیں، ان کی حدیث مرسل ہے۔ بغوی پھر لکھتے ہیں: ان کے صحابی ہونے میں اختلاف ہے۔ البتہ ابو بکر بن ابی شیبہ نے اپنی مسند میں ان کی حدیث نقل کی ہے۔\nمیں کہتا ہوں: راویوں میں یزید بن نعامہ مفتی تابعی ہیں جو سیدنا انس رضی اللہ عنہ سے روایت لیتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۰۷) تجرید (۱۶۲۶) (۱۴۱/۲)\n(2) التاریخ الکبیر (۳۱۳/۴)\n(3) الجرح والتعدیل (۲۹۲/۹)"}],[7933,"§۹۳۲۲ ۔ یزید بن النعمان\n(1) ابن عمرو ابن عرفجہ بن العاتک بن امرئ القیس بن ذبل بن معاویہ الکندی۔ بقول ابن کلبی: یہ اور ان کے دونوں بھائی حجر اور عکس نبی صلی اللہ علیہ وسلم کے پاس وفد کی صورت میں آئے۔","",{"fn":"(1) الجرح والتعدیل (۱۴۱/۲)"}],[7934,"§۹۳۲۳ ۔ یزید بن نعیم\n(1) طبرانی(2) نے ان کی حدیث نقل کیے بغیر ان کا ذکر کیا ہے، اگر یہ وہی ہیں جن کے دادا \"ہزال\" ہیں تو یہ تابعی ہیں۔","",{"fn":"(1) ایضا\n(2) المعجم الکبیر (۲۴۵/۲۲)"}],[7935,"§۹۳۲۴ ۔ یزید بن نویرہ\n(1) ابن حارث بن عدی بن بخشم بن مجدعہ بن حارثہ بن حارث انصاری۔ بقول ابن عبد البر، اُحد میں شریک ہوئے اور نہروان کے روز جنگ کی۔ خطیب اپنی تاریخ میں لکھتے ہیں: نہروان کے روز سیدنا علی رضی اللہ عنہ کی فوج کا پہلا سپاہی جو شہید ہوا وہ انصار کا یزید ابن نویرہ نامی شخص تھا۔ نبی صلی اللہ علیہ وسلم نے انہیں دو بار جنت کی بشارت دی تھی، ایک بار اُحد میں جب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو ٹیلے سے آگے نکل گیا اس کے لیے جنت ہے\"۔ چنانچہ یزید تلوار لیے وار کرتے ہوئے ٹیلے سے آگے نکل گئے۔ تو ان کے چچا زاد بھائی کہنے لگے: اللہ کے رسول! جو خوشخبری آپ نے میرے چچا زاد بھائی کو دی ہے مجھے بھی دیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ چنانچہ وہ بھی لڑتے لڑتے آگے نکل گئے۔ پھر دونوں واپس آئے تو ایک مقتول میں دونوں کا اختلاف ہو گیا، جسے ان دونوں نے قتل کیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: تم دونوں کے لیے جنت واجب ہے اور یزید تمہیں اپنے ساتھی پہ فضیلت حاصل ہے۔ ابن عقدہ(2) نے اپنی ضعیف سے نقل کیا ہے کہ سیدنا علی رضی اللہ عنہ کے ساتھ نہروان میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۰) استیعاب (۲۸۲۷) تجرید (۱۴۱/۲)\n(2) استیعاب (۱۴۲/۴)"}],[7936,"§۹۳۲۵ ۔ یزید بن وقش\n(1) بنی عبد شمس کے حلیف۔ ابن اسحاق کا بیان ہے یمامہ میں شہید ہوئے۔ یہ اموی کی بحوالہ ابن اسحاق روایت ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ بعض کا کہنا ہے: یزید بن قیس واقدی فرماتے ہیں: سالم مولی ابی حذیفہ کے بعد جنگ یمامہ میں علم سنبھالا اور شہید ہو گئے۔","",{"fn":"(1) تاریخ بغداد (۲۰۴/۱)"}],[7937,"§۹۳۲۶ ۔ یزید بن یحنس الکوفی\n(1) ابو الحسن، ابن عساکر(2) نے ان کا ذکر کیا ہے کہ دور نبوی پایا ہے لیکن مجھے ان کی رویت کا علم نہیں۔ سیف \"فتوح\" میں لکھتے ہیں: جنگ یرموک میں شریک ہوئے اور گھڑ سواروں کے ایک دستے کے امیر تھے۔\nمیں کہتا ہوں: کہ فتوحات میں صحابہ رضی اللہ عنہم ہی امیر بنائے جاتے تھے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۳) تجرید (۱۴۱/۲)\n(2) الجرح والتعدیل (۲۹۵/۹)"}],[7938,"§۹۳۲۷ ۔ یزید بن ابی الیسر\n(1) ابو الیسر کا نام کعب بن عمرو تھا۔ ابن سعد نے ان کا ذکر کیا ہے کہ ام سعید کبشہ بنت ثابت بن عتیک (جو صحابیہ ہیں اور بیعت کرنے والی خواتین میں سے ہیں) سے شادی کی جن سے سعید اور عروہ پیدا ہوئے۔ نساء میں اس کی تفصیل بیان ہوگی۔","",{"fn":"(1) تجرید (۱۴۱/۲)"}],[7939,"§۹۳۲۸ ۔ یزید\nمعن کے والد، بغوی اور ابن شاہین نے ان میں اور یزید بن الاخنس میں فرق کیا ہے۔"],[7940,"§۹۳۲۹ ۔ یزید مولا سلیم بن عمرو\nموسیٰ بن عقبہ نے انصار میں سے بنی سواد کے اُحد کے شہداء میں ان کا ذکر کیا ہے۔ ابن عبد البر نے \"عنترۃ\" کے حالات میں ابن اسحاق کی پیروی کرتے ہوئے ان کا ذکر کیا ہے۔"],[7941,"§۹۳۳۰ ۔ یزید، ابو عمر\n(1) طبرانی(2) نے ان کا ذکر کیا ہے اور بروایت خطاب بن القاسم عن ابن اسحاق عن عمر بن یزید انہوں نے اپنے والد سے روایت کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو کوئی (بلا وجہ) کسی چڑیا کو مارے گا تو وہ قیامت کے روز چیخ کر کہے گی: اے میرے رب! اس نے مجھے فضول قتل کیا، نہ میری جان گنوانے سے کوئی فائدہ حاصل کیا اور نہ مجھے (زندہ) چھوڑا کہ میں آپ کی زمین میں زندگی بسر کرتی۔","",{"fn":"(1) اسد الغابہ (۵۵۸۶) تجرید (۱۳۹/۲)\n(2) المعجم الکبیر (۲۴۵/۲۲)"}],[7942,"§۹۳۳۱ ۔ یزید\n(1) غضبان کے والد۔ ان کی ایک حدیث ہے جو انہوں نے اپنے والد سے نقل کی ہے، تجرید میں ایسا ہی ہے۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[7943,"§۹۳۳۲ ۔ یزید (بے نسبت)\n(1) ابن مندہ نے ان کا ذکر کیا ہے کہ حدیث سراج بن مجامعہ میں ان کا ذکر ہے، ان کا اشارہ اس روایت کی طرف ہے جو طبرانی وغیرہ نے بطریق ہلال بن سراج بن مجاعہ عن ابیہ نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں یمن میں زمین عطا کی اور ان کے لیے ایک تحریر لکھوائی: \"محمد رسول اللہ (صلی اللہ علیہ وسلم) کی طرف سے مجاعہ بن مرارہ جو بنی سلیم میں سے ہے، کے لیے، میں نے تمہیں فلاں فلاں زمین دے دی ہے اب جو کوئی تم سے اس کے بارے میں جھگڑے وہ میرے پاس آ جائے\"۔ وہ تحریر یزید نے قلمبند کی تھی۔\nمیں کہتا ہوں: احتمال ہے وہ یزید بن ابی سفیان رضی اللہ عنہ ہوں کیونکہ وہ آپ کے لیے لکھا کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۴) تجرید (۱۴۱/۲)"}],[7944,"§۹۳۳۳ ۔ یزید الکرخی\nابن حکیم میں ان کا تذکرہ ہوا ہے۔"],[7945,"§۹۳۳۴ ۔ یسار بن ازیہر الجہنی\n(1) ابن السکن: اہل مدینہ میں شمار ہوتے ہیں۔ ابو عمر: ابو الغادیہ ہیں۔ جس کی ابن فتحون نے تردید کی ہے۔ ابن السکن اور ابن مندہ بطریق محمد بن الحسن ان کی حدیث نقل کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے سر پہ ہاتھ پھیرا اور مجھے دو چادریں اور ایک تلوار عطا کی، ان کی بیٹی عمرہ کہتی ہیں کہ وفات تک میرے والد کا سر سفید نہیں ہوا۔(2)","",{"fn":"(1) اسد الغابہ (۵۶۱۵) تجرید اسماء الصحابہ (۱۴۱/۲)\n(2) اسد الغابہ (۵۶۱۵) تجرید اسماء الصحابہ (۱۴۱/۲)"}],[7946,"§۹۳۳۵ ۔ یسار بن الاطول الجہنی\n(1) سعد کے بھائی۔ حاکم نے ان کے بھائی ابو مطرف کے حالات میں ان کا نام سعد بتایا ہے اور یہ روایت نقل کی ہے کہ سعد بن الاطول نے کہا: اور ان کے بھائی یسار بن الاطول یعنی جو عہد نبی صلی اللہ علیہ وسلم میں فوت ہوئے۔ ابو عمر سعد بن الاطول کے حالات میں لکھتے ہیں: ان کے بھائی یسار بن الاطول عہد نبی صلی اللہ علیہ وسلم میں فوت ہوئے۔ یہ حدیث ابن ماجہ، اور حاکم نے بطریق حماد بن سلمہ بحوالہ سعد بن الاطول نقل کی ہے کہ ان کے بھائی کا انتقال ہوا تو وراثت میں تین سو(۳۰۰) درہم اور عیال چھوڑے۔ تو میں نے ان کے اہل و عیال پر وہ درہم خرچ کرنا چاہے تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا بھائی اپنے قرضے کی وجہ سے رکا ہوا ہے، اس کا قرض ادا کرو\"۔(2) فرماتے ہیں: میں نے ان کا قرض ادا کیا۔\nابن عبد البر ان سے غافل ہو گئے باوجود یکہ سعد کے حالات میں ان کا ذکر کیا ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) مجمع الزوائد (۱۶۱۲۷) جامع المسانید والسنن (۴۵۱/۱۲)\n(2) اسد الغابہ (۵۶۱۶) تجرید اسماء الصحابہ (۱۴۱/۲)"}],[7947,"§۹۳۳۶ ۔ یسار بن بلال\n(1) بقول بعض: ابو لیلیٰ انصاری کا نام ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۸) استیعاب (۲۸۳۱) تجرید (۱۴۱/۲)"}],[7948,"§۹۳۳۷ ۔ یسار بن سبع\n(1) ابو الغادیہ الجہنی۔ بقول بعض المزنی، کنیتوں میں تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۶۲۲) استیعاب (۲۸۳۳) تجرید (۱۴۲/۲)"}],[7949,"§۹۳۳۸ ۔ یسار بن سوید الجہنی\n(1) مسلم بن یسار بصری کے والد۔ ابن السکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، سمویہ نے اپنے فوائد میں، ابن السکن اور خطیب نے المتفق میں اور ابن مندہ نے بطریق ابو الہیثم بن قیس عن عبد اللہ بن مسلم بن یسار عن ابیہ عن جدہ عن النبی صلی اللہ علیہ وسلم موزوں پر مسح اور صرف(2) کے بارے میں چند احادیث نقل کی ہیں۔ حافظ موسیٰ بن ہارون الحمال کا قول ہے: قرہ بن حبیب سے کسی نے پوچھا: کیا یسار نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے؟ انہوں نے فرمایا: اختلاف ہے۔ ابو موسیٰ کا قول ہے: اس مسند میں وہم ہے۔ قتادہ کی عن مسلم بن یسار عن ابی الاشعث عن قتادہ صرف کے بارے درست سند ہے۔\nمیں کہتا ہوں: سلمہ بن علقمہ اور محمد بن سیرین نے عن مسلم بن یسار اسی طرح نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۲۳) استیعاب (۲۸۳۴) تجرید (۱۴۲/۲)\n(2) المعجم الکبیر (۳۷۶/۱۲) جامع المسانید (۴۵۲/۱۲)"}],[7950,"§۹۳۳۹ ۔ یسار بن عبد\n(1) ابن عامر بن نعیم بن ملاحق بن جذیمہ... ابو عزۃ الہذلی۔ کنیت سے مشہور ہیں۔ ابو علی بن السکن وغیرہ نے ان کا نسب بیان کیا ہے، لکھتے ہیں: بصرہ کے رہائشی ہیں وہیں ان کی حویلی ہے۔ ان سے ایک حدیث مروی ہے جس میں یسار بن عمرو نام بتایا جاتا ہے کہ بیعت رضوان کے شرکاء میں سے ہیں۔ پھر وہ(2) حدیث نقل کی، کنیتوں میں اس کا تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۶۲۴) استیعاب (۲۸۳۵) تجرید (۱۴۲/۲)\n(2) المعجم الکبیر (۳۷۶/۲۲) التاریخ الکبیر (۴۴۱۹/۴)"}],[7951,"§۹۳۴۰ ۔ یسار بن مالک الثقفی\nان کے مولا تحننس کے حالات میں۔"],[7952,"§۹۳۴۱ ۔ یسار\n(1) بریدہ کے غلام مدینین میں ان کا ذکر ملتا ہے۔ اسی طرح ابن مندہ نے ان کا مختصر ذکر کیا ہے اور عمر بن شبہ بطریق عبد العزیز ابن عمران عن یحییٰ بن اش مولا بنی ضمرہ روایت کرتے ہیں کہ میں نے بریدہ بن الحصیب الاسلمی کو فرماتے سنا وہ بتاتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر ہجرت کے دوران ان کے پاس سے گزرے تو انہوں نے اپنا یسار غلام ان کے ساتھ بھیجا۔ وہ کہتے ہیں: جب نماز کا وقت ہوا، رسول اللہ صلی اللہ علیہ وسلم قبلہ رخ کھڑے ہوئے۔ ابو بکر آپ کے دائیں طرف اور میں بائیں جانب کھڑا ہوا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابو بکر کے سینے پہ ہاتھ مار کر اپنے پیچھے اور مجھے انھوں نے پیچھے کر دیا تو ہم نے آپ کے پیچھے صف بنائی۔ عمر بن شبہ کا قول ہے: عبد العزیز اکثر غلطیاں کرنے والا راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۷)"}],[7953,"§۹۳۴۲ ۔ یسار الجثی الراعی\n(1) ابو نعیم نے ان کا نام لیا ہے اور واقدی نے بطریق یعقوب بن عقبہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کو معلوم ہوا کہ غطفان کی ایک جماعت جو بنی ثعلبہ بن سعد سے تعلق رکھتی ہے، کدر میں ہے۔ جب آپ اس وادی میں پہنچے تو وہاں چرواہوں کو دیکھا ان میں یسار نامی ایک غلام تھا آپ نے اس سے پوچھا: اس نے کہا: اس نے کہا مجھے اتنا پتہ ہے کہ لوگوں کی نفری پانیوں کی طرف بڑھی تھی۔ تو رسول اللہ صلی اللہ علیہ وسلم لوٹ گئے جبکہ جانوروں کو حاصل کرنے میں کامیابی ہوئی۔ جب آپ نے صبح کی نماز پڑھائی آپ نے دیکھا کہ یسار نماز پڑھ رہا ہے پھر آپ نے غنیمت تقسیم کرنے کا حکم دیا۔ لوگوں نے عرض کی: ہم ان سب کو ایک ساتھ ہانک سکتے ہیں کیونکہ ہمارے کچھ لوگ اپنے حصے کے جانوروں کو ہانکنے سے عاجز ہیں۔ پھر لوگوں نے عرض کی: اللہ کے رسول! اگر آپ کو وہ غلام اچھا لگا ہے جسے آپ نے نماز پڑھتے دیکھا ہے تو ہم اپنے حصے سے وہ آپ کو دیتے ہیں؟ آپ نے فرمایا: جیسی تمہاری خوشی؟ لوگوں نے عرض کی: جی ہاں۔ آپ نے اسے قبول کر کے آزاد کر دیا۔ ابو عمر(2) بحوالہ ابن اسحاق بیان کرتے ہیں: نبی صلی اللہ علیہ وسلم نے اس کا نام اسلم رکھا۔ ابن الاثیر(3) اس کی تردید کرتے ہیں کہ اسلم تو خیبر میں شہید ہوئے جیسا کہ ان کے حالات میں بیان ہوا۔","",{"fn":"(1) اسد الغابہ (۵۶۱۹) استیعاب (۲۸۳۹) تجرید (۱۴۱/۲)\n(2) استیعاب (۱۴۵/۴)\n(3) اسد الغابہ (۳۵۵/۴)"}],[7954,"§۹۳۴۳ ۔ یسار الخفاف\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، لکھتے ہیں: یوسف بن فورک المستملی نے اپنی کتاب الجنائز میں بطریق حفص بن عبد الرحمن الہلالی روایت کی ہے کہ مجھ سے میرے والد نے بیان کیا کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لائے، پھر ایک ایسی حویلی تک پہنچے جسے فرشتوں نے گھیر رکھا تھا، آپ اس میں داخل ہوئے تو وہاں نور پھوٹ رہا تھا۔ آپ نے دیکھا، ایک شخص نماز پڑھ رہا ہے وہ نور اس کے منہ سے پھوٹ کر آسمان تک جا رہا ہے۔ اس شخص نے نماز مختصر کر لی۔ آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: تم کون ہو؟ اس نے کہا: بنی فلاں کا غلام ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہارا نام؟ اس نے کہا: یسار۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہارا عمل کیا ہے؟ عرض کی: موزے بیچنا۔ جب صبح ہوئی تو آپ نے اس کے متعلق پوچھا۔ لوگوں نے عرض کی: آپ اس کا کیا کریں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: میں اسے آزاد کروں گا۔ ان لوگوں نے عرض کیا ہم آپ کو اس کا اجر نہ سونپ دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: کیوں نہیں۔ چنانچہ انہوں نے اسے آزاد کر دیا۔ راوی کا کہنا ہے: پھر ایک رات آپ اس حویلی تک پہنچے تو آپ کو فرشتے نہ نظر آئے، آپ نے دروازہ کھولا تو وہ سجدہ میں پڑا ہوا تھا اور اسی حالت میں روح پرواز کر گئی تھی۔ اتنے میں جبرائیل علیہ السلام آپ کے پاس تشریف لائے اور کہنے لگے: اے محمد (صلی اللہ علیہ وسلم)! ہم نے آپ کو اس کے غسل کی زحمت نہیں دی چنانچہ ان لوگوں نے اسے عمدہ کفن پہنایا۔(2)","",{"fn":"(1) اسد الغابہ (۵۶۲۰) تجرید (۱۴۱/۲)\n(2) اسد الغابہ (۳۵۶/۴)"}],[7955,"§۹۳۴۴ ۔ یسار الراعی\n(1) دوسرے ہیں۔ جنہیں عرنیوں نے قتل کیا تھا، صحیحین میں بغیر نام ان کا ذکر ثابت ہے جو حدیث ان سے منقول ہے اور سلمہ ابن اکوع کی حدیث میں نام ہے۔ اسے طبرانی(2) نے بطریق موسیٰ بن محمد بن ابراہیم التیمی عن ابیہ عن سلمہ نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم کا یسار نامی ایک غلام تھا۔ آپ نے دیکھا وہ بڑی اچھی نماز پڑھتا ہے تو اسے آزاد کر دیا۔ اور اپنی اونٹنیاں دے کر حرہ بھیجا، عرینہ کی ایک قوم نے اسلام کا اظہار کیا تھا جو بیمار تھے ان کے پیٹ پھول رہے تھے۔ آپ نے انہیں یسار کی جانب بھیجا تو یہ لوگ اونٹنیوں کا دودھ پینے لگے پھر یسار پر حملہ کر کے اسے شہید کر دیا اور اس کی آنکھوں میں کانٹے ٹھونس دیئے۔ (حدیث) احتمال ہے یہ پہلے والے ہوں جن کا ایک عنوان پہلے ذکر ہوا ہے لیکن انہیں حبشی کہا ہے اور انہیں نوبی کہا جاتا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۶۲۱) تجرید (۱۴۲/۲)\n(2) المعجم الکبیر (۲۸۴/۲۲)"}],[7956,"§۹۳۴۵ ۔ یسار\n(1) ابو ہند الحجام۔ مولا بنی بیاضہ، کنیتوں میں تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۰) تجرید (۱۴۲/۲)"}],[7957,"§۹۳۴۶ ۔ یسار\n(1) مولا بنی سلیم بن عمرو۔ موسیٰ بن عقبہ نے شہداء اُحد میں اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۴۲/۲)"}],[7958,"§۹۳۴۷ ۔ یَسار\n(1) ابو فکیہہ مولا صفوان۔ ابن اسحاق نے ان لوگوں میں ان کا ذکر کیا ہے جن کے بارے میں یہ آیت نازل ہوئی(2) اور آپ ان لوگوں کو اپنے پاس سے نہ ہٹائیے جو صبح و شام اپنے رب کو پکارتے ہیں۔ یہ اپنی کنیت سے مشہور ہیں، کنیتوں میں ذکر ہونا ہے۔ بقول بعض: ان کا نام افلح ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۲۶) استیعاب (۲۸۳۸) تجرید (۱۴۲/۲)\n(2) سورۃ الانعام (۵۲)"}],[7959,"§۹۳۴۸ ۔ یسار (بے نسبت)\nابو داؤد طیالسی اپنی مسند میں فرماتے ہیں: جسر بن فرقد، سلیط بن عبد اللہ بن یسار کے سلسلہ سند سے مروی ہے، فرمایا: میرے دادا نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔"],[7960,"§۹۳۴۹ ۔ یسار ابو برہ\nمولا عبد اللہ بن السائب المخزومی۔ بقول ابن قانع: امام بخاری رحمہ اللہ نے ان کا نام لیا ہے، یہ المزنی القاری کے دادا ہیں، کنیتوں میں تذکرہ ہوگا۔"],[7961,"§۹۳۵۰ ۔ یسار مولی عثمان الثقفی\nابن فتحون نے ان کا ذکر کیا ہے کہ طائف کے قلعہ سے رسول اللہ صلی اللہ علیہ وسلم کی طرف اتر آئے تھے، مسلمان ہوئے آپ نے آزاد کر دیا۔ واقدی نے ان کا ذکر کیا ہے۔"],[7962,"§۹۳۵۱ ۔ یسار مولیٰ آل عمر\n(1) ابن عمیر الثقفی۔ مستغفری نے طائف کے غلاموں میں سے نکلنے والوں میں ان کا ذکر کیا ہے کہ آپ نے انہیں آزاد کر دیا۔ بعد میں انہوں نے بنی عقیل میں شادی کر لی۔ حجاج(2) کے گورنر ہیں، نوے(۹۰) سے زیادہ اولادیں ہوئیں۔\nمیں کہتا ہوں: احتمال ہے پہلے والے ہوں۔","",{"fn":"(1) اسد الغابہ (۵۶۲۸) تجرید (۱۴۲/۲)\n(2) اسد الغابہ (۳۵۸/۴)"}],[7963,"§۹۳۵۲ ۔ یاسر\n(1) مولیٰ فضالہ بن ہلال۔ ابن مندہ نے مسلم کے والد سے انہیں رلا ملا دیا ہے اور ابو عمر(2) نے دونوں میں فرق کیا ہے کہ انہوں نے اور ان کے مولا نے نبی صلی اللہ علیہ وسلم سے بیعت کی، یہی درست لگتا ہے۔ کیونکہ ان کا نسب مزنی بتاتے ہیں۔ چنانچہ ابو بکر بن ابی شیبہ عن عبد اللہ بن موسیٰ عن عبد اللہ بن مسلم بن یسار المزنی عن ابیہ عن جدہ روایت کی ہے کہ میں اپنے مولا فضالہ بن ہلال کے ساتھ حجۃ الوداع کے لیے نکلا۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۲۵) استیعاب (۲۸۳۷) تجرید (۱۴۲/۲)\n(2) استیعاب (۱۴۵/۴)\n(3) اتحاف السادۃ (۳۵۲/۵)"}],[7964,"§۹۳۵۳ ۔ یُسیر بن جابر العتکی\nابن شاہین نے یہاں ان کا ذکر کیا ہے، حرف باء میں تذکرہ ہو چکا ہے۔"],[7965,"§۹۳۵۴ ۔ یُسیر بن حارث العبسی\n(1) باء میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۲) تجرید (۱۴۳/۲)"}],[7966,"§۹۳۵۵ ۔ یُسیر\nتصغیر ہے، یہ ابن عروہ ہیں اسیر میں ذکر ہوا ہے۔"],[7967,"§۹۳۵۶ ۔ یُسیر بن عمرو\n(1) ابن سیار بن درمکہ، جو سیار کی والدہ ہیں۔ وہ بنت عبد اللہ بن سعید بن مرہ بن ذہل بن شیبان ہیں، رہے ابو یسار تو وہ بنی مزید بن الاحجم بن سعید بن مرہ سے تعلق رکھتے ہیں۔ ابن کلبی نے ان کا ذکر کیا ہے کہ صحابی ہیں، انہیں اسیر بھی کہا جاتا ہے۔ بعض نے انہیں اسیر بن عمرو سے ملا دیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۲۸۴۰) تجرید (۱۴۳/۲)"}],[7968,"§۹۳۵۷ ۔ یَعفر\n(1) بقول بعض: یعفور بن عریب بن عبد کلال الرعینی التقبانی۔ ابن یونس نے ان کا ذکر کیا ہے کہ لوگوں کا گمان ہے فتح مصر میں شریک ہوئے، بحر کے حالات میں لکھتے ہیں: یعفر کو آنے کی سعادت حاصل ہے۔","",{"fn":"(1) تجرید (۱۴۳/۲)"}],[7969,"§۹۳۵۸ ۔ یعقوب بن الحصین\n(1) بقول ابن السکن: ان سے ایک غیر مشہور حدیث مروی ہے۔ ابن ابی خیثمہ، بغوی، ابن قانع، ابن شاہین اور ابن السکن وغیرہ نے بروایت عبد الوہاب بن مجاہد عن ابیہ عن یعقوب بن الحصین روایت کی ہے، فرمایا: مجھے لگتا ہے کہ میں اب بھی رسول اللہ صلی اللہ علیہ وسلم کے رخسار دیکھ رہا ہوں آپ دائیں بائیں سلام پھیر رہے ہیں۔ آپ بلند آواز سے سلام پھیرتے تھے۔ ابو عمر(2)(3) کا بیان ہے، اس میں ابن مجاہد جو ضعیف راوی ہے منفرد ہے۔ یحییٰ بن مخلد نے یہ روایت نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۷) استیعاب (۲۸۴۳) تجرید (۱۴۳/۲)\n(2) جامع المسانید (۴۵۷/۱۲)\n(3) استیعاب (۱۴۷/۴)"}],[7970,"§۹۳۵۹ ۔ یعقوب بن زمعہ الاسدی\n(1) عبد اللہ بن عمرو کی حدیث میں منقطع سند سے ان کا ذکر ملتا ہے۔ فرماتے ہیں: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یہاں کی کسی وادی میں نماز پڑھنا چاہتے تھے۔ آپ کھڑے ہوئے اور ہم بھی کھڑے ہو گئے۔ اتنے میں شعب ابی ذئب سے ایک گدھا نکلا، آپ صلی اللہ علیہ وسلم رک گئے اور تکبیر نہیں کہی اور بنی اسد کے یعقوب بن زمعہ کو اس کی طرف روانہ کیا یہاں تک کہ انہوں نے اسے لوٹا دیا۔ اسے امام احمد رحمہ اللہ نے عن عبد الرزاق عن ابن جریج، عمرو بن شعیب، عن عبد اللہ بن عمرو اسی اسناد سے نقل کیا ہے اور ابن ابی عمر نے عن ہشام ابن سلیمان عن ابن جریج نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۸) تجرید (۱۴۳/۲)"}],[7971,"§۹۳۶۰ ۔ یعقوب القبطی\n(1) مولیٰ بنی فہر۔ ابن یونس نے ان کا ذکر کیا ہے کہ مقوقس نے ماریہ رضی اللہ عنہا کے ساتھ بھیجا تھا۔ بقول بعض: صحابی ہیں۔ ایک قول ہے: جب اسلام لائے تو بنی فہر سے موالات کر لی۔ میں نے سعید بن عفیر کی کتاب میں دیکھا ہے کہ یعقوب الفہری سے مروی ہے، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو دیکھا اور آپ صلی اللہ علیہ وسلم کے ساتھ صبح کی نماز پڑھی میں نے آپ سے زیادہ اچھی کسی کی قراءت نہیں سنی۔ ابن یونس فرماتے ہیں: مجھے یہ حدیث سوائے ابن عفیر کے کسی کی کتاب میں نہیں ملی۔ جسے مجھ سے حسین بن زید نے عن اسد بن سعید عن کثیر بن عفیر نقل کی ہے۔","",{"fn":"(1) تجرید (۱۴۳/۲)"}],[7972,"§۹۳۶۱ ۔ یعقوب القبطی (دوسرے)\n(1) ان کے مولا نے مدبر بنا کر آزاد کر دیا تھا، تو نبی صلی اللہ علیہ وسلم نے انہیں فروخت کر دیا تاکہ ان کا قرض ادا ہو جائے۔ مسلم کی روایت میں جو بطریق ابو الزبیر عن جابر مروی ہے۔ ان کا نام آیا ہے کہ ابو مذکور انصاری نے یعقوب قبطی کو خرید کر پھر مدبر بنا کر آزاد کر دیا (جب ان کی وفات ہوئی تو) نبی صلی اللہ علیہ وسلم نے پوچھا: کیا اس کے علاوہ ان کا کوئی مال ہے؟ لوگوں نے عرض کی: نہیں۔ تو آپ نے انہیں نعیم بن عبد اللہ(2) کے ہاتھ فروخت کر دیا۔ حدیث صحیحین میں ہے اور لیث کی روایت عن ابی الزبیر عن اشیم مروی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۹) تجرید (۱۴۳/۲)\n(2) بخاری کتاب کفارات الایمان باب عتق المدبر و ام الولد والمکاتب فی الکفارۃ و عتق ولد الزنا (۶۷۱۶) مسلم (۵۸)"}],[7973,"§۹۳۶۲ ۔ یعلی بن امیہ\n(1) ابن ابی عبیدہ بن ہمام بن الحارث التیمی الحنظلی، قریش کے حلیف، انہی کو یعلی بن منیہ کہا جاتا ہے، جو ان کی والدہ ہیں۔ بقول بعض: ان کی دادی ہیں جس پہ الدارقطنی نے اعتماد کیا ہے، لکھتے ہیں: وہ منیہ بنت حارث بن جابر، امیہ کی والدہ ہیں۔ یعلی کے والد اور عوام کی والدہ ہیں جو زبیر کے والد ہیں۔ یہ زبیر اور یعلی کی دادی ہیں۔ انہیں روایت حاصل ہے اور ان کا ذکر ملتا ہے ان کی کنیت ابو خلف ہے یا ابو خالد یا ابو صفوان ہے۔ مدائنی عن سلمہ بن محارب عن عوف الاعرابی روایت کرتے ہیں کہ سیدنا ابو بکر نے ارتداد کے فتنہ میں یعلی کو حلوان کا گورنر بنایا، پھر وہ سیدنا عمر رضی اللہ عنہ کی طرف سے یمن کے کسی علاقے کے گورنر رہے۔ وہاں اپنے لیے ایک چراگاہ بنائی تو آپ نے انہیں معزول کر دیا۔ پھر سیدنا عثمان رضی اللہ عنہ کی طرف سے صنعاء یمن کے گورنر مقرر ہوئے۔ اور جس سال شہادت عثمان رضی اللہ عنہ ہوئی حج کیا۔ پھر جنگ جمل میں سیدہ عائشہ رضی اللہ عنہا کا ساتھ دیا اور صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ رہے۔ بقول بعض: اسی میں شہید ہوئے۔\nابن عساکر نے یہ بات ابو حسان الزیادی سے نقل کی ہے لیکن اسے بعید سمجھا ہے۔ نسائی کی روایت سے پتہ چلتا ہے ان کی وفات تاخیر سے ہوئی۔ یعلی بن امیہ سے مروی ہے میں عقبہ بن ابی سفیان کے پاس ان کی آخری گھڑی میں آیا تو انہوں نے بواسطہ جبیب رضی اللہ عنہ مجھ سے حدیث بیان کی۔ خلیفہ وغیرہ کا بیان ہے عقبہ ۴۴ھ میں فوت ہوئے۔ حضور نبی صلی اللہ علیہ وسلم، سیدنا عمر اور عقبہ بن ابی سفیان رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے ان کی اولاد صفوان، عثمان، محمد، عبد الرحمن، پوتے صفوان بن عبد اللہ بن یعلی، عطاء مجاہد وغیرہ روایت کرتے ہیں۔ بقول ابن سعد:(2) حنین، طائف اور تبوک میں شریک ہوئے۔ بقول حاکم نجران پر سیدنا عمر رضی اللہ عنہ کے گورنر مقرر تھے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۰) استیعاب (۲۸۴۴) تجرید (۱۴۴/۲)\n(2) الطبقات الکبریٰ (۴۵۶/۵)"}],[7974,"§۹۳۶۳ ۔ یعلی بن جاریہ ثقفی\n(1) بنی زہرہ بن کلاب کے حلیف۔ ابو عمر(2) نے بحوالہ ابو معشر ان کا ذکر کیا ہے کہ جنگ یمامہ میں شہید ہوئے، لکھتے ہیں: محمد ابن اسحاق نے ان کا نام یحییٰ بن جاریہ بتایا ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۶۴۱) استیعاب (۲۸۴۵) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)"}],[7975,"§۹۳۶۴ ۔ یعلی سیابہ\n(1) وہی ابن مرہ۔ ابو حاتم،(2) ابن قانع اور طبرانی(3) نے دونوں میں فرق کیا ہے۔ ابن حبان کہتے ہیں: جو یعلی بن مرہ کو یعلی ابن سیابہ کہتا ہے اسے وہم ہوا ہے۔ پھر خود لکھتے ہیں: یعلی بن سیابہ۔ بقول بعض: صحابی ہیں۔","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) الجرح والتعدیل (۳۰۱/۹)\n(3) المعجم الکبیر (۲۷۵/۲۲)"}],[7976,"§۹۳۶۵ ۔ یعلی بن مرّہ\n(1) ابن وہب بن جابر بن عتاب بن مالک بن کعب بن عمرو بن سعد بن عوف بن ثقیف ثقفی ابو المرازم۔ یہی یعلی بن سیابہ ہیں۔ سیابہ ان کی والدہ کا نام ہے۔ بقول یحییٰ بن معین: خیبر، بیعت رضوان، فتح مکہ، غزوہ ہوازن اور طائف میں شریک ہوئے۔ بقول ابو عمر:(2) افضل صحابہ رضی اللہ عنہم میں سے تھے۔ نبی صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں۔ سیدنا علی رضی اللہ عنہ سے بھی روایت کرتے ہیں۔ ان سے ان کے دونوں فرزند عبد اللہ اور عثمان، نیز راشد بن سعد سعید بن راشد کے دادا اور عبد اللہ بن حفص بن نہیک وغیرہ روایت کرتے ہیں۔ ابن سعد لکھتے ہیں: نبی صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ ثقیف انگوری باغ کاٹ ڈالیں تو انہوں نے کاٹ دیئے۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۴۴) استیعاب (۲۸۴۷) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)\n(3) جامع المسانید والسنن (۴۷۵/۱۲)"}],[7977,"§۹۳۶۶ ۔ یعلی العامری\n(1) طبرانی، ابن شاہین(2) ابو عمر عسکری نے ان میں اور یعلی بن مرہ ثقفی میں فرق کیا ہے۔ بقول بعض: دونوں ایک ہیں۔ ان کے نسب میں اختلاف ہے۔ حدیث سے ایک ہونے کی تائید ہوتی ہے۔ ابن قانع اور طبرانی(3) کی روایت میں یعلی بن مرہ لکھا ہے۔ ابو عمر کا بیان ہے اس میں اختلاف ہے کہ یعلی بن مرہ ثقفی ہیں یا عامری۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۶۴۳) استیعاب (۲۸۴۸) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)\n(3) المعجم الکبیر (۲۷۳/۲۲)"}],[7978,"§۹۳۶۷ ۔ یَعمَر\n(1) بنی سعد بن ہذیم کے فرد، ابو خزامہ کے والد کسی نے ایک روایت میں ان کا نام بتایا ہے جبکہ اکثر میں مبہم ہے۔ بغوی کی روایت ہے کہ ابو خزامہ بن یعمر بحوالہ اپنے والد نقل کرتے ہیں، انہوں نے عرض کی: اللہ کے رسول! جو دم ہم کرتے ہیں اس کے بارے میں آپ کا کیا ارشاد ہے؟ (حدیث)(2)","",{"fn":"(1) اسد الغابہ (۵۶۴۶) استیعاب (۲۸۵۵) تجرید (۱۴۴/۲)\n(2) ترمذی کتاب الطب باب ما جاء فی الرقی والادویۃ (۲۰۶۵، ۲۱۴۸) ابن ماجہ (۳۴۳۷) المستدرک (۴۰۲/۴) المعجم الکبیر (۲۱۵/۳) مجمع الزوائد (۸۵/۵)"}],[7979,"§۹۳۶۸ ۔ یعیش ذوالغرۃ الجہنی\n(1) اونٹوں کا گوشت کھانے کی وجہ سے وضو کرنے کے بارے میں ان کی ایک حدیث ہے۔ ترمذی نے بلا نام ان کا ذکر کیا ہے جبکہ ابن السکن نے ان کا نام بتایا ہے کہ یعیش جہنی جو ذو الغرۃ سے مشہور ہیں سے مروی ہے ایک دیہاتی آ کر کہنے لگا: کیا آپ اونٹوں کا گوشت کھانے کے بعد وضو کرتے ہیں؟ آپ نے فرمایا: ہاں! ابن شاہین(2) نے اسی سند سے ان کا نام بیان کیا ہے ان کا سیاق اس سے مکمل ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۷) استیعاب (۲۸۵۰) تجرید (۱۴۴/۲)\n(2) مسند احمد (۶۷/۴) (۱۱۲/۵) المعجم الکبیر (۷۰۹/۲۲) مجمع الزوائد (۲۵۰/۱) شرح المعانی (۷۰/۱)"}],[7980,"§۹۳۶۹ ۔ یعیش بن طخفہ الغفاری\n(1) بقول ابن سعد: شامی ہیں۔ مصریوں سے ان کی حدیث روایت کی جاتی ہے۔ پھر بطریق ابن لہیعہ بحوالہ یعیش الغفاری یہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم ایک اونٹنی کے پاس آ کر فرمانے لگے: اس کا دودھ کون دوہے گا؟ تو ایک صاحب اٹھے، آپ نے فرمایا: کیا نام ہے؟ کہا: مرہ۔ فرمایا: بیٹھ جاؤ۔ پھر دوسرا اٹھا تو پوچھا: کیا نام ہے؟ کہا: جمرہ۔ فرمایا: بیٹھ جاؤ، اتنے میں تیسرا شخص کھڑا ہوا، آپ نے فرمایا: کیا نام ہے؟ عرض کی: یعیش۔ فرمایا: دوہو! ابن قانع(2) ایک اور طریق سے عن ابن لہیعہ نقل کر کے سند میں فرماتے ہیں: عن یعیش الانصاری۔ حرب کے سوانح میں اس کے کئی طرق ہیں جو موطا میں منقول ہیں اور بزار نے یہ روایت حدیث بریدہ سے طویل نقل کی ہے۔ یہ یعیش ان یعیش بن طخفہ کے علاوہ ہیں جو اپنے والد سے اور ان سے یحییٰ بن ابی کثیر روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۴۸) استیعاب (۱۵۰/۴) تجرید (۱۴۴/۲)\n(2) المعجم الکبیر (۱۷۱/۲۲) مجمع الزوائد (۴۱/۸) جامع المسانید (۴۹۱/۱۲)"}],[7981,"§۹۳۷۰ ۔ یعیش\n(1) مولیٰ بنی عامر بن لوی۔ ابن الامین نے اپنے ذیل الاستعیاب میں ان کا ذکر کیا ہے کہ عثمانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۴۴/۲)"}],[7982,"§۹۳۷۱ ۔ یعیش\n(1) بنی مغیرہ کے غلام۔ مستغفری نے ان کا ذکر کیا ہے اور بطریق وکیع، سفیان، عن حبیب بن ابی ثابت عن عکرمہ روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم بنی مغیرہ کے ایک عجمی غلام کو قرآن پڑھاتے تھے۔ وکیع فرماتے ہیں: سفیان کا قول ہے: میرے خیال میں اسے یعیش کہا جاتا تھا۔ جس پہ یہ آیت نازل ہوئی: ﴿ہم خوب جانتے ہیں یہ لوگ کہتے ہیں: اسے (محمد صلی اللہ علیہ وسلم کو تو) ایک انسان سکھاتا ہے۔۔۔۔﴾۔ یحنس(2) میں دیکھ لیا جائے شاید وہ یہی ہوں۔","",{"fn":"(1) اسد الغابہ (۵۶۴۹) تجرید (۱۴۵/۲)\n(2) سورۃ النحل (۱۰۳)"}],[7983,"§۹۳۷۲ ۔ یغوث\nایک حدیث میں جسے میں من گھڑت سمجھتا ہوں ان کا ذکر آیا ہے جو میں نے ابن ابی طی کی کتاب طبقات الامامیہ میں پڑھی ہے۔۔۔۔"],[7984,"§۹۳۷۳ ۔ یفودان بن یفد یدویہ\n(1) مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جبکہ محمد نامی حضرات میں ان کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۶۵۰) تجرید (۱۴۵/۲)"}],[7985,"§۹۳۷۴ ۔ الیمان بن جابر\n(1) سیدنا حذیفہ رضی اللہ عنہ کے والد۔ حاء میں ان کا ذکر ہوا ہے کہ ان کا نام حصل ہے اور یمان لقب ہے۔ بقول بعض: یمان سیدنا حذیفہ کے دادا کا لقب ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۵۱) تجرید (۱۴۵/۲)"}],[7986,"§۹۳۷۵ ۔ یَناق\n(1) ابن مندہ نے ان کا ذکر کیا ہے کہ ان کی حدیث علی بن حجر نے عن عمر بن ہارون عن عبد العزیز بن عمر عن الحسن بن مسلم عن جدہ یَناق کی سند سے بیان کی ہے، فرمایا: میں نے حجۃ الوداع میں نبی صلی اللہ علیہ وسلم کو دیکھا۔ آپ سورج ڈھلنے کے بعد لوگوں کو وعظ کہنے کھڑے ہوئے۔(2)","",{"fn":"(1) اسد الغابہ (۵۶۵۲) تجرید (۱۴۵/۲)\n(2) جامع المسانید (۴۹۲/۱۲)"}],[7987,"§۹۳۷۶ ۔ یناق العمانی\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور الدارقطنی نے \"غرائب مالک\" میں نافع مولی ابن عمر کے حالات کے آخر میں بطریق عبد الرحمن بن خالد بن نجیح عن حبیب کاتب مالک روایت کی ہے کہ عمان کے کچھ لوگ امام مالک کے پاس آئے، ان میں صدقہ بن عطیہ بن حماس بن نجبہ بن حمار بن یناق نامی ایک شخص تھا، آپ اس کا احترام کرتے، کسی نے امام مالک رحمہ اللہ سے کہا کہ اس کے پاس چند احادیث ہیں جنہیں وہ بیان کرتا ہے تو مجھے امام مالک رحمہ اللہ نے وہ حدیث لکھنے کا حکم دیا تاکہ میں آپ کے سامنے پیش کروں۔ چنانچہ اس نے مجھے املاء کرایا: حدثنی ابی عطیہ سمعت جدی نجبہ بن حمار یحدث عن جدہ یناق، فرمایا: میں طائف میں اپنے جنگل میں اونٹ چرا رہا تھا، ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کا خط آیا: \"اگر تم لوگ اسلام قبول نہیں کرتے تو جزیہ دو\"۔ پھر لمبی حدیث ذکر کی۔ اس کے آخر میں ہے: وہ سیدنا عمر رضی اللہ عنہ کے پاس اس وقت آئے جب آپ کو نیزہ لگا تھا، چنانچہ آپ کی وفات اور دفن میں شریک ہوئے۔ اور پہلے بیان ہو چکا ہے کہ حجۃ الوداع کے موقع پر مکہ اور طائف میں جو مسلمان باقی رہا وہ اس میں شریک ہوا۔"],[7988,"§۹۳۷۷ ۔ ینّہ الجہنی\nابن السکن نے یہاں ان کا ذکر کیا ہے، باء میں ذکر ہو چکا ہے۔"],[7989,"§۹۳۷۸ ۔ ینّہ الحمراوی\nابن یونس نے ان کا ذکر کیا ہے کہ فتح مصر میں شریک ہوئے اور حمراء کے ناظم تھے، مصر میں انہیں زائد وظیفہ ملتا تھا۔ بقول سعید بن عفیر: عبد الرحمن بن ینّہ کے والد ہیں۔\nمیں کہتا ہوں: فتوحات میں صحابہ رضی اللہ عنہم ہی امیر مقرر ہوتے تھے۔"],[7990,"§۹۳۷۹ ۔ یوسف بن عبد اللہ\n(1) بن سلام بن حارث اسرائیلی۔ بچپن میں نبی صلی اللہ علیہ وسلم کو دیکھا ہے اور آپ کی حدیث یاد رکھی ہے، ان کی حدیث سنن ابو داؤد اور جامع ترمذی میں بطریق یزید بن الاعور مروی ہے۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ نے روٹی کے ٹکڑے پہ کھجور رکھ کر فرمایا: یہ اس کا سالن ہے۔(2) ترمذی(3) میں ایک اور طریق سے بحوالہ ان کے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے میرا نام یوسف رکھا، یوسف اپنے والد، سیدنا عثمان، عمر، علی وغیرہ صحابہ کرام رضی اللہ عنہم سے بھی روایت کرتے ہیں۔ ابن ابی حاتم(4) نے نقل کیا ہے، انہوں نے اپنے والد سے کہا: امام بخاری رحمہ اللہ(5) نے ذکر کیا ہے کہ یوسف صحابی ہیں، تو میرے والد نے فرمایا: نہیں، انہیں رویت حاصل ہے۔ امام بخاری رحمہ اللہ کی بات زیادہ صحیح ہے۔ بغوی کا قول ہے: نبی صلی اللہ علیہ وسلم سے روایت کی ہے اور ابن سعد نے صحابہ رضی اللہ عنہم کے پانچویں طبقے میں ان کا ذکر کیا ہے اور صحابہ رضی اللہ عنہم کے متعلق کتابیں لکھنے والی ایک جماعت نے ان کا ذکر کیا ہے، خلیفہ بن خیاط فرماتے ہیں: خلافت عمر بن عبد العزیز میں فوت ہوئے۔ حاکم کا قول ہے: واقدی نے ان کی کنیت ابو یعقوب بتائی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۵۳) استیعاب (۲۸۵۶) تجرید (۱۴۵/۲)\n(2) ابوداؤد کتاب الاطعمۃ باب فی التمر (۳۸۳۰) شمائل الترمذی (۱۸۲) السنن الکبریٰ (۶۳/۱۰) المعجم الکبیر (۷۳۲/۲۲) مجمع الزوائد (۳۸/۵)\n(3) ترمذی، کتاب المناقب۔۔۔۔\n(4) الجرح والتعدیل (۲۴۰/۹)\n(5) التاریخ الکبیر (۳۷۱/۴)"}],[7991,"§۹۳۸۰ ۔ یوسف بن ہبیرہ\nابن ابی وہب المخزومی، فتح مکہ کے بعد ان کا والد کافر مرا، ان کی والدہ ام ہانی ہیں ان کے بھائی ہانی کے حالات میں ان کا ذکر ہوا ہے کہ انہوں نے اور ان کے بھائیوں نے دور نبوی پایا ہے۔"],[7992,"§۹۳۸۱ ۔ یونس بن شداد الازدی\n(1) ابن ابی حاتم(2) نے ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم سے روایت کی ہے جو بروایت سعید بن بشیر ان کی سند سے ہے جسے عبد اللہ بن احمد نے \"زوائد المسند\" میں بروایت سعید عن قتادہ عن ابی قلابہ عن ابی الشعثاء عن یونس بن شداد نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ایام تشریق (قربانی کے تین دنوں) میں روزہ رکھنے سے منع کیا ہے۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۵۵) استیعاب (۲۸۵۷) تجرید (۱۴۵/۲)\n(2) الجرح والتعدیل (۲۴۰/۹)\n(3) مسند احمد (۷۷/۴) مجمع الزوائد (۳۰۳/۳) شرح المعانی (۲۴۵/۲) جامع المسانید (۴۹۹/۱۲)"}],[7993,"§۹۳۸۲ ۔ یونس بن عبید\nابن اسد بن علاج الثقفی۔ حنفیہ بنت عبید جو زیاد کی والدہ سیدہ سمیہ کی مولاۃ ہیں کے بھائی، نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے یہ فیصلہ فرمایا کہ بچہ اسی کا ہے جس کے پاس وہ بیوی ہے جب یہ زیاد کے استلحاق (ملائے جانے) کے وقت حاضر ہوئے۔ انہوں نے اس کا انکار کیا۔ تو امیر معاویہ رضی اللہ عنہ نے ان سے فرمایا: یا تم باز آ جاؤ گے یا میں تمہاری وجہ سے ایسی بدشگونی لوں گا جس کا پیش آنا دیر سے ہوگا۔ تو یونس(1) نے کہا: صرف اللہ کی طرف پھر میں واقع ہو جاؤں گا؟ انہوں نے کہا: ہاں! اور میں اللہ سے معافی چاہتا ہوں۔ پھر خاموش ہو گئے۔ یہ واقعہ رشاطی نے نقل کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۴۲/۹)"}],[7994,"§۹۳۸۳ ۔ یحییٰ بن ثابت\nابن قیس بن شماس انصاری خزرجی۔ انہیں اپنے بھائیوں کی طرح رویت حاصل ہے، ثابت جنگ یمامہ میں شہید ہوئے تھے۔"],[7995,"§۹۳۸۴ ۔ یحییٰ بن خلاد\n(1) ابن رافع بن مالک بن العجلان الزرقی بقول ابو عمر(2): ان کی احادیث اسحاق بن عبد اللہ بن ابی طلحہ کی کتاب میں عن علی بن یحییٰ بن خلاد عن ابیہ عن جدہ کی سند سے ہیں، کہ: جس دن یہ پیدا ہوئے نبی صلی اللہ علیہ وسلم کے پاس لائے گئے۔ آپ نے کھجور چبا کر دی اور فرمایا: میں اس کا ایسا نام رکھوں گا جو یحییٰ بن زکریا علیہ السلام کے بعد کسی کا نہیں رکھا گیا۔ پھر آپ نے ان کا نام(3) یحییٰ رکھا۔ ہمارے شیخ الشیوخ حافظ صلاح الدین علائی کا قول ہے: مجھے اس کی سند سے نہیں ملی۔\nمیں کہتا ہوں: ابن مندہ نے اس کا ذکر تو کیا ہے لیکن مرسلا۔ چنانچہ بطریق حبان بن ہلال عن ہمام عن اسحاق، حدثنی یحییٰ ابن خلاد، فرمایا: جب میری ولادت ہوئی تو میرے والد مجھے لے کر آئے۔۔۔۔ پھر اس کا ذکر کیا۔ ابو عمر نے وہم سے ان کا نسب کندی بتایا ہے جس کی ابن فتحون نے تردید کی ہے جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۵) استیعاب (۲۷۷۹) تجرید (۱۳۳/۲)\n(2) استیعاب (۱۲۹/۴)\n(3) الطبقات الکبریٰ (۵۲/۵) التاریخ الکبیر (۲۶۹/۴) الجرح والتعدیل (۱۳۹/۹)"}],[7996,"§۹۳۸۵ ۔ یزید بن الاصم\n(1) بن عمرو بن عبید بن معاویہ بن عبادہ بن البکاء بن عامر بن ربیعہ بن عامر بن صعصعہ، الاصم لقب ہے۔ یزید کی والدہ برزہ بنت الحارث الہلالیہ سیدہ ام المومنین میمونہ رضی اللہ عنہا کی بہن ہیں۔ بقول بعض: ان کی ولادت عہد نبی صلی اللہ علیہ وسلم میں ہوئی۔ ابن مندہ نے ان کے متعلق یہی ذکر کیا ہے۔ ابو نعیم فرماتے ہیں: ان کے صحابی ہونے کی بات صحیح نہیں۔ اپنی خالہ سیدہ میمونہ، سیدہ عائشہ رضی اللہ عنہما، ابو ہریرہ، سعد بن ابی وقاص، معاویہ اور ابن عباس رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے دونوں بیٹے عبد اللہ اور عبید اللہ صاحبزادگان عبد اللہ بن الاصم، زہری، ابو فزارہ العبسی، السبعی، قتادہ، میمون بن مہران، جعفر بن برقان وغیرہ روایت کرتے ہیں۔ ابن سعد(2) کا قول ہے، بقول ابن کلبی: نبی صلی اللہ علیہ وسلم نے الاصم کا نام عبد الرحمن رکھا۔ ابن سعد فرماتے ہیں: یزید بکثرت حدیث بیان کرتے۔ ۱۰۳ھ یا ۱۰۴ھ میں فوت ہوئے۔ بقول بعض: ۱۰۱ھ میں وفات پائی۔ واقدی کا بیان ہے: بہتر(۷۳) سال زندہ رہے۔\nمیں کہتا ہوں: اگر یہ روایت صحیح ہے تو پھر انہیں رویت حاصل نہیں۔ اس حساب سے ان کی پیدائش وفات نبویہ سے تقریباً بیس(۲۰) سال بعد ہوئی ہوگی۔","",{"fn":"(1) اسد الغابہ (۵۵۲۱) تجرید (۱۳۴/۲)\n(2) الطبقات الکبریٰ (۴۷۹/۷)"}],[7997,"§۹۳۸۶ ۔ یزید بن امیہ الدؤلی\n(1) ابو سنان الدؤلی۔ سیدنا علی، ابو واقد اللیثی اور ابن عباس رضی اللہ عنہم سے اور ان سے نافع، زہری، زید بن اسلم روایت کرتے ہیں۔ ابو عمر(2) نے صحابہ رضی اللہ عنہم میں ان کا مختصر ذکر کیا ہے۔ غزوہ احد کے سال عین موقعہ پہ پیدا ہوئے۔ ابو حاتم(3) فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئے۔ یہ بات انہوں نے واقدی سے لی ہے ورنہ ثابت نہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۲۲) استیعاب (۲۷۸۷) تجرید (۱۳۴/۲)\n(2) استیعاب (۱۳۲/۴)\n(3) الجرح والتعدیل (۳۰۱/۹)"}],[7998,"§۹۳۸۷ ۔ یعلی بن حمزہ\n(1) ابن عبد المطلب بن ہاشم ہاشمی۔ نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی۔ بقول زبیر: سیدنا حمزہ کی نسل صرف یعلی سے چلی تھی ان کے ہاں چار بیٹے پیدا ہوئے لیکن وہ سب فوت ہو گئے اور کوئی اولاد نہ چھوڑی۔ یوں سیدنا حمزہ بن عبد المطلب کا سلسلہ نسل منقطع ہو گیا۔ ابن سعد(2) کا قول ہے: سیدنا حمزہ کے ہاں یعلی پیدا ہوئے اور انھی کے نام پہ کنیت رکھتے تھے۔ پھر عمارہ ہوئے جن کے نام سے بھی کنیت کرتے تھے اور عامر پیدا ہوئے۔ انہوں نے شادی کی۔ ان کی والدہ ام یعلی اوسیہ انصاریہ ہیں اور عمارہ کی والدہ خولہ بنت قیس ہیں اور یعلی کی اولاد کے نام عمارہ، الفضل، زبیر عقیل اور محمد بتائے، سب فوت ہو گئے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۲) استیعاب (۲۸۴۶)\n(2) الطبقات الکبریٰ (۸/۳)"}],[7999,"§۹۳۸۸ ۔ یحمد الخولانی\nیزید بن محمد کے حالات میں ان کا ذکر ہوگا۔"],[8000,"§۹۳۸۹ ۔ یُحَنّس\nمولی صہیب بن سنان۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے۔ سیدنا صہیب کے سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ واقعے میں صہیب کے حالات میں ان کا ذکر ہوا ہے۔"],[8001,"§۹۳۹۰ ۔ یحییٰ بن یعمر الرعینی\nبقول ابن یونس: فتح مصر میں شریک ہوئے، سیدنا عثمان رضی اللہ عنہ کے خون کا مطالبہ کرنے میں سردار کی حیثیت رکھتے تھے۔"],[8002,"§۹۳۹۱ ۔ یرفا (دربان عمر رضی اللہ عنہ)\nدور جاہلیت پایا ہے اور خلافت صدیقی میں سیدنا عمر رضی اللہ عنہ کے ساتھ حج کیا۔ ابن المبارک نے کتاب الزہد میں اپنی شامی سند سے بحوالہ ابن عمر روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ کو سیدنا یزید بن ابی سفیان رضی اللہ عنہ کی طرف سے یہ خبر ملی کہ وہ رنگ برنگے کھانے کھاتے ہیں تو آپ نے اپنے مولا یرفا سے فرمایا: جب تمہیں پتہ چلے کہ ان کے کھانے کا وقت ہو گیا ہے تو مجھے اطلاع کر دینا۔۔۔۔ پھر ایک واقعہ نقل کیا۔ ابن صاعد لکھتے ہیں: غریب ہے۔ اسے صرف ابن المبارک نے نقل کیا ہے۔ سعید بن منصور، ابو الاحوص عن ابی اسحاق بحوالہ البراء روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے مجھ سے فرمایا: میں اللہ کے مال سے وہی سلوک کرتا ہوں جو یتیم کا سرپرست کرتا ہے۔ جب مجھے ضرورت پڑتی ہے لے لیتا ہوں اور جب فراخی ہوتی ہے واپس کر دیتا ہوں۔ اور جب مجھے اس کی ضرورت نہیں ہوتی تو اس سے بچتا ہوں۔ ابو حنفہ الازدی کا بیان ہے: جب سیدنا عمر خلیفہ مقرر ہوئے تو ابو عبیدہ کی طرف یرفا کو خط دے کر بھیجا۔ تو یہ روانہ ہوئے یہاں تک کہ ابو عبیدہ کے پاس جا پہنچے۔۔۔۔ پھر ایک واقعہ نقل کیا۔\nیرفا کا تذکرہ صحیحین میں سیدنا عباس و علی رضی اللہ عنہما کے رسول اللہ صلی اللہ علیہ وسلم کے زکوۃ کے مال میں جھگڑے والے واقعے میں ملتا ہے اور اس حدیث میں بھی ان کا ذکر ہے جسے ابن ابی شیبہ(1) نے بطریق زہری عن عبد اللہ بن عبد اللہ بن عتبہ عن ابیہ نقل کیا ہے، فرماتے ہیں: میں سیدنا عمر رضی اللہ عنہ کے پاس آیا، آپ اس وقت نماز پڑھ رہے تھے۔ تو آپ نے مجھے اپنی دائیں جانب کھڑا کر لیا۔ میں یرفا آئے تو ہمیں اپنے پیچھے دھکیل دیا۔","",{"fn":"(1) المصنف لابن ابی شیبہ (۵۳۵/۱)"}],[8003,"§۹۳۹۲ ۔ یریم بن عامر\nبن سعد بن ذہل بن الاحدس بن سہل الرعینی۔ دور نبوی پایا ہے، بقول ابن یونس: یہ اور ان کا بھائی عقبہ فتح مصر میں شریک ہوئے۔"],[8004,"§۹۳۹۳ ۔ یریم بن معدیکرب\nابن ابرہہ بن الصباح الاصحی۔ دور نبوت پایا ہے، ان کا نضر نامی ایک بیٹا تھا، بقول ابن کلبی: اپنے دور میں حمیر کے شام میں سردار تھے، ان کے والد بنت معبد بن عباس بن عبد المطلب ہیں۔"],[8005,"§۹۳۹۴ ۔ یزداد الفارسی\n(1) ازواج میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۴) تجرید (۱۳۳/۲)"}],[8006,"§۹۳۹۵ ۔ یزید بن احمد المرادی ثم الزرقی\nبقول ابن کلبی۔ فتح مصر میں شریک ہوئے۔"],[8007,"§۹۳۹۶ ۔ یزید بن الاسود الغسانی\n(1) از بنی ثعلبہ بن کعب بن عمرو۔ ابن کلبی نے نسب قحطان کے آغاز میں ان کا ذکر کیا ہے۔ ابو خنس کنیت تھی۔ یہی یرموک کے زمانہ میں جبلہ بن الایہم کے ساتھ روم میں داخل ہوئے۔ پھر وہاں غسلان سے اپنے ساتھیوں سمیت مسلمان ہو کر لوٹے۔ شام میں ان کا بڑا مرتبہ ہے۔","",{"fn":"(1) تجرید (۱۳۴/۲)"}],[8008,"§۹۳۹۷ ۔ یزید بن الاسود الجُرَشی\n(1) ابو الاسود۔ بقول ابن ابی حاتم(2): دور جاہلیت کے ہیں۔ مسلم فرماتے ہیں: قدیم زمانے کے ہیں۔ ابو عمر(3) لکھتے ہیں: دور جاہلیت پایا ہے اور اہل شام میں شمار ہوتے ہیں۔ ابن مندہ فرماتے ہیں: صحابہ رضی اللہ عنہم میں ان کا ذکر ملتا ہے، جو ثابت نہیں۔ پھر بطریق یونس بن میسرہ روایت کی ہے کہ میں نے یزید بن الاسود سے پوچھا: ابو الاسود! آپ نے کتنا عرصہ گزارا ہے؟ انہوں نے کہا: مجھے وہ زمانہ یاد ہے جب میری قوم عزیٰ کو پوجا کرتی تھی اور امام بخاری رحمہ اللہ(4) نے اسے عن ابی مسہر عن سعید بن عبد العزیز عن یونس نقل کیا ہے اور ابن سعد نے پہلے طبقہ میں ان کا ذکر کیا ہے۔ ابن حبان الثقات میں لکھتے ہیں: سخت(5) حال لوگوں میں سے تھے۔ یہی روایت ابو زرعہ دمشقی اور یعقوب بن سفیان نے اپنی اپنی تاریخ میں بسند صحیح عن سلیم بن عامر نقل کی ہے کہ دمشق میں قحط پڑا تو امیر معاویہ یزید ابن الاسود کے وسیلے سے بارش کی دعا کرنے لگے تو ان لوگوں پہ بارش ہوئی۔\nابو زرعہ فرماتے ہیں: ابو مسہر، سعید بن عبد العزیز کے واسطے سے ہمیں بتاتے ہیں کہ ضحاک بن قیس لوگوں کے ساتھ صلوۃ الاستسقاء پڑھنے نکلے تو یزید بن الاسود سے کہا: اے کثرت سے رونے والے، اٹھیے! اسی سند سے مروی ہے کہ عبد الملک جب مصعب ابن الزبیر کی جانب روانہ ہوا تو اس کے ساتھ یزید بن الاسود تھے۔ ابن ابی الدنیا نے بطریق ہشام بن الغاز، حبان بن النضر کہ مجھ سے واثلہ بن الاسقع نے فرمایا کہ مجھے یزید بن الاسود کے پاس لے چلو، یہ ان کے پاس پہنچے تو وہ آ رہے تھے۔ انہوں نے آواز دی یہ آپ کے بھائی واثلہ ہیں تو انہوں نے اپنا ہاتھ بڑھایا، وہ اسے چومنے لگے، میں نے ان کی ہتھیلی اپنی ہتھیلی میں لے لی جسے وہ اپنے سینے پہ کبھی پھیرتے اور کبھی چہرے پہ۔ واثلہ کی ہتھیلی رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ کی جگہ ہے۔۔۔۔ پھر ایک واقعہ ذکر کیا۔ میرا غالب گمان یہی ہے کہ یہ سابقہ شخص کے علاوہ ہیں۔","",{"fn":"(1) استیعاب (۲۷۸۳) تجرید (۱۳۴/۲)\n(2) الجرح والتعدیل (۲۵۰/۹)\n(3) استیعاب (۱۳۱/۴)\n(4) التاریخ الکبیر (۳۱۸/۴)\n(5) جامع المسانید (۴۱۵/۱۲)"}],[8009,"§۹۳۹۸ ۔ یزید بن اُنیس الہذلی\n(1) دور نبوی پایا ہے۔ فرماتے ہیں: ہم لوگ عہد فاروقی میں مسجد میں قیام کرتے، یہ روایت ان سے مسلم بن جندب نے نقل کی ہے اور امام بخاری رحمہ اللہ نے کتاب خلق افعال العباد میں درج کی ہے۔","",{"fn":"(1) تجرید (۱۳۴/۲)"}],[8010,"§۹۳۹۹ ۔ یزید بن بشر الضبعّی\nبشر بن یزید میں ذکر ہوا ہے۔"],[8011,"§۹۴۰۰ ۔ یزید بن حارث الشیبانی\nدور نبوی پایا ہے اور جنگ یمامہ میں شریک ہوئے۔ جس کے بارے کہتے ہیں: ط \"ہماری چکی عامر کے جھنڈے کے ارد گرد گھوم رہی تھی، وہ ہمیں کھلے میدان میں ملے ہوئے دیکھ رہا تھا، معد کے دونوں رکن ہماری پناہ لے رہے تھے اور ہماری وجہ سے مشارق والے موت کی سختیوں سے بچتے ہیں\"۔ اس کے بعد بصرہ فروکش ہوئے، مرزبانی نے ان کا ذکر کیا ہے۔"],[8012,"§۹۴۰۱ ۔ یزید بن حذیفہ اسدی\n(1) کتاب الردہ میں وثیمہ نے ان کا اور ان کے بیٹے زفر کا اسلام پہ ثابت قدم رہنے والوں میں ذکر کیا ہے۔ وہ بنی اسد کے معزز لوگوں میں سے تھے۔ سیدنا خالد بن ولید سے جا ملے انہوں نے بنی اسد کی طرف انہیں ارتداد سے ڈرانے کے لیے یہ اشعار بھیجے: ط \"بنی اسد! اے میری قوم! طلیحہ میں کوئی ایسی خصلت نہیں جس کی وجہ سے اس کی بات مانی جائے\"۔","",{"fn":"(1) اسد الغابہ (۳۵۲۵) تجرید (۱۳۶/۲)"}],[8013,"§۹۴۰۲ ۔ یزید بن حمزہ المازنی\n(1) حارث بن عوف میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۹) تجرید (۱۳۶/۲)"}],[8014,"§۹۴۰۳ ۔ یزید بن ذی الاخرۃ الیمانی\nوثیمہ نے کتاب الردہ میں ان کا ذکر کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کے حکم سے الاسود العنسی کے بارے میں اشعار کہے تھے، اس بارے میں وہ اسود کے قتل کے بعد کہتے ہیں: ط \"تیرے بقاء کی قسم! ہم عبدان کے دن برکت والے حسیوں کی جماعت تھے نہ کہ کمینے۔ جس صبح ہم نے ایک وار سے عنس میں ناک کاٹ ڈالی اس کے ذریعے مکشوح نے ہمام کا سر جدا کر دیا\"۔"],[8015,"§۹۴۰۴ ۔ یزید بن رناب الاسلمی\nبقول ابن یونس: یہ اور ان کا بھائی فتح مصر میں شریک ہوئے۔"],[8016,"§۹۴۰۵ ۔ یزید بن السجّوح التجیبی العامری\nابن یونس کا بیان ہے: فتح مصر میں شریک ہوئے۔ بحری جنگ کے امیر مقرر ہوئے۔ یہ معصومہ میں طحاوی گلی کی مسجد والے ہیں۔"],[8017,"§۹۴۰۶ ۔ یزید بن شریک\n(1) ابن طارق التیمی الکوفی الفقیہ ابراہیم کے والد۔ کوفہ کے رہائشی تھے۔ سیدنا عمر، علی، ابوذر، ابن مسعود، حذیفہ وغیرہ صحابہ رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے ان کا بیٹا ابراہیم، ابراہیم نخعی، حکم بن عیینہ وغیرہ روایت کرتے ہیں۔ بقول ابن سعد(2): اپنی قوم کے ناظم تھے۔ بقول ابو موسیٰ: بتایا جاتا ہے دور جاہلیت پایا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۰) تجرید (۱۳۸/۲)\n(2) الطبقات الکبریٰ (۷۰/۶)"}],[8018,"§۹۴۰۷ ۔ یزید بن ضرار الاسدی\n(1) الشماخ میں ذکر ہوا ہے۔ یہ مزد ابو ضرار بقول ابو الحسن سے مشہور ہیں۔ الشماخ کے بھائی ہیں، بڑے تھے۔ مرزبانی(2) لکھتے ہیں: اسلام کا زمانہ پایا تو مسلمان ہو گئے، اپنے اس قصیدے میں کہتے ہیں جس کا مطلع ہے: ط \"دل سلمیٰ سے صاف ہو گیا اور اب طعنہ زن بھی کم ہو گئے ہیں\"۔ اسی میں کہتے ہیں: ط \"لوگوں کو خوب معلوم ہے کہ میں گزشتہ زمانے میں جب جری اور طعنہ زن کوشش کرتا تو میں ہی خطیب ہوتا، سردار ہوتا جسے بدکے ہوئے اونٹوں کے ذریعے پھینک دیتے۔ جنہیں ساتھ چلنے والے گاتے اور سواریوں کی حدی خوانی کی جاتی جس پر ان میں سے کسی ایک شعر کو تو پھینکے گا اسے واضح کر دے گا جسے چہرے کے قتل ہوئے اور مٹکوں کو دھو کے والا کوئی نہیں\"۔","",{"fn":"(1) تجرید (۱۳۸/۲)\n(2) معجم الشعراء (۴۸۲)"}],[8019,"§۹۴۰۸ ۔ یزید بن عبد اللہ\nالاحرم بن شعبہ بن حزم بن رویبہ بن عبد اللہ بن ہلال العامری ثم الہلالی، ہوزم میں ام المومنین سیدہ میمونہ رضی اللہ عنہا کے ہم نسب ہو جاتے ہیں۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے، بنی مروان کے دور میں ان کے بیٹے عبد اللہ بن یزید کا ذکر ہے، ان کا پوتا عاصم بن عبد اللہ ابن یزید، اسد بن عبد اللہ القسری کے پاس خراسان آیا تو اس نے انہیں قید کر لیا جس پہ اشعار کہے: ط \"تمہارے دوست قمری نے تمہیں قمر کے قریب کر دیا، ودوتی کی بنا پر جس چیز کے قریب کر دیا وہ بہت بری ہے\"۔ ابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے، حمص کے رہائشی تھے۔"],[8020,"§۹۴۰۹ ۔ یزید بن عمرو الریاحی\nشاعر اخوص سے مشہور تھے۔ مرزبانی معجم الشعراء میں لکھتے ہیں: مخضرمی ہیں، ابن قسوہ شاعر عیینہ بن مرداس کے ساتھ ان کا ایک واقعہ ہے۔ ابو بشر الآمدی نے ان کا نام زید بتایا ہے۔"],[8021,"§۹۴۱۰ ۔ یزید بن عمیرہ الزبیدی\n(1) بقول بعض: کندی/کلبی۔ حمص کے رہائشی تھے، بقول ابن سمیع: دور جاہلیت پایا ہے۔ ابن سعد رحمہ اللہ(2) لکھتے ہیں: سیدنا ابو بکر و عمر رضی اللہ عنہما سے ملے اور معاذ بن جبل کے ساتھ رہے۔ سیدنا معاذ، ابن مسعود رضی اللہ عنہما سے روایت کرتے ہیں ان سے ابو ادریس الخولانی، عطیہ بن قیس، ابو قلابہ، اور معبد الجہنی روایت کرتے ہیں۔ عجلی لکھتے ہیں: اکابر تابعین میں سے ہیں۔ ابو مسہر کا قول ہے: سیدنا معاذ کے تلامذہ کے سردار مالک بن ہبیرہ تھے اور یزید بن عمیرہ ان کے سرداروں میں سے تھے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۷) تجرید (۱۳۹/۲)\n(2) الطبقات الکبریٰ (۳۵۲/۲)"}],[8022,"§۹۴۱۱ ۔ یزید بن قیس\n(1) ابن تمام بن مسعود بن کعب بن علوی بن علیان بن ارحب بن عامر بن مالک بن معاویہ۔۔۔۔ ہمدانی ارحبی۔ دور نبوت پایا ہے۔ اور ان کے سردار تھے۔ مجالد بن سعید نے کہا: جب سعید بن عاص روانہ ہوئے جو سیدنا عثمان رضی اللہ عنہ کی طرف سے کوفہ کے امیر تھے تو اہل کوفہ نے ان پہ دھاوا بول دیا۔ تو وہ سیدنا عثمان رضی اللہ عنہ کی طرف روانہ ہو گئے۔ کوفہ کے تمام قریش اکٹھے ہوئے اور ان یزید بن قیس کو اپنا امیر بنا لیا۔ پھر سیدنا علی رضی اللہ عنہ کی جنگوں میں ان کا ساتھ دیا، انہوں نے اپنا محافظ بنا لیا۔ پھر اصبہان، رے، اور ہمدان کا والی مقرر کر دیا۔ اس کے بعد شاعر امیر معاویہ کو مخاطب کر کے انہی سے مراد لیتا ہے: ط \"معاویہ! اگر آپ ہماری طرف آنے میں جلدی نہ کریں تو سیدنا علی رضی اللہ عنہ سے بیعت کر لیں یا یزید یمانی سے\"۔ بقول ابن کلبی: اس شعر کا شاعر ثمامہ ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[8023,"§۹۴۱۲ ۔ یزید بن قیس\nابن عبد اللہ بن قیس ابن عبد اللہ بن معاویہ بن الشیطان بن بکر بن کوف بن الحج انحی۔ دور نبوت پایا ہے۔ ان کا بیٹا عبد اللہ ابن یزید سیدنا علی رضی اللہ عنہ کے طرفداروں میں سے تھا۔ اور کوفہ میں فوت ہوا تو سیدنا علی رضی اللہ عنہ نے جنازہ پڑھایا۔ ہشام بن کلبی نے ان کا ذکر کیا ہے۔"],[8024,"§۹۴۱۳ ۔ یزید بن قیصم البہزی\nدور نبوی صلی اللہ علیہ وسلم پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔ مورخین نے اپنی کتابوں میں ان کا ذکر کیا ہے۔"],[8025,"§۹۴۱۴ ۔ یزید بن قنان\nاز بنی مالک بن سعد۔ سیف نے فتوح میں لکھا ہے کہ جب سیدنا عکرمہ رضی اللہ عنہ بن ابی جہل نے فتنہ ارتداد میں اپنے ساتھیوں کو ادھر ادھر تقسیم کیا تو انہیں کندہ بھیجا۔ طبری نے ان کا ذکر کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ واللہ اعلم"],[8026,"§۹۴۱۵ ۔ یزید بن قیس\n(1) ابن یزید بن الصعق۔ یہ لقب ہے ان کا نام عمرو بن حارث بن خویلد بن نوفل بن عمرو بن کلاب بن ربیعہ الکلابی ہے۔ بقول بعض: الصعق خویلد کا لقب ہے۔ مرزبانی نے ان کے دادا یزید بن الصعق کا ذکر کیا ہے اور ان کے بنی تمیم کی ہجو میں بیان کردہ اشعار نقل کیے ہیں کہ وہ نعمان بن المنذر کے دور میں تھے۔ رہے یزید بن قیس تو ان کی کنیت ابو المحتار ہے۔ ان کا مرزبانی نے ذکر کیا ہے اور لکھا ہے انہوں نے بحرہ کے گورنروں کی شکایات پر مشتمل ایک قصیدہ تیار کیا جو سیدنا عمر رضی اللہ عنہ تک پہنچ گیا۔ تو خالد بن غلاب نے دیا۔ اور ندائی نے عن علی بن حماد و حکیم بن حفص وغیرہ نقل کیے ہیں۔ لوگوں کا کہنا ہے: ابو المحتار یزید بن قیس بن الصعق نے ایسی بات کی جس میں اھواء وغیرہ کے گورنروں کی سیدنا عمر بن خطاب رضی اللہ عنہ سے شکایت کی ہے: ط \"امیر المومنین کو میری طرف سے یہ پیام پہنچا دو کہ آپ امر و نہی میں اللہ کے امین ہیں۔ آپ ہم میں اللہ کے امین ہیں اور جو رب العرش کا امین ہو میرا سینہ اس کے تابع ہے۔ آپ رسا تیق اور گاؤں والوں کو نہ چھوڑیئے گا۔ جو اللہ کے مال کو چپڑے اور بہتان میں بہاتے ہیں۔ آپ حجاج کی طرف پیام بھیج کر اس کا حساب جانچیئے، اسی طرح جزاء اور بشری کی طرف حکم بھیجیے! اور دونوں نافع کو ہرگز نہ بھولیے گا۔ اور نہ ابن غلاب کو جو بنی نصر کے سرداروں میں سے ہے، ان میں سے عاصم کی تھوڑی توجہ نہیں۔ اور جو بازاروں میں ہے وہ بنی بدر کا مولا ہے نعمان کی طرف خط بھیج کر اس کا حساب بھی دیکھئے۔ اور بنی غزوان کے داماد کی بے شک مجھے اطلاع ہے اور شبل کی طرف اس کے مال کے بارے میں پوچھے۔ اور ابن محرش کیونکہ اہل رساتق میں انہی کا بڑا ذکر ہے۔ آپ ان سے مقاسمہ کیجئے۔ میری جان آپ پہ فدا! اگر آپ نے آدھو آدھ تقسیم کی تو راضی ہو جائیں گے آپ مجھے گواہی کے لیے نہ بلائیے گا کیونکہ میں غائب رہتا ہوں، لیکن میں زمانے کے عجائبات دیکھتا ہوں جب یہ لوگ واپس ہوتے ہیں ہم بھی واپس ہوتے ہیں اور جب یہ جہاد کرتے ہیں ہم بھی شریک ہوتے ہیں\"۔ مرزبانی نے چند اشعار پر اکتفا کیا ہے اور آخر میں ایک تیرا شعر زائد نقل کیا ہے: ط \"جب ہندوستانی تاجر مشک لے کر آتا ہے تو آپ دیکھیں گے کہ ان کی مانگوں سے بہہ رہی ہوتی ہے\"۔ تو سیدنا عمر رضی اللہ عنہ نے ان لوگوں سے مقاسمہ کیا، ان کا آدھا مال ضبط کر لیا یہاں تک کہ ایک جوتا ضبط اور ایک چھوڑ دیا۔ ان لوگوں میں ابو بکرہ بھی تھے۔ کہنے لگے: میں نے کسی کام میں کوئی کوتاہی نہیں کی۔ آپ نے فرمایا: تمہارا بھائی بیت المال اور اونٹوں کا عشر لینے پہ مامور ہے وہ تمہیں مال دیتا ہے جس سے تم تجارت کرتے ہو۔ چنانچہ ان سے دس ہزار لیے۔ بقول بعض: ان کا بھی آدھا مال لے لیا۔ راوی کا بیان ہے۔ جس حجاج کا انہوں نے ذکر کیا ہے وہ ابن عتیک ثقفی ہیں اور وہ فرات پہ مامور تھے۔ اور جزاء بن معاویہ احنف کے چچا جو سرف پر مقرر تھے۔ بشر بن المحبر باب سابور کے لشکروں کے نگران تھے۔ دو نافع سے مراد، ابو بکر نفع اور نافع بن حارث بن خلدہ جو ان کے بھائی ہیں۔ اور ابن غلاب خالد بن حارث جن کا تعلق بنی دھمان بن نصر بن معاویہ بن بکر بن ھوازن سے تھا وہ اصبہان میں بیت المال پر مامور تھے۔ اور عاصم بن قیس بن الصلت مناذر پر تھے اور بازار پر سمرہ بن جندب تھے جو سوق الاھواز پر مامور تھے۔ نعمان بن عدی بن نضلہ، بقول بعض: فضیلہ بن عبد العزیٰ بن حرثان بنی عدی بن کعب کے فرد جو دجلہ کے ضلع کے عامل تھے۔ انہیں نے کہا تھا: ط \"حناء کو کوئی یہ پیام پہنچانے والا ہے کہ اس کا خاوند اور بنی غزوان کا داماد مجاشع بن سعد سلمی ہیں\"۔ ان کے عقد میں بنت عتبہ بن غزوان تھیں۔ وہ بصرہ کی زکوۃ وصولی پر مامور تھے۔ اور شبل بن معبد الجبلی الا حمسی، غنیمتیں وصول کرنے پر مقرر تھے۔ اور ابن محرش ابو مریم کثفی، رامہر مز پر فرات کے پل پر مقرر تھے۔ مرزبانی کا قول ہے: خالد بن غلاب نے انہیں جواب دیتے ہوئے کہا: ط \"ابو المحتار کو بتا دو میں نہ تمہارا رشتہ دار ہوں اور نہ داماد، میرا مال کسی ویران حکومت سے حاصل نہیں ہوا جسے تم شعروں میں شامل کرنے لگو\"۔ اسی قصیدے میں چند اشعار یہ ہیں: ط \"دار الحفاظ آگے رکھی ہوئی چیزیں کھانے کی تھیں جنگ کے دن فرما رواؤں کے لیے، اسل اور کیکر، بھری ہوئی نیزوں کی زیادتی کو بھلا دے، میں ان چیزوں سے تیری کفایت سفید اثر والی چیز سے اپنی طرف سے کر دوں گا\"۔","",{"fn":"(1) معجم الشعراء (۴۸۰)"}],[8027,"§۹۴۱۶ ۔ یزید بن محمد\nیزید بن محمد کے حالات میں ذکر ہوا ہے۔"],[8028,"§۹۴۱۷ ۔ یزید بن مر\nعلی بن عبدوؤ بن امد بن کعب الصائد بن شر حبیل بن عمرو بن جشم بن صاعد المحمد انی ثم الصائدی۔ ان کا بیٹا محمد، ابن الحنفیہ کے ساتھیوں میں سے تھا۔ مختار بن ابی عبید کی جنگوں میں اس کے ساتھ تھا۔ ابن کلبی نے یہ بات نقل کی ہے۔"],[8029,"§۹۴۱۸ ۔ یزید بن معاویہ\n(1) ابن عبید بن رؤاس بن کلاب بن ربیعہ بن عامر بن صعصعہ الرؤاسی۔ ابو داؤد شاعر بقول مرزبانی(2) مخضرمی ہیں: ط \"کبھی تو تم سلسلہ بحال رکھتے ہو اور کبھی توڑ دیتے ہو، سب سے برا دوست مقلون المراج ہے\"۔ ابن کلبی رحمہ اللہ نے ان کے بارے میں شاعر سے زیادہ کچھ نہیں کہا۔","",{"fn":"(1) اسد الغابہ (۵۶۰۱)\n(2) معجم الشعراء (۴۸۴)"}],[8030,"§۹۴۱۹ ۔ یزید بن مُغفل\nابن عوف بن عمیر بن کلب العامری۔ نسب ان کے بھائی زہیر کے حالات میں بیان ہو چکا ہے۔ دونوں نے دور نبوی صلی اللہ علیہ وسلم پایا ہے اور دونوں ہی جنگ قادسیہ میں شہید ہوئے۔ (ابن کلبی) اور مرزبانی نے یزید بن مغفل کا ذکر کیا اور ان کا یہ شعر نقل کیا ہے جب وہ حسین بن علی رضی اللہ عنہ کی طرف سے لڑ رہے تھے اور اسی گھڑی شہید ہوئے۔ \"اگر تم مجھے نہیں جانتے تو میں ابن المغفل ہوں جنگوں میں اسلحے سے لیس پیچھے نہ ہٹنے والا، میرے دائیں ہاتھ میں آوھی تیز دھار تلوار ہے جسے میں گھر سوار پر جنگ کے درمیان میں چلا دیتا ہوں\"۔ یا تو یہ دو ہیں یا ان کے شہید ہونے کی جگہوں میں سے ایک کے بارے میں قول غلط ہے۔"],[8031,"§۹۴۲۰ ۔ یزید بن ملجم المرادی\nعبد الرحمن کے بھائی۔ دور نبوی پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔"],[8032,"§۹۴۲۱ ۔ یزید بن ناجیہ اللخمی\nاز بنی بحر بن سوادہ ان میں صاحب شرافت تھے۔ دور نبوی پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔ سیدنا ابوذر رضی اللہ عنہ سے روایت کرتے ہیں ان سے یزید بن عمرو الغافری روایت کرتے ہیں۔"],[8033,"§۹۴۲۲ ۔ یزید بن نعیم\n(1) ابن شجرہ بن یزید التجیبی ثم الایدعانی، دور نبوت پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے اور گنے چنے شہسواروں میں سے ایک تھے۔","",{"fn":"(1) تجرید (۱۴۱/۲)"}],[8034,"§۹۴۲۳ ۔ یزید بن یحمد الہمدانی\n(1) عبد خیر کے والد۔ ابو عمر نے ان کے بیٹے کے سوانح میں ان کا ذکر کیا ہے۔ اور بروایت عبد الملک بن سلع نقل کیا ہے، فرماتے ہیں: میں نے عبد خیر سے کہا: ابو عمارہ! آپ بہت بوڑھے ہو گئے آپ کی کتنی عمر ہو گئی ہے؟ انہوں نے کہا: ایک سو بیس(۱۲۰) سال۔ میں نے کہا: کیا آپ کو دور جاہلیت کی کوئی بات یاد ہے؟ انہوں نے فرمایا: ہاں! مجھے یاد ہے کہ میری والدہ نے ہنڈیا پکائی، میں نے کہا: ہمیں کھانا دیجئے! کہنے لگیں ابا کو آ لینے دو، اتنے میں میرے والد صاحب آ گئے۔ وہ کہنے لگے: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کا خط آیا ہے۔ آپ ہمیں مردار کا گوشت کھانے سے منع کر رہے ہیں۔ چنانچہ ہم نے وہ ہنڈیا انڈیل دی۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں اسی طرح نقل کیا ہے۔ اور ابو یعلی نے بروایت عبد الملک، ابن فتحون فرماتے ہیں: یہ روایت ابو عمر نے ان کے بیٹے عبد خیر کے حالات میں شامل کی ہے۔ یہ ان کی شرط کے مطابق ہیں پھر ان کا الگ نہیں ذکر کیا۔\nمیں کہتا ہوں: لیکن انہوں نے \"یزید بن محمد\" کہا ہے تحریف میں بدل دیا، یہ تو محمد ہیں۔ بقول بعض: یہ عبد الرحمن بن محمد ہیں۔ شاید کسی نے ان کے دادا کے نسب سے ایسا ذکر کر دیا ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[8035,"§۹۴۲۴ ۔ یسار\nحسن بن ابی الحسن البصری کے والد۔ دور نبوی نصیب ہوا ہے۔ خطیب بطریق ابی الحنا عن ابی عائشہ روایت کرتے ہیں کہ یسار اہل یمان سے تھے۔ گرفتار ہوئے اور کسی انصاری کے گھر جا پہنچے۔ یہ انصار کے مولا ہیں خلافت فاروقی کے اخیر دور میں ان کے ہاں حسن پیدا ہوئے۔"],[8036,"§۹۴۲۵ ۔ یسار المطلبی\nمولی قیس بن مخرمہ۔ یہ صاحب مغازى محمد یسار کے دادا ہیں۔ ابو بکر بن المقرئ نے اپنے فوائد میں بطریق محمد بن اسحاق روایت کی ہے کہ مجھ سے صالح بن کیسان نے بیان کیا کہ خالد بن الولید روانہ ہو کر \"عین التمر\" پہ فروکش ہوئے۔ وہاں جنگ کی اور لوگوں کو قیدی بنایا۔ قیدیوں میں سیر بن ابی عمرہ اور عبد مولی بلقین، حمران بن ابان، افلح مولی ابی ایوب، اور یسار مولی قیس بن مخرمہ بھی تھے۔ یہ اھل خلافت صدیقی کے آغاز کا واقعہ ہے۔"],[8037,"§۹۴۲۶ ۔ یسار بن نمیر\n(1) سیدنا عمر رضی اللہ عنہ کے خزانچی۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے اور سیدنا عمر رضی اللہ عنہ سے روایت کا شرف رکھتے ہیں۔ ان سے ابو وائل، شقیق بن سلمہ وغیرہ روایت لیتے ہیں۔ ابن سعد(2) نے طبقات میں سیدنا عمر رضی اللہ عنہ کے حالات میں بروایت ابو عاصم الغطفانی، بحوالہ یسار بن نمیر حدیث نقل کی ہے کہ \"میں نے جب بھی سیدنا عمر رضی اللہ عنہ کے آٹا چھانا، تو آپ مجھ سے ناراض ہوئے\"۔ اور ہم عباس(3) الترقی کے رسالہ میں بطریق غیلان بن جریر عن ابی اسحاق عن یسار بن نمیر مولی عمر روایت کی ہے، فرمایا: سیدنا عمر رضی اللہ عنہ جب پیشاب کے لیے بیٹھتے تو مجھے فرماتے: کوئی چیز دے دو، تو میں آپ کو لکڑی یا پتھر دیتا ورنہ آپ کسی دیوار والے باغ کے قریب آ جاتے۔ بلاذری کی روایت ہے، یسار فرماتے ہیں: مجھ سے سیدنا عمر رضی اللہ عنہ نے فرمایا: ہمارا حج میں کتنا خرچ ہوا۔۔۔۔ پھر ایک واقعہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۱۴۵/۴) تجرید (۱۴۲/۲)\n(2) الطبقات (۳۱۹/۳)\n(3) التاریخ الکبیر (۴۲۰/۴) الجرح والتعدیل (۳۰۷/۹)"}],[8038,"§۹۴۲۷ ۔ یُسیر بن عمرو\n(1) اسیر میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۲۸۴۰) تجرید (۱۴۳/۲)"}],[8039,"§۹۴۲۸ ۔ یعقوب بن عمرو\nدور نبوت پایا ہے۔ خلافت صدیقی میں اجنادین میں شہید ہوئے۔ یہ بات میں نے تاریخ مظفری میں دیکھی ہے۔ پھر ازدی کی فتوح الشام میں مل گئی۔ ان کا تذکرہ ان کے والد عمرو بن ضریس کے حالات میں بھی ہوا ہے۔ ابو اسماعیل ازدی کا قول ہے: واقعہ اجنادین میں سات مشرک قتل کیے۔ انہیں ایک نیزہ لگا، چار یا پانچ ایام تک زندہ رہے پھر زخم بہہ پڑا۔ سیدنا ابو عبیدہ سے اپنے اہل و عیال کے ہاں جانے کی اجازت چاہی، انہوں نے اجازت دے دی تو وہیں وفات پائی۔"],[8040,"§۹۴۲۹ ۔ یعفور بن حسان الذہلی\nدور نبوی پایا ہے اور فتح قادسیہ میں شریک ہوئے۔ سیدنا سعد رضی اللہ عنہ نے سیدنا عمر رضی اللہ عنہ سے ان کے بارے میں بیان کیا کہ میں نے یعفور جیسا آدمی نہیں دیکھا وہ ایک دن پانچ گھر سواروں کو لے آئے ان میں سے ایک آدمی کو ایسا داو دیا یہاں تک کہ اس پہ تیروں کی بوچھاڑ کر دی، پھر پوری طرح اس پر غلبہ پا کر اسے مسلمان کر کے لے آئے۔"],[8041,"§۹۴۳۰ ۔ یعلی بن عمیرہ\nابن یعمر بن حارثہ بن العبید۔۔۔۔ انہدی۔ دور نبوت نصیب ہوا، فتوحات عراق میں سے قادسیہ میں سیدنا سعد رضی اللہ عنہ کے ساتھ شریک ہوئے۔ پھر صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ بقول ابن کلبی بنی نہد کا جھنڈا انہی کے ہاتھ میں تھا۔"],[8042,"§۹۴۳۱ ۔ ینّاق العمانی\n(1) دور نبوی پایا ہے۔ الدار قطنی نے \"غرائب مالک\" میں ان کی حدیث بطریق عبد الرحمن بن خالد بن نجیح عن حبیب کاتب مالک روایت کی ہے کہ عمان کے کچھ لوگ حج کر کے امام مالک کے پاس آئے۔ ان میں صدقہ بن عطیہ بن حماس بن نجبہ بن حمار بن یناق تھا۔ امام مالک رحمہ اللہ اس کا بڑا اکرام کرتے بلند مقام پر بٹھاتے، پھر مجھے حکم دیا کہ میں اس سے وہ حدیث نقل کروں جو وہ بیان کرتا ہے اور پھر امام مالک رحمہ اللہ کے سامنے پیش کروں۔ چنانچہ اس نے مجھے املا کرایا: حدثنی ابی عطیة بن حماس قال سمعت جدی نجبہ بن حمار یحدث عن جدہ یناق۔ فرماتے ہیں: میں اپنے گھر والوں کے اپنے جنگل میں اونٹ چرا رہا تھا، ہمارے پاس نبی صلی اللہ علیہ وسلم کا خط آیا کہ مسلمان ہو جاؤ، تو میری قوم نے انکار کر دیا۔ آپ نے ان کی طرف اپنے نیک آدمی بھیجے، پھر ہمیں رسول اللہ صلی اللہ علیہ وسلم کی وفات کی اطلاع ملی۔ تو میری قوم جو پہلے ادا کرتی تھی وہ ابو بکر کی طرف بھیج دی، میں نے اپنی قوم سے کہا: مجھے سوار کر کے سیدنا عمر رضی اللہ عنہ کے پاس بھیج دو تو انہوں نے نہ مانا۔ یہاں تک کہ ان میں سے بعض لوگوں نے میرے اونٹ لے لیے، میں اپنی سواری پر بیٹھ کر مدینہ کی طرف چل پڑا۔۔۔۔ پھر ایک لمبا واقعہ ذکر کیا۔ اس میں ہے: سیدنا عمر رضی اللہ عنہ پہ قاتلانہ حملہ ہوا، فرماتے ہیں: میں مدینہ میں داخل ہوا، پھر سیدنا عمر رضی اللہ عنہ کے گھر آپ کے آخری لمحات میں ان لوگوں سے اپنی ملاقات کا ذکر کیا، جس کی لمبی حدیث ہے۔\nحبیب کہتے ہیں: میں امام مالک کے پاس آیا، آپ نے وہ تحریر پڑھ کر فرمایا: اسی مفہوم کی روایت مجھ سے نافع نے بحوالہ ابن عمر رضی اللہ عنہ بیان کی ہے۔ پھر وہ شیخ امام مالک رحمہ اللہ کے پاس آیا، آپ نے اس کا اکرام کیا تو آپ کی مجلس میں اس نے وہ حدیث بیان کی۔ پھر ان سے وہ واقعہ نقل کیا جس میں سیدنا علی رضی اللہ عنہ کا سیدنا عمر رضی اللہ عنہ سے ام کلثوم بنت علی بن نعیم کے بارے اختلاف ہوا، یہاں تک کہ سب کا اس پہ اتفاق ہوا کہ وہ سیدہ حفصہ بنت عمر کے پاس قیام کریں گی۔۔۔۔ الدار قطنی فرماتے ہیں: اس میں حبیب عن صدقہ عن مالک روایت کرنے میں منفرد ہیں، اس کے بعد فرماتے ہیں: حبیب محدثین کے نزدیک ضعیف ہیں۔","",{"fn":"(1) تجرید (۱۴۵/۲)"}],[8043,"§۹۴۳۲ ۔ یحییٰ بن سعید\n(1) ابن عاص۔ درمیانہ درجے کے تابعی ہیں۔ ذیل میں ابو موسیٰ لکھتے ہیں: ابو داؤد نے السنن میں عن الشعی عن مالک عن یحییٰ بن سعید الانصاری عن القاسم بن محمد و سلیمان بن یسار روایت کی ہے، دونوں فرماتے ہیں کہ یحییٰ بن سعید بن عاص نے بنت عبد الرحمن کو طلاق بائن دے دی تو عبد الرحمن انہیں لے گئے۔ سیدہ عائشہ رضی اللہ عنہا نے مروان بن الحکم کی طرف پیام بھیجا وہ اس وقت مدینہ کے گورنر تھے: کہ اللہ سے ڈرو! اور عورت کو اس کے گھر لوٹا دو۔۔۔۔ (حدیث)(2)\nابن الاثیر(3) فرماتے ہیں: یہ یحییٰ، عمرو بن سعید الاشدق کے بھائی ہیں۔ نہ یہ دونوں صحابی ہیں اور نہ دونوں کو دور نبوی ملا ہے۔ کیونکہ ان کے والد سعید بن عاص ہجرت کے سال پیدا ہوئے اور یحییٰ ان کے بڑے بیٹے بھی نہیں۔ بہر صورت یہ صحابی نہیں۔ تو ابو موسیٰ کو کیسے شبہ ہو گیا؟\nیہ حدیث بخاری میں بھی عن اسماعیل عن مالک مروی ہے اس میں بنت عبد الرحمن بن الحکم کو طلاق دی۔ اور بطریق عبد الرحمن ابن القاسم عن ابیہ نقل کی ہے کہ عروہ نے سیدہ عائشہ رضی اللہ عنہا سے کہا: خالہ جان! آپ نے اس عورت کو دیکھا ہے جسے اس کے خاوند نے طلاق دے دی ہے، پھر بھی وہ چلی گئی ہے، اس کے بارے آپ کیا کہتی ہیں؟ آپ نے فرمایا: اس نے بہت برا کیا۔ لگتا ہے اس روایت میں اپنے دادا کے نسب سے ذکر ہوئی ہیں اور ان کے خاوند کا نام نہیں لیا گیا۔ جو یحییٰ بن سعید ہیں جن کا ابھی ذکر ہوا ہے۔ اور یحییٰ(4) ..........","",{"fn":"(1) اسد الغابہ (۵۵۰۶) تجرید (۱۳۲/۲)\n(2) بخاری کتاب الطلاق باب فاطمۃ بنت قیس (۵۳۲۱، ۵۳۲۲) ابو داؤد (۲۲۹۵) موطا مالک (۱۲۶۰)\n(3) اسد الغابہ (۴۲۸/۴)\n(4) چار لفظوں کے بقدر جگہ خالی ہے۔"}],[8044,"§۹۴۳۳ ۔ یحییٰ بن صیفی\n(1) چھوٹے تابعی ہیں۔ کوئی حدیث مرسل بیان کی ہے جس کی وجہ سے یحییٰ بن یونس نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا۔ اور بطریق ابراہیم بن یزید، الجوزی، عن یحییٰ بن صیفی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: آدمی کی سعادت ہے کہ اس کا بیٹا اس کے مشابہ ہو۔(2) مستغفری صحابہ رضی اللہ عنہم میں ان کا ذکر کرنے کے بعد فرماتے ہیں: یہ روایت مرسل ہے اور یحییٰ کا صحابی ہونا مشہور ہے۔\nمیں کہتا ہوں: ان کی ایک اور مرسل حدیث بھی ہے جسے ابو سعید بن الاعرابی نے اپنے \"معجم\" میں بروایت السائب بن عمر مخزومی عن یحییٰ بن صیفی نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس پہ کوئی احسان ہوا ہو تو اس پہ لازم ہے کہ وہ اس کا بدلہ دے اگر ایسا نہ کر سکے تو تعریف کر دے، اگر ایسا بھی نہ کیا تو اس نے کفران نعمت کیا۔ بعض نے یہ امکان ظاہر کیا ہے کہ یہ یحییٰ بن عبد اللہ بن صیفی ہیں جن کی حدیث صحیح میں بروایت ان کے عن ابی سعید مولی ابن عباس رضی اللہ عنہما بحوالہ ان کے مروی ہے۔ لگتا ہے ان دونوں صحیح حدیثوں میں اپنے دادا کے نسب سے ذکر ہوئے۔ بقول ابن سعد رضی اللہ عنہ ثقہ تھے ان کی روایت سے کئی احادیث مروی ہیں، ابن حبان نے ثقہ تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۷) تجرید اسماء الصحابۃ (۱۳۳/۲)\n(2) جامع المسانید والسنن (۴۰۹/۱۲)"}],[8045,"§۹۴۳۴ ۔ یحییٰ بن عبد الرحمن\n(1) ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا اور بطریق شعبہ بحوالہ یحییٰ بن عبد الرحمن روایت کی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اسعد بن زرارہ کو داغ لگایا، ان سے غلطی ہوئی یہ تو عن عمہ یحییٰ بن اسعد بن زرارہ مروی ہے جیسا کہ پہلے بیان ہوئی۔","",{"fn":"(1) تجرید (۱۳۳/۲)"}],[8046,"§۹۴۳۵ ۔ یحییٰ بن ابی کریم\nتابعی ہیں، مرسل حدیث بیان کی جس کی وجہ سے کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا۔ عسکری لکھتے ہیں: ان کی روایت مرسل ہے۔"],[8047,"§۹۴۳۶ ۔ یحییٰ بن ہانی\n(1) ابن عروہ المرادی۔ چھوٹے تابعی ہیں۔ کوئی مرسل حدیث بیان کی ہے جس کی وجہ سے ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور بطریق ابن کلبی بحوالہ یحییٰ بن ہانی بن عروہ المرادی روایت کی ہے فرمایا کہ فروہ بن مسیک کندہ کے بادشاہوں سے الگ ہو کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔۔۔۔ پھر وہ حدیث(2) ذکر کی۔\nمیں کہتا ہوں: ان کے والد ہانی بن عروہ مخضرمین میں شامل ہوتے ہیں۔ حرف ہاء میں ان کا ذکر ہو چکا ہے یحییٰ کو سیدنا انس، نعیم بن وجاج اور ابو حذیفہ وغیرہ حضرات سے روایت کرنے کا شرف حاصل ہے۔ ان سے شعبہ، ثوری، شریک اور ابو بکر بن عیاش وغیرہ روایت کرتے ہیں۔\nابو حاتم رازی(3) لکھتے ہیں: ثقہ، صالح ہیں۔ اہل کوفہ کے سرداروں میں سے ہیں۔ ابن حبان نے معتبر ثقہ تابعین میں ان کا شمار کیا ہے، یحییٰ بن بکیر بحوالہ شعبہ نقل کرتے ہیں۔ اپنے دور میں کوفہ والوں کے سردار تھے۔ نسائی وغیرہ نے انہیں ثقہ لکھا ہے۔ ان کی حدیث سنن کی تینوں کتابوں میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۱) تجرید (۱۳۳/۲)\n(2) البدایۃ والنہایۃ (۷۱/۵)\n(3) الجرح والتعدیل (۱۹۵/۹)"}],[8048,"§۹۴۳۷ ۔ یزید بن ابی اوفی\n(1) درست نام زید ہے، حرف زاء میں پہلے بیان ہو چکا ہے۔","",{"fn":"(1) تجرید (۱۳۵/۲)"}],[8049,"§۹۴۳۸ ۔ یزید بن جاریہ\nابن قانع نے ان کا ذکر کیا ہے اور ابن الدباغ نے ابن عبد البر کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے، جو ان کا وہم ہے۔ کیونکہ ابن عبد البر نے ان کا درست نام ذکر کیا ہے، وہ لکھتے ہیں: یزید بن سیف یا یوسف، ان کے دادا کا نام نہیں لکھا، جس سے ابن الدباغ سمجھے انہوں نے ان کا ذکر نہیں کیا اور ابن قانع نے ان کے دادا کے نسب سے ذکر کیا ہے اور بغوی، ابن السکن اور طبرانی(1) نے ان کا صحیح نسب لکھا ہے اور جیسا پہلے بیان ہوا ان کی حدیث نقل کی۔","",{"fn":"(1) المعجم الکبیر (۲۴۵/۲۲)"}],[8050,"§۹۴۳۹ ۔ یزید بن جاریہ\n(1) ابن عامر بن العطاف۔ ابن شاہین نے ان کا ذکر کیا ہے اور ان سے پہلے یزید بن جاریہ ابن مجمع بن العطاف کا ذکر کر چکے ہیں، دونوں ایک ہیں۔ یہی ابن جاریہ بن عامر بن مجمع بن العطاف ہیں جیسا کہ قسم اول میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۰) تجرید (۱۳۵/۲)"}],[8051,"§۹۴۴۰ ۔ یزید بن جاریہ\n(1) دوسرے، قریب ہی یزید بن خارجہ بن عامر میں ذکر ہوگا۔","",{"fn":"(1) استیعاب (۲۷۹۲) تجرید (۱۳۵/۲)"}],[8052,"§۹۴۴۱ ۔ یزید بن حُصین\n(1) ابن نمیر الکوفی الحمصی۔ صغار تابعین میں سے ہیں۔ خلافت یزید بن عبد الملک ۱۰۳ھ میں فوت ہوئے۔ سلیمان بن عبد الملک نے انہیں حمص کا پھر حضرت عمر بن عبد العزیز نے گورنر مقرر کیا تھا۔ جب مروان بن الحکم مصر داخل ہوئے تو یہ ساتھ تھے، ان کے والد حسین بن نمیر کو مسلم بن عقبہ المری نے واقعہ حرہ کے بعد اس لشکر کا امیر بنایا جس نے خلافت یزید بن معاویہ میں مدینہ نبویہ پر چڑھائی کی۔ پھر حسین نے مکہ پہ حملہ کیا اور ابن زبیر رضی اللہ عنہ کا محاصرہ کر لیا۔ اتنے میں انہیں یزید بن معاویہ(2) کی موت کی اطلاع مل گئی۔ حسین صحابی نہیں چہ جائیکہ ان کا بیٹا۔ جس کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا تو ایک صحابی کے ساتھ اشتباہ کی وجہ سے جن کا نام اور ان کے والد کا نام ایک جیسا ہے جن کا قسم اول میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۷) تجرید (۱۳۶/۲)\n(2) التاریخ الکبیر (۳۲۶/۴) جامع المسانید (۴۲۴/۱۲) الطبقات الکبریٰ (۲۹۳/۴)"}],[8053,"§۹۴۴۲ ۔ یزید بن حنظلہ\nحدیث ابراہیم میں ان کا ذکر آتا ہے جو ابراہیم بن عبد الاعلی عن جدتہ عن ابیھا یزید بن حنظلہ کی سند سے مروی ہے کہ ہم سفر پہ نکلے، ہمارے ساتھ وائل بن حجر تھے۔ انہیں ان کے دشمن نے پکڑ لیا، ان لوگوں نے تم کھائے بغیر نہ چھوڑا۔ تو انہوں نے اللہ کی قسم کھائی کہ یہ میرا بھائی ہے۔ (حدیث)(1) اسے بغوی نے عن ہارون الحمال عن یزید بن ہارون بحوالہ ان کے نقل کیا: یزید، اور دوسری بار کہا: سوید بن حنظلہ، انہیں اس میں شک ہے۔\nمیں کہتا ہوں: امام احمد رحمہ اللہ(2) نے اسے عن یزید بلا شک عن سوید نقل کیا ہے، یہی قول بغوی کا ہے۔ یزید کے علاوہ لوگوں نے اسے اسرائیل سے نقل کیا ہے۔\nمیں کہتا ہوں: وہ روایت ابو داؤد اور ابن ماجہ وغیرہ میں کئی طرق سے عن اسرائیل اسی طرح مروی ہے۔ یزید کا اس میں ذکر کرنا وہم ہے۔","",{"fn":"(1) ابو داؤد کتاب الایمان باب المعاریض فی الیمین (۳۲۵۶) ابن ماجہ (۲۱۱۹) مسند احمد (۷۹/۴)\n(2) مسند احمد (۱۱۸/۴)"}],[8054,"§۹۴۴۳ ۔ یزید بن خارجہ انصاری\nابن فتحون نے بحوالہ بغوی ان کا اپنے استدراک میں ذکر کیا ہے، جو لفظی غلطی سے پیدا ہونے والا وہم ہے۔ بغوی فرماتے ہیں: سوید بن معاویہ عن عثمان بن حکیم عن خالد بن سلمہ عن موسیٰ بن طلحہ عن یزید بن خارجہ انخزرجی کی سند سے ہم سے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: ہم آپ پہ کیسے درود بھیجا کریں۔۔۔۔ (حدیث)(1) درست زید ہے، اسی روایت کو بغوی نے وہاں دو طریق سے بحوالہ عثمان نقل کیا ہے۔ اسی طرح بطریق عیسیٰ بن یونس عن عثمان مسند احمد اور نسائی میں ہے۔ اور ابن ابی عاصم نے بطریق عیسیٰ نقل کی تو ہے لیکن انہوں نے خارجہ بن یزید کہا جو الٹ ہے۔ اس میں سوید کو ایک اور وہم ہوا ہے چنانچہ ابو نعیم نے بطریق مطین بحوالہ ان کے نقل کیا ہے، فرمایا: یزید بن حارثہ۔ ان کے والد کا نام بدل دیا، درست خارجہ ہے۔ واللہ اعلم","",{"fn":"(1) نسائی کتاب السہو باب نوع آخر (۱۲۸۶، ۱۲۸۷، ۱۲۸۸)"}],[8055,"§۹۴۴۴ ۔ یزید بن حمیر العرنی\nسیدنا معاویہ رضی اللہ عنہ کی امارت میں حمص فروکش ہوئے۔ ابن شاہین نے ان کا ذکر کیا ہے جو ان کا وہم ہے۔ اس واسطے کہ یہ مشہور تابعی ہیں۔ ان کے سب سے بڑے شیخ ابو درداء رضی اللہ عنہ ہیں۔ امام بخاری، ابن ابی حاتم اور ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔"],[8056,"§۹۴۴۵ ۔ یزید بن سَلَمہ\n(1) بغوی نے ان کا ذکر کیا ہے اور بطریق سعید بن مسروق عن ابن اشوع عن یزید بن سلمہ روایت کی ہے کہ میں نے عرض کی: اللہ کے رسول! میں نے آپ کی بہت سی احادیث سنی ہیں مجھے خدشہ ہے میں انہیں بھول نہ جاؤں۔۔۔۔ (حدیث)(2) بغوی لکھتے ہیں: میرے خیال میں یہ جعفی کے علاوہ ہیں۔\nمیں کہتا ہوں: اسے ابن مندہ نے بطریق ابن اشوع نقل کیا تو کہا: عن یزید بن سلمہ الجعفی اور ترمذی نے اسی طرح روایت کی ہے۔ قسم اول میں درست نام بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۴) استیعاب (۱۳۷/۴) تجرید (۱۳۷/۲)\n(2) جامع المسانید (۴۲۹/۱۲) المعجم الکبیر (۲۴۲/۲۲) التاریخ الکبیر (۳۴۰/۴)"}],[8057,"§۹۴۴۶ ۔ یزید بن صحار\n(1) ابو بکر بن علی نے ان کا ذکر کیا ہے اور بطریق اسماعیل بن عیاش عن ابن خثیم عن جعفر بن یزید بن صحار العبدی عن ابیہ مرفوع روایت کی ہے: ٹھیکری، مٹکے اور درخت کے چھید میں (بنا) کوئی مشروب نہ پیا جائے۔(2)\nمیں کہتا ہوں: اسماعیل سے نقل کرنے والے کسی راوی سے غلطی ہوئی ہے، یہ تو زید ہیں، ابن مندہ نے ایک اور طریق سے عن اسماعیل نقل کیا تو فرمایا: عن جعفر بن زید عن ابیہ جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۳) تجرید (۱۳۸/۲)\n(2) جامع المسانید (۴۳۴/۱۲)"}],[8058,"§۹۴۴۷ ۔ یزید بن طلحہ\n(1) ابن رکانہ۔ بقول المستغفری: یحییٰ بن یونس شیرازی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق مالک(2) عن سلمہ بن صفوان۔ بحوالہ ان کے مرفوع روایت کی ہے: \"ہر مذہب کے اوصاف ہوتے ہیں، دین اسلام کا وصف خاص حیاء ہے\"۔ بغوی لکھتے ہیں: یہ مرسل روایت ہے اور یہ یزید، محمد بن طلحہ بن رکانہ مشہور تابعی کے بھائی ہیں۔ ابن ابی حاتم(3) فرماتے ہیں: اپنے والد اور محمد ابن الحنفیہ سے روایت کرتے ہیں۔ ابن حبان ثقات التابعین میں ان کا ذکر کرتے ہیں کہ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں، ہشام بن عبد الملک کی خلافت کے آغاز میں فوت ہوئے۔ ابن عبد البر لکھتے ہیں: امام مالک رحمہ اللہ کے تمام تلامذہ کا کہنا بھی یہی ہے، صرف ایک وکیع کہتے ہیں: عن یزید بن طلحہ عن ابیہ انہوں نے عن ابیہ کا اضافہ نقل کیا ہے۔ لکھتے ہیں: یحییٰ بن یحییٰ اللیثی کی روایت جمہور کی طرح ہے۔ انہوں نے یزید کی جگہ زید کہا۔ ابن عبد البر فرماتے ہیں: بقول وکیع حدیث مسند ہے۔ اور خود استیعاب میں طلحہ کا ذکر نہیں کیا۔ جس کا ان پہ ایک اور تعاقب ہے۔ اس واسطے کہ دار قطنی نے جو روایت غرائب مالک میں بطریق وکیع نقل کی ہے وہ عن مالک عن سلمہ عن یزید بن رکانہ عن ابیہ ہے۔ اس بنا پر صحابی رکانہ ہوئے۔ دار قطنی فرماتے ہیں: اسے علی بن زید الصدرائی نے عن مالک اسی طرح نقل کیا ہے، لیکن یزید بن طلحہ بن رکانہ کہا۔","",{"fn":"(1) اسد الغابہ (۵۵۶۶) تجرید (۱۳۸/۲)\n(2) موطا مالک کتاب حسن الخلق (۱۷۲۵)\n(3) الجرح والتعدیل (۲۷۳/۹)"}],[8059,"§۹۴۴۸ ۔ یزید بن عبد اللہ بن رکانہ\nابن المطلب المطلسی۔ کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے، جس کی وجہ ایک مرسل حدیث ہے جسے بیہقی نے \"الدعوات\" میں بطریق ابراہیم بن المندر عن الحسن بن زید عن جعفر بن محمد عن ابیہ عن یزید بن عبد اللہ بن رکانہ بن المطلب کی سند سے نقل کیا ہے۔ فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی جنازہ لایا جاتا تو آپ فرماتے: اے اللہ! یہ تیرا بندہ تیرے بندے کا بیٹا تیری رحمت کا محتاج ہے۔۔۔۔ (الحدیث)(1)","",{"fn":"(1) المعجم الکبیر (۲۷۷/۸) المصنف لعبد الرزاق (۶۴۲۰)"}],[8060,"§۹۴۴۹ ۔ یزید بن عبد اللہ بن الشخیر\n(1)(2) ابو العلاء اکابر تابعین میں سے ایک، ابو موسیٰ ذیل میں لکھتے ہیں: یحییٰ بن عبد الوہاب بن مندہ نے اپنے دادا کی کتاب پہ اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق ہشیم عن یونس بن عبید عن یزید بن عبد اللہ بن الشخیر روایت کی ہے۔ میرے خیال میں انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ جو کچھ بندے کو عطا کرتا ہے اس میں اس کی آزمائش کرتا ہے، اگر وہ راضی رہے تو اسے برکت دیتا ہے اور اگر ناراض ہو تو برکت اٹھا لیتا ہے۔(3)\nکسی کا یہ کہنا ہے کہ میرے خیال میں انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے، غلط ہے، اس واسطے کہ امام بخاری رحمہ اللہ نے اپنی تاریخ میں(4) نقل کیا ہے کہ یہ حضرت حسن بصری سے دس سال پہلے پیدا ہوئے اور حضرت حسن بصری کی ولادت خلافت فاروقی کے آخر میں ہوئی۔ لہذا یزید کی ولادت خلافت صدیقی میں ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۵۷۴) تجرید (۱۳۹/۲)\n(2) التاریخ الکبیر (۳۴۵/۴) جمع الجوامع (۵۱۶۳) جامع المسانید (۴۳۸/۱۲) الجرح والتعدیل (۲۷۴/۹)\n(3) الطبقات الکبریٰ (۱۵۵/۷)\n(4) التاریخ الکبیر (۳۴۵/۴)"}],[8061,"§۹۴۵۰ ۔ یزید بن عبد الرحمن\n(1) ابو نعیم نے ان کا ذکر کیا اور یہ مرفوع روایت نقل کی ہے: اپنے غلاموں کا خیال رکھو! اپنے غلاموں کے بارے میں احتیاط برتو!۔۔۔۔ (حدیث)(2) ابو نعیم فرماتے ہیں: بقول بعض: یہ یزید بن جاریہ۔ ابن الاثیر(3) نے فرمایا: یہ بلاشبہ وہی ہیں۔ مذکورہ حدیث ان کے حالات میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۸) تجرید (۱۳۹/۲)\n(2) مسند احمد (۳۶/۴) المعجم الکبیر (۲۴۲/۲۲) مجمع الزوائد (۲۳۶/۴) کنز العمال (۲۵۰۱۳)\n(3) اسد الغابہ (۳۴۷/۴)"}],[8062,"§۹۴۵۱ ۔ یزید بن عبد المزنی حجازی\n(1) ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور ابن ماجہ نے بطریق ایوب بن موسیٰ بحوالہ ان کے مرفوع روایت کی ہے: \"لڑکے کی طرف سے عقیقہ کیا جائے گا\"۔(2) یہ یزید تابعی ہیں۔ امام بخاری رحمہ اللہ فرماتے ہیں: انہوں نے تو یہ حدیث عن ابیہ عن النبی صلی اللہ علیہ وسلم روایت کی ہے، نیز ان کے والد کے صحابی ہونے کا ثبوت نہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۸۰)\n(2) ابن ماجہ کتاب الذبائح باب العقیقۃ (۳۱۶۶) فتح الباری (۵۹۴/۹) کنز العمال (۴۵۲۸۵) جامع المسانید (۴۳۷/۱۲)"}],[8063,"§۹۴۵۲ ۔ یزید بن عبید السلمی ابو وجزہ\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور بطریق ابن ابی ذئب عن عبد اللہ بن محمد بن عمرو بن حاطب عن ابی وجزہ یزید بن عبید روایت کی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک سے واپس ہوئے تو آپ کے پاس بنی فزارہ کا وفد آیا، جن میں خارجہ ابن حصین اور حارث بن قیس تھے۔ جو سب سے کم سن تھے۔ یہ لوگ رملہ بنت حارث کی حویلی میں فروکش ہوئے۔ یہ مرسل ہے ابو وجزہ تابعی ہیں جو سعدی سے مشہور ہیں۔ واقدی نے مغازی میں یہ حدیث اسی سند سے نقل کی تو اس کے سیاق میں کہا: عن ابی وجزہ السعدی۔ مرزبانی نے مبرد سے نقل کیا ہے: ابو وجزہ اصلاً سلمی ہیں، انہیں سعدی اس وجہ سے کہا جاتا ہے کہ وہ بنی سعد میں فروکش ہوئے تھے۔\nمیں کہتا ہوں: حدیث ان کے مراسیل سے مذکور ہے اور ابو وجزہ کی یہ حدیث السنن میں عن عمرو بن ابی سلمہ المخزومی پروردہ نبی صلی اللہ علیہ وسلم موجود ہے۔ مشہور شاعر ہیں، مدینہ کے رہائشی تھے اور وہیں ۱۳۰ھ میں فوت ہوئے۔"],[8064,"§۹۴۵۳ ۔ یزید بن عمر\n(1) مستغفری نے انہیں صحابہ رضی اللہ عنہم میں شمار کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو عمر نے ان کا ذکر تو کیا ہے لیکن کہا: یزید بن عمرو، میں نے اس بارے میں اختلاف قسم اول میں بیان کر دیا ہے۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[8065,"§۹۴۵۴ ۔ یزید بن عمرو\n(1) مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ایوب عن میمون بن مہران روایت کی ہے: میری طرف ابن عمر رضی اللہ عنہما نے خط بھیجا۔ رسول اللہ صلی اللہ علیہ وسلم کا سیدہ میمونہ رضی اللہ عنہا سے نکاح کے بارے میں یزید بن عمرو سے پوچھو! میں نے ان سے پوچھا تو انہوں نے فرمایا: \"آپ نے حل (حرم سے باہر) میں ان سے نکاح کیا تھا\"۔(2)\nمیں کہتا ہوں: یہ یزید وہی یزید بن الاصم ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے۔ قسم ثانی میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۵) تجرید (۱۳۹/۲)\n(2) مسلم کتاب النکاح باب تحریم نکاح المحرم (۴۸) ابو داؤد (۱۸۴۳) ترمذی (۸۴۵) ابن ماجہ (۱۹۶۴) سنن الدارمی (۳۸/۲)"}],[8066,"§۹۴۵۵ ۔ یزید بن کعب\n(1) بقول بعض: یہ ان بہری کا نام ہے جن کا ذکر حدیث عمیر بن سلمہ الضمری میں ملتا ہے۔ جن کا تذکرہ ان کے حالات میں ہو چکا ہے۔ ابن عبد البر(2) نے ان کا ذکر کیا ہے۔ درست زید ہے جیسا کہ پہلے بیان ہو چکا۔ الدار قطنی وغیرہ نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۵) استیعاب (۱۴۱/۴) تجرید (۱۴۰/۲)\n(2) استیعاب (۱۴۱/۴)"}],[8067,"§۹۴۵۶ ۔ یزید بن محمد\n(1) عبد خیر کے والد۔ اسی طرح ابن فتحون ابن الامین اور ذہبی نے ان کا ذکر کیا ہے، جبکہ درست یزید بن محمد ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[8068,"§۹۴۵۷ ۔ یزید بن المُزَین\n(1) ابن قیس بن عدی بن امیہ انصاری الخزرجی۔ بقول ابو عمر: یہ نام واقدی(2) نے ذکر کیا ہے جبکہ جمہور زید بتاتے ہیں، جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۰۰) استیعاب (۲۸۲۳) تجرید (۱۴۰/۲)\n(2) استیعاب (۱۴۱/۴)"}],[8069,"§۹۴۵۸ ۔ یزید بن معبد\n(1) القیسی الربعی الیمامی۔ جس نے انہیں یزید بن معبد الحنفی الدولی کے علاوہ قرار دیا ہے، اس سے وہم ہوا ہے بلکہ یہ ایک ہی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۰۲) استیعاب (۲۸۲۴) تجرید (۱۴۰/۲)"}],[8070,"§۹۴۵۹ ۔ یزید بن المعتمر النمیری\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے جو ان کا وہم ہے۔ یہ تو یزید بن نمیر ہیں جن کا ابو عمر نے ذکر کیا ہے۔"],[8071,"§۹۴۶۰ ۔ یزید بن نعیم\n(1) ابن ہزال الاسلمی مشہور تابعی۔ ایک مرسل حدیث بیان کی ہے تو الاثیری نے اپنے استدراک میں اور ابن الاثیر(2) نے ان کی خوشہ چینی میں ان کا ذکر کیا ہے جو وہم ہے۔ ان کی حدیث مسند بقی بن مخلد سے شامل کی ہے جو ان کی اپنے والد سے روایت سے مروی ہے۔ امام بخاری،(3) مسلم، ابن ابی حاتم(4) اور ابن حبان وغیرہ نے انہیں تابعین میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۰۹) تجرید (۱۴۱/۲)\n(2) اسد الغابہ (۲۵۲/۴)\n(3) التاریخ الکبیر (۳۶۴/۴)\n(4) الجرح والتعدیل (۲۹۲/۹)"}],[8072,"§۹۴۶۱ ۔ یزید بن نمران شامی\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا جو ان کا وہم ہے ان کی روایت تو عن المنقد بحوالہ اس شخص کے جو نبی صلی اللہ علیہ وسلم کے پاس سے اس وقت گزرا جب آپ تبوک میں نماز پڑھ رہے تھے۔ ابن ابی حاتم(1) فرماتے ہیں: یزید بن نمران نے فرمایا: میں نے تبوک میں ایک پانچ صحابی دیکھا۔ لگتا ہے ابن شاہین نے سمجھا کہ \"لہ صحبتہ\" کی ضمیر یزید کی طرف ہے حالانکہ وہ پانچ شخص کی طرف راجع ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۹۲/۹)"}],[8073,"§۹۴۶۲ ۔ یزید ابو عبد اللہ\n(1) پہلے بیان ہوا یہ غلط ہے۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[8074,"§۹۴۶۳ ۔ یزید\n(1) عبد اللہ انظمی کے والد۔ یہ حدیث \"مصیبت زدہ تو وہ ہے جس نے آگے کوئی اولاد نہیں بھیجی\"۔ انما الرقوب۔۔۔۔ روایت کی ہے۔ اس میں تامل ہے۔ ابن مندہ اور ابن الاثیر(2) نے اسی طرح نقل کیا ہے جو ان کا وہم ہے اس لیے محمد ثمین نے ان کا ذکر کیا ہے وہ یزید بن حصین ہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۷۶) استیعاب (۱۴۲/۴) تجرید (۱۳۹/۲)\n(2) اسد الغابہ (۳۴۷/۴)"}],[8075,"§۹۴۶۴ ۔ یزید ابو ہانی الحنفی\n(1) ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق ہانی بن یزید عن ابیہ روایت کی ہے کہ ان کے بھائی بشر بن معبد و حارث بن ظفر کی لڑائی ہو گئی۔ انہیں ان کا اپنے استدراک میں شامل کرنے سے وہم ہوا کیونکہ یہ تو وہی یزید بن معبد ہیں جن کا ابن مندہ نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۱) تجرید (۱۴۱/۲)"}],[8076,"§۹۴۶۵ ۔ یزید العقیلی\n(1) ایک مرسل حدیث بیان کی ہے جس کی وجہ سے مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور لکھتے ہیں: مجھے ان کا صحابی ہونا معلوم نہیں۔\nمیں کہتا ہوں: ابن ابی حاتم(2) نے جزم سے لکھا ہے کہ ان کی حدیث مرسل ہے جسے بقیہ نے عن نافع بن یزید عن نافع بن سلیمان عن یزید العقیلی نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب میری امت میں ایسے لوگ ہوں گے جن کی وجہ سے اللہ تعالیٰ حدود (ملکی) کو بدر گئے گا\"۔ (حدیث)","",{"fn":"(1) اسد الغابہ (۵۵۶۲) تجرید (۱۳۹/۲)\n(2) الجرح والتعدیل (۳۰۱/۹)"}],[8077,"§۹۴۶۶ ۔ یزید (حکیم کے والد)\n(1) ان کی حدیث حماد بن سلمہ نے عن عطاء بن السائب عن حکیم بن یزید عن ابیہ کی سند سے نقل کی ہے، درست یوں ہے: عن حکیم بن ابی یزید، جیسا کہنیوں میں بھی تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۵۳۸) استیعاب (۲۸۲۹) تجرید (۱۳۶/۲)"}],[8078,"§۹۴۶۷ ۔ یسار بن نُمیر ابو لیلیٰ\n(1) مولا بنی عمرو بن عوف۔ فرضی نے المؤتلف میں ان کا ذکر کیا ہے۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے اور تجرید(2) میں انہی کی خوشہ چینی کی گئی ہے۔ یہ ابو لیلیٰ عبد الرحمن کے والد ہیں، جس نے ان دونوں میں فرق کیا ہے، اس سے وہم ہوا۔ ابو عمر نے ان کے نام میں اختلاف ذکر کیا ہے۔ ان کے متعلق تمام اقوال میں سے ایک قول ہے \"یسیر بن نمیر\" جو امام بخاری(3) اور کا قول ہے جیسا کہ پہلے بیان ہوا ہے۔","",{"fn":"(1) تجرید (۱۴۲/۲)\n(2) تجرید (۱۴۲/۲)\n(3) التاریخ الکبیر (۴۲۰/۴)"}],[8079,"§۹۴۶۸ ۔ یُسیر\nابن عبد اللہ، جھوٹوں میں سے ایک جس نے صحابی ہونے کا دعویٰ کیا ہے۔ حسین بن خارجہ کا گمان ہے اس کی مصر میں اس سے ملاقات ہوئی ہے اس نے اس سے ذکر کیا کہ اس کی عمر تین سو(۳۰۰) سال ہے۔ حافظ ابن عساکر رحمہ اللہ نے \"السباعیات\" میں بطریق حسین بن خارجہ بحوالہ اس کے کئی احادیث نقل کی ہیں۔ ذہبی میزان میں لکھتے ہیں: اس تک کی سند میں ظلمات ہیں۔ میر۔ دو مشہور اشعار میں اس کا ذکر ملتا ہے جس کے مطلع میں حدیث ابن نسطور یسیر اور نعیم ہے۔ وہ نعیم یہی میسر ہے، کچھ ہی دیر بعد نعیم ذکر ہوگا۔"],[8080,"§۹۴۶۹ ۔ الیسع بن المغیرہ المخزومی\nچھوٹے مشہور تابعی ہیں، حاکم نے ان کی حدیث اپنے متدرک میں نقل کی ہے جسے بطریق اسماعیل بن ابی اویس عن محمد بن طلحہ التمیمی عن عبد الرحمن بن ابی بکر بن المغیرہ نقل کیا ہے کہ \"رسول اللہ صلی اللہ علیہ وسلم بازار میں ایک آدمی کے پاس سے گزرے جو بازاری نرخ سے کم بھاؤ پہ اناج بیچ رہا تھا۔۔۔۔\"۔ (حدیث) جس سے حاکم نے سمجھ لیا یہ صحابی ہیں، یہ تو تابعی ہیں۔ حالانکہ ابو داؤد نے مراسیل میں ان کی حدیث بطریق الزبیر بن سعید عن الیسع بن المغیرہ نقل کی ہے کہ خالد بن ولید نے رسول اللہ صلی اللہ علیہ وسلم سے اپنے گھر کی تنگی کی شکایت کی تو آپ نے فرمایا: رونے میں کشادگی اختیار کرو، طبرانی نے اسے المیج مذکور روایت میں عن ابیہ عن خالد بن ولید موصولاً ذکر کیا ہے۔ الیسع کو عطاء بن ابی رباح، محمد بن سیرین وغیرہ سے بھی روایت حاصل ہے۔ ابو حاتم الرازی ان کے بارے میں کہتے ہیں: قوی نہیں۔ جبکہ ابن ابی حاتم(1) اور ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۳۰۸/۹)"}],[8081,"§۹۴۷۰ ۔ یُسیر ابن العنبس انصاری\n(1) ابن الاثیر(2) نے اپنے استدراک میں ان کا ذکر کیا ہے جو ان کا وہم ہے، یہ نام تو نون سے ہے، پہلے درست بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۵) تجرید (۱۴۲/۲)\n(2) اسد الغابہ (۳۶۰/۴)"}],[8082,"§۹۴۷۱ ۔ یُسیر بن یزید انصاری\n(1) بیہقی نے الشعب میں بطریق محمد بن اسحاق البلخی عن عمرو بن قیس عن ابیہ عن جدہ عن خالد روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"احمق محروم ہوا\"۔ پھر بیہقی اپنے شیخ حاکم سے روایت کرتے ہیں کہ قیس کے دادا کا نام یسیر بن یزید انصاری ہے اور ان کی اسانید بہت شتم ہیں، بیہقی نے اپنے شیخ پر اس کی نکیر کی ہے وہ لکھتے ہیں: صحابہ رضی اللہ عنہم میں یسیر بن یزید نامی کوئی بھی نہیں۔ یہ تو یسیر بن عمرو ہیں مخزومی تابعی ہیں۔ پھر مذکورہ حدیث بطریق یعقوب بن سفیان عن ابی سعید الاشج عن عمرو بن قیس انھی الفاظ میں نقل کی ہے۔ مرفوع بیان نہیں کی۔ فرماتے ہیں: ایک موقوف زیادہ صحیح ہے۔ قسم ثالث میں یسیر بن عمرو کا ذکر ہو چکا ہے اس کا اول (پہلا حرف) ہمزہ سے بدل جاتا ہے، حرف الف میں اس کی طرف اشارہ ہوا ہے۔","",{"fn":"(1) استیعاب (۲۸۴۱)"}],[8083,"§۹۴۷۲ ۔ یعقوب بن اوس الثقفی\n(1) مشہور تابعی ہیں۔ بقول بعض: ان کا نام عقبہ ہے۔ ابن ابی خیثمہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، جو وہم ہے۔ بغوی ان کی شبہ عمد کے بارے میں مرفوع روایت کرتے ہیں: بغوی لکھتے ہیں: یہ سند ابی خیثمہ سے شک کے ساتھ ہے اور ہم سے یہ روایت احمد بن ابی خیثمہ نے عن ابیہ بیان کی اس کی یا کسی صحابی سے۔\nمیں کہتا ہوں: ابن ابی خیثمہ اس حدیث کو نقل کرنے کے بعد فرماتے ہیں: یعقوب صحابی نہیں۔ یہ روایت تو انہوں نے عبد اللہ ابن عمرو سے نقل کی ہے۔ اور یہ حدیث ابو داؤد کی کتاب مس بروایت حماد بن یزید و وہیب بن خالد دونوں عن خالد الحذاء عن القاسم بن ربیعہ عن عقبہ بن اوس عن عبد اللہ بن عمرو ودی ہے۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے روز خطاب فرمایا، پھر ایک حدیث ذکر کی۔ اس میں ہے: \"خطا کی دیت شبہ العمد جب تک کوڑوں اور لاٹھی سے مارا گیا ہو سو(۱۰۰) اونٹ ہے ان میں چالیس حاملہ اونٹنیاں رہی ہوں گی\"۔(2) یہی روایت نسائی نے بطریق حماد بن زید نقل کی تو کہا: عن عقبہ بن اوس عن رجل من الصحابہ اور بطریق ابن ابی عدی عن خالد عن القاسم عن عقبہ بن اوس نقل کی رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔۔ پھر وہ حدیث مرسلاً ذکر کی۔ جو بطریق بشر بن المفضل و یزید بن زریخ دونوں عن خالد و وہیب کی روایت جیسی روایت کرتے ہیں لیکن صحابی رضی اللہ عنہ کا نام نہیں لیا۔ اور قاسم کے شیخ کا نام یعقوب بتایا ہے۔ ابو داؤد نے اس میں قاسم بن ربیعہ سے آگے ایک اور اختلاف بھی ذکر کیا ہے۔ آیا یہ عبد اللہ بن عمرو ہیں یا ابن عمر؟ اس لیے کہ قاسم اور ان کے درمیان کوئی نہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۳۶) استیعاب (۲۸۴۲)\n(2) ابو داؤد کتاب الدیات باب فیمن قتل فی عمیاء بین قوم (۴۵۹۱) نسائی کتاب القسامۃ باب من قتل بحجر او سبوط (۴۸۰۳)"}],[8084,"§۹۴۷۳ ۔ یعلی بن حازم الثقفی\n(1) حلیف بنی زہرہ، یمامہ میں شہادت پائی۔ تجرید میں اسی طرح لکھا ہے جو وہم ہے ان کے والد کا نام غلط لکھ دیا ہے یہ تو ابن جاریہ ہیں پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) تجرید (۱۴۴/۲)"}],[8085,"§۹۴۷۴ ۔ یعلی بن صفوان\nابن امیہ، ابن فتحون نے بحوالہ مغازی اموی ان کا اپنے استدراک میں ذکر کیا ہے کہ فتح مکہ کے بعد یعلی بن صفوان بن امیہ اپنے بیٹے کو ہجرت کی بیعت کرانے نبی صلی اللہ علیہ وسلم کے پاس لائے۔ ابن قانع نے بھی اسی طرح نقل کیا ہے جو الٹ ہے اس میں کسی راوی کو وہم ہوا ہے، درست ہے۔ عن مجاہد عن صفوان بن یعلی بن امیہ ہے کہ یعلی اپنے بیٹے کو لائے، اس سے ابن فتحون نے خبردار کیا ہے۔ صفوان ابن یعلی بن امیہ مشہور تابعی ہیں۔"],[8086,"§۹۴۷۵ ۔ یعلی بن طَلق\n(1) ابن قانع نے ان کا ذکر کیا ہے، جو وہم ہے۔ یہ تو علی بن طلق ہیں چنانچہ ابن قانع اپنی سند سے عن جعفر بن عوف عن یحییٰ بن سعید عن محمد بن المنکدر عن یعلی بن طلق مرفوع روایت کرتے ہیں: \"آدمی نماز تو پڑھتا ہے لیکن جو اس کا (اصل) وقت رہ جاتا ہے وہ اس کے اہل و عیال اور مال سے زیادہ افضل ہے\"۔(2)","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) مجمع الزوائد (۲۹۷/۳) السنن الکبریٰ (۱۴۵/۴) کنز العمال (۱۷۳۰۱)"}],[8087,"§۹۴۷۶ ۔ یعلی (بے نسبت)\n(1) ابن قانع نے ان کا ذکر کیا ہے اور بطریق ولید بن مسلم عن سفیان عن عمرو بن یعلی عذابیہ کی سند سے روایت نقل کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور میرے ہاتھ (کی انگلی) میں سونے کی انگوٹھی تھی۔ فرمایا: کیا تم اس کی زکوۃ ادا کرتے ہو؟ میں نے عرض کی: کیا اس کی بھی زکوۃ ہے؟ آپ نے فرمایا: (پھر تو) یہ مونثا انگارہ ہے۔(2)\nمیں کہتا ہوں: یہ یعلی ابن ابی مرہ ہیں جیسا کہ طبرانی نے جب یہ حدیث نقل کی تو اعتماد سے کہا۔ جبکہ درست یہ ہے ان سے روایت کرنے والے عمر جو ہیں وہ اپنے دادا کے نسب عمر بن عبد اللہ بن یعلی بن خضر سے ذکر ہوئے جو مشہور ہیں ان کے اپنے والد سے بحوالہ دادا کئی احادیث ہیں۔ ریا ح ثقفنی کے حالات میں اس متن پر کچھ بحث ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۵) تجرید (۱۴۴/۲)\n(2) مسند احمد (۱۷۱/۴) مجمع الزوائد (۶۶/۳) السنن الکبریٰ (۱۴۵/۴) کنز العمال (۱۷۲۰۱)"}],[8088,"§۹۴۷۷ ۔ یعلی (بے نسبت، دوسرے)\n(1) ابن فتحون نے بحوالہ یحییٰ بن یحییٰ تیمی عن عمرو بن عثمان عن ابیہ عن یعلی، ذیل میں ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ رضی اللہ عنہم ایک تنگ مقام پر پہنچے، جہاں آپ نے انہیں اپنی سواری پہ نماز پڑھائی، سجدہ رکوع اشارے سے تھا، سجدہ کا جھکاؤ رکوع کی بہ نسبت زیادہ تھا۔(2)\nمیں کہتا ہوں: یہ یعلی بھی ابن مرہ ہیں، ترمذی نے یہی روایت نقل کر کے تبصرہ کیا ہے کہ غریب ہے اس میں عمر بن الرماح منفرد ہے اور اسے الدار قطنی نے اسی سند سے نقل کیا تو کہا: یعلی بن امیہ، ہمارے شیخ شرح ترمذی میں شبابہ کی روایت کو ترجیح دی ہے۔ ہر تقدیر و صورت یہ یعلی اور ہیں۔","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) ابو داؤد کتاب الصلاۃ باب التطوع علی الراحلۃ والوتر (۱۲۲۷) نسائی (۱۱۸۸) ابن ماجہ (۱۰۱۸) مسند احمد (۳۲۴/۲)"}],[8089,"§۹۴۷۸ ۔ یوسف الانصاری\n(1) ابن قانع نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منبر پر چڑھ کر فرمایا: \"لوگو! ابو بکر نے مجھے کبھی اذیت نہیں پہنچائی تو تم لوگ بھی اس بات کی وجہ سے ان کا لحاظ کرنا\"۔۔۔۔ (حدیث)(2) ہمارے شیخ الشیوخ العلائی فرماتے ہیں: یہ وہم ہے درست عن سہل بن یوسف بن سہل عن ابیہ عن جدہ ہے، ان کے دادا کا نام سہل بن حنیف ہے۔ ابن قانع نے یہی روایت دوسرے مقام پر بطریق محمد بن یونس عن خالد بن عمرو و ثق نقل کیا ہے۔ علائی فرماتے ہیں: یہ زیادہ مناسب ہے۔\nمیں کہتا ہوں: اسے ابن عساکر نے پہلے کی طرح نقل کیا ہے، جبکہ زکریا بن یحییٰ نے عن سلیمان بن داؤد عن خالد بن عمر عن سہل بن یوسف بن سہل بن مالک عن ابیہ عن جدہ اسی طرح زعفرانی نے عن زکریا نقل کیا ہے۔ خلیعات میں ہمیں بطریق ابی سعید الاعرابی عن الزعفرانی لکھی ملی ہے۔","",{"fn":"(1) تجرید (۱۴۵/۲)\n(2) المعجم الکبیر (۱۲۶/۶) کنز العمال (۳۳۱۳۹) (۳۵۶۴۵) لسان المیزان (۴۲۴/۳) (۷۱۹/۴) مختصر تاریخ دمشق (۱۲۹/۶)"}],[8090,"§۹۴۷۹ ۔ یونس انصاری ظفری ابو محمد\n(1) بقول ابن مندہ اہل مدینہ میں شمار ہوتے ہیں۔ ابن شاہین نے ان کا ذکر کیا ہے، پھر انہوں نے، ابن مندہ اور ابو نعیم نے بطریق ابن ابی فدیک عن ادریس بن محمد بن یونس ظفری عن ابیہ عن جدہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مونچھیں کاٹا کرو\"۔(2) ہمارے شیخ الشیوخ علائی نے فرمایا: یہ وہم ہے، درست ادریس بن محمد بن یونس بن انس بن فضالہ عن ابیہ عن جدہ یونس عن ابیہ محمد بن انس بن فضالہ ہے۔ یہ سند ابن مندہ نے محمد بن انس کے سوانح میں درست نقل کی ہے، جیسا قسم اول میں بیان ہو چکی ہے۔\nمیں کہتا ہوں: کنیتوں کے آخر میں بیان ہوگا کہ ابن ابی عاصم نے یہ عنوان ابو یونس کے لیے قائم کیا ہے اور اسی طریق سے عن ادریس بن محمد بن یونس عن جدہ یونس عن ابیہ روایت کی ہے کہ وہ حجۃ الوداع میں شریک تھے، اس وقت وہ بیس(۲۰) سال کے تھے، اس سے علائی کے اعتراض کو تقویت ملتی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۶۵۶)\n(2) السنن الکبریٰ (۱۵۰/۱) کنز العمال (۱۷۲۲۳) جامع المسانید والسنن (۵۰۰/۱۲)"}],[8091,"§اختتام جلد 6\nاس کتاب کے مؤلف (اللہ ان سے راضی ہو) فرماتے ہیں: میری کتاب حواشی کے ساتھ تین ذوالحجہ ۸۲۴ھ مکمل ہوئی۔ جس کی ابتداء آٹھ سو نو (۸۰۹) میں ہوئی تھی جو چالیس کے قریب ہے، لیکن اس کی کتابت تاخیر سے ہوئی۔ جو ترتیب میں نے اختیار کی تھی اس کی وجہ سے مسودات میں تین بار ہوئی۔ اب یہ تیسری بار ہے یہ نسخہ بھی مسودہ ہی ہے کیونکہ اس میں بکثرت الحاق کیا گیا ہے، دوسرے ناموں کے شامل کرنے سے تاامیدی حاصل نہیں ہوئی۔ پہلے میں نے سرخی پھر زردی سے پھر خالص صورت سے پھر اس سے حج جلتی حدوت سے اسامہ کو ممتاز کیا۔ یہ سب کچھ درجال ونساوہ کی فصل میں مہم سے پہلے کی کتاب ہے یہ مصنف کے الفاظ تھے انہی کے قلم سے ہم نے نقل کیے ہیں۔\nوالحمدللہ رب العالمین حمداً لا نھایۃ لہ وصلی اللہ علی سیدنا محمد و آلہ و صحبہ وسلّم تسلیماً کثیراً۔ آمین"],[8092,"§۹۳۸۰ ۔ ابوامیہ الفزاری(1)\nنہ کسی نے ان کا نام بتایا اور نہ نسب، ابونعیم اور یحییٰ بن معین کہتے ہیں: انہیں شرف صحابیت حاصل ہے۔ امام احمد(2) اور بغوی نے ابو جعفر الفراء رحمہ اللہ کی سند سے نقل کیا ہے، فرمایا: میں نے ابو امیہ رضی اللہ عنہ کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سینگی لگواتے دیکھا، اس کی سند قوی ہے، اسے سمویہ نے اپنے \"فوائد\" میں اور ابو علی بن السکن اور دیگر لوگوں نے اس سلسلے سے صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ بغوی کہتے ہیں: کسی نے ان کا نسب بیان نہیں کیا اور ان سے صرف یہ حدیث مروی ہے، ابو جعفر ان سے روایت کرنے میں متفرد ہیں ابو جعفر ثقہ ہیں اس نام کے متعلق اکثر علماء کہتے ہیں کہ مد اور میم کے زیر سے ہے جس کے بعد نون ہے۔ ابن عبدالبر نے ذکر کیا ہے کہ ابواحمد حاکم نے کنیتوں میں، ہمزہ کے پیش، میم کے زیر اور آخر میں یائے مشددہ سے ذکر کیا ہے۔ فرماتے ہیں: یہ کچھ بھی نہیں۔ میں کہتا ہوں: ابواحمد نے دو جگہ اس کا ذکر کیا ہے، پہلا مقام دوسرے کی طرح ہے، جبکہ انہوں نے الفزاری نہیں کہا، بلکہ یوں کہا ہے۔ انہوں نے نبی صلی اللہ علیہ وسلم کو پچھنے لگواتے دیکھا، پھر مذکورہ حدیث ذکر کی۔ اور دوسری، حرف الف کے افراد میں ہے اور الفزاری، ابن الاثیر(3) نے یہ گمان کیا ہے کہ ابو عمرو نے ان کا دو جگہ ذکر کیا ہے، وہاں بھی میں نے ایسا دیکھا ہے جیسا کہ میں نے ذکر کیا۔ ابن شاہین کو اس میں تردد ہے۔ اور ابن مندہ نے اس میں اختلاف ذکر کیا ہے اور اس بات کو درست قرار دیا ہے کہ یہ مد نون سے ہے اور ابن فتحون نے کہا ہے: میں نے \"ابن مُؤرج\" کی اصل کتاب میں، ابن السکن کی کتاب سے منقول: أَمَّة الف کے فتحہ اور میم سے بغیر مد کے لکھا دیکھا ہے۔ میں کہتا ہوں: ان کا بغیر مد کے کہنا، اگر الف کی زیادتی و اضافہ مراد ہے تو ٹھیک ورنہ ان کا قول ترک مد میں کوئی صریح اور حرف آخر نہیں ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۷) تجرید اسماء الصحابہ (۱۴۵/۲)\n(2) اخرجہ الامام احمد فی مسندہ (الحدیث: ۳۱۰/۴)\n(3) اسد الغابہ (۳۶۷/۴)"}],[8093,"§۹۳۸۱ ۔ ابوامیہ\nیہ دوسرے ہیں، جن لوگوں کی کنیت ابو آمنہ ہے، ان میں تذکرہ آئے گا۔"],[8094,"§۹۳۸۲ ۔ ابوابراہیم(1)\nسیدہ ام سلمہ رضی اللہ عنہا کے غلام ہیں۔ الحسن بن سفیان نے اپنی مسند میں ان کا ذکر کیا ہے اور یونس بن ابی اسحاق کی سند سے ان کے والد سے ابوابراہیم سے روایت کی ہے، فرمایا: \"(بچپن میں) قیس سیدہ ام سلمہ رضی اللہ عنہا کا غلام تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے بستر پر رات بسر کرتا اور آپ کے برتن سے وضو کرتا۔\"(2) ابو نعیم نے ان کی سند سے اور ابو موسیٰ نے بھی نقل کیا ہے، اس کی سند قوی ہے جبکہ باوردی نے اس سے مکمل روایت ذکر کی ہے، اس کے بعد ہے: \"پھر جب میں بالغ ہو گیا تو آپ نے مجھے آزاد کر دیا، اور فرمایا: ایسی جگہ چلے جاؤ کہ مجھے نظر نہ آؤ۔\" اگر اس روایت کے کسی سلسلے میں اس بات کی وضاحت ہوتی کہ وہ نبی صلی اللہ علیہ وسلم کے زمانے میں تھے (تب تو ان کا صحابی ہونا مانا جاتا) لیکن اس کا بس احتمال ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۹) تجرید اسماء الصحابہ (۱۴۶/۲۲)\n(2) ذکر ابن کثیر فی جامع المسانید والسنن (۵/۳) و ذکرہ ابن الاثیر فی اسد الغابہ (۳۶۷/۴)"}],[8095,"§۹۳۸۳ ۔ ابوابراہیم (بغیر منسوب)\nطبرانی اور عثمانی نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور دونوں نے جریر بن حازم کی سند سے ابوابراہیم سے نقل کیا ہے، فرمایا: میری ان سے مکہ میں ۱۰۴ھ میں ملاقات ہوئی۔ انہیں شرف صحابیت حاصل ہے، پھر انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں نے ارادہ کر لیا کہ صرف چار قبیلوں سے ہدیہ قبول کروں: قریشی، انصاری، ثقفی یا دوسی سے۔\"(1) اس کی سند میں محمد بن یونس کریمی ہے جو ضعیف ہے اور اس روایت میں وہ متفرد بھی ہے، شاید یہ بعد والے ہوں۔","",{"fn":"(1) ذکرہ الہیثمی فی مجمع الزوائد (الحدیث: ۱۴۸/۴) والطبرانی فی المعجم الکبیر (الحدیث: ۱۸/۱۱) والزبیدی فی اتحاف السادۃ المتقین (۲۹۷/۹)"}],[8096,"§۹۳۸۴ ۔ ابوابراہیم الحجبی(1)\nبنی شیبہ سے ان کا تعلق ہے، ابن مندہ نے ان کا ذکر کیا ہے اور سعید بن میسرہ کی سند سے ابراہیم بن ابی ابراہیم الحجبی سے نقل کیا اور انہوں نے اپنے والد سے نقل کیا فرمایا: \"اللہ تعالیٰ نے ابراہیم علیہ السلام کی طرف وحی بھیجی کہ میرے لیے گھر تعمیر کرو۔\"(2) ذہبی(3) فرماتے ہیں: ان کے صحابی ہونے کے بارے میں تردد ہے، بات وہی ہے جو ذہبی نے کہی، کیونکہ روایت میں اس کی وضاحت کے لیے کوئی چیز نہیں اور سعید ضعیف بھی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۸) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) ذکرہ ابن الاثیر فی اسد الغابہ (۳۶۷/۴)\n(3) التجرید (۱۴۶/۲)"}],[8097,"§۹۳۸۵ ۔ ابو ابیّ ابن امرأۃ عبادۃ بن الصامت(1)\nعبد اللہ بن عمرو بن قیس بن زید الانصاری ہیں۔ بعض عبد اللہ بن ابی اور بعض ابن کعب کہتے ہیں، عبادہ رضی اللہ عنہ کی بہن کے بیٹے ہیں بعض عبادہ کے بھانجے بتاتے ہیں۔ ابن حبان نے ذکر کیا ہے کہ ان کا نام شمعون ہے، ابو عمر نے ان لوگوں کے قول کو غلط قرار دیا ہے، جو کہتے ہیں کہ ان کا نام عبد اللہ بن ابی ہے، فرماتے ہیں: وہ تو عبد اللہ بن ابوابی ہیں۔ یحیی بن مندہ نے کہا ہے کہ فلسطین میں سب سے آخری جو صحابی فوت ہوئے یہ ہیں۔ عبادلہ میں ان کا تذکرہ گزر چکا ہے، ان کے والد کے نام میں اختلاف ہے، بغوی وغیرہ نے ابراہیم بن عبلہ کی سند سے ان کی حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۰) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[8098,"§۹۳۸۶ ۔ ابو ابیّ\nذہبی نے بقی بن مخلد کی مسند سے ذکر کیا ہے کہ اس میں ان کی دو حدیثیں ہیں۔ اور یہ ان لوگوں میں ہیں جنہوں نے دونوں قبلوں کی جانب نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم سے نقل کیا ہے، آپ نے فرمایا: \"سنا اور شہد کا استعمال کیا کرو ان میں سوائے موت کے ہر بیماری کی شفاء ہے۔\"(1)۔ میرے خیال میں یہ پہلے والے ہیں۔","",{"fn":"(1) اخرجہ ابن ماجہ فی کتاب الطب باب السنا والسنوت (الحدیث: ۳۴۵۷) الحاکم فی المستدرک (۲۰/۴) ابن ابی عاصم فی السلسلۃ الصحیحۃ (الحدیث: ۱۷۹۸) والنہدۃ فی کنز العمال (الحدیث: ۲۸۲۷۱ و ۲۸۲۶۷) الہیثمی فی مجمع الزوائد (الحدیث: ۸۳۰۹) الطبرانی فی المعجم الکبیر (الحدیث: ۳۹۸/۲۳) ذہبی فی الطب النبوی (۱۸/۱)"}],[8099,"§۹۳۸۷ ۔ ابواثیلہ(1)\nالف کے زبر، زیر پیش سے تصغیر ہے۔ وہ راشد اسلمی ہیں۔ اسماء میں گزر چکا ہے۔ ابوعمر نے نقل کیا ہے کہ وہ ابووائلہ ہیں بغیر تصغیر۔ ابن الاثیر(2) نے ابواثیلہ بن راشد لکھا ہے جو وہم ہے راشد تو ان کے بیٹے کا نام ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۱) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) اسد الغابہ (۳۶۸/۴)"}],[8100,"§۹۳۸۸ ۔ ابواثیلہ (دوسرے)\nابن الجوزی نے \"تنقیح\" میں ان کا ذکر کیا ہے اور ان کے متعلق کہا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے غلام تھے۔"],[8101,"§۹۳۸۹ ۔ ابواحمد بن جحش الاسدی(1)\nام المومنین زینب رضی اللہ عنہا کے بھائی، ان کا نام \"عبد\" بغیر اضافت ہے۔ بعض نے عبد اللہ کہا ہے۔ ابن کثیر سے نقل کیا ہے، علماء نے کہا: یہ وہم ہے البتہ اس پر اتفاق ہے کہ وہ سابقین اولین سے ہیں، بعض کا قول ہے کہ انہوں نے حبشہ ہجرت کی، پھر مدینہ ہجرت کر کے آئے، بلاذری نے ان کی حبشہ کی جانب ہجرت کا انکار کیا ہے، اور کہا ہے کہ انہوں نے حبشہ ہجرت نہیں کی۔ وہ تو ان کے بھائی عبید اللہ تھے جو وہاں جا کے نصرانی ہو گئے تھے۔ ابن اسحاق(2) کا قول ہے کہ ابو سلمہ عامر بن ربیعہ اور عبداللہ بن جحش کے بعد مہاجرین میں سب سے پہلے وہ مدینہ آئے۔ اپنے گھرانے اور اپنے بھائی عبداللہ کو ساتھ لے آئے۔ ابواحمد نابینے تھے، مکہ میں اوپر نیچے بغیر قائد کے طواف کرتے تھے۔ ان کے عقد میں فارعہ بنت ابوسفیان بن حرب تھیں، بدر اور دوسری جنگوں میں شریک رہے۔ وہ مکہ میں بغیر قائد کے گھومتے تھے۔ اس کے متعلق وہ کہتے ہیں: \"مکہ کیا ہی اچھی وادی ہے جس میں میرا گھرانا۔۔۔۔۔۔ اس میں میری کیلیں جمی ہوئی ہیں، اس میں میں بغیر رہنما کے چلتا ہوں۔\" اور بلاذری نے ہر قسم کی ابتداء میں پہلے کے سوا ابی کے اضافہ سے یہ اشعار پڑھے ہیں: پھر چاروں مخزومہ ہو جائیں گے، مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے، فرماتے ہیں، نبی صلی اللہ علیہ وسلم نے یہ اشعار پڑھے: \"ام احمد نے کوہ صفا اور مروہ پر اللہ کی قسم کھائی، اس کی قسم پوری ہوگئی، ہم وہی لوگ ہیں جو اس میں تھے پھر ہم مکہ میں ہی رہے۔ ہم دو اور ایک کے درمیان اللہ تعالیٰ کی طرف بڑھتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کا دین اور اس کا دین برحق ہے۔\" ابن الاثیر(3) نے اس بات پر اعتماد کیا ہے کہ انہوں نے اپنی بہن زینب بنت جحش کے بعد وفات پائی۔ جبکہ اس میں نظر ہے۔ بعض کا کہنا ہے: یہ وہی ہیں جو فوت ہوئے تو ان کی بہن کو ان کی فوتگی کی خبر ملی تو انہوں نے خوشبو منگا کر ملی۔ صحیحین میں زینب بنت ام سلمہ کی سند سے منقول ہے، راوی کا بیان ہے: میں سیدہ زینب بنت جحش رضی اللہ عنہا کے پاس آیا، جب ان کے بھائی کا انتقال ہوا، تو انہوں نے خوشبو منگا کر ملی، پھر فرمانے لگیں: مجھے خوشبو کی چنداں ضرورت نہ تھی، چونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو عورت اللہ تعالیٰ اور یوم آخرت پر ایمان رکھتی ہو اس کے لیے حلال نہیں کہ وہ سوائے خاوند کے کسی میت کے لیے تین دن سے زائد سوگ کرے۔\"۔ (الحدیث)(4) جس کی تقویت اس سے ہوتی ہے کہ یہ ابو احمد ہی ہیں کیونکہ آپ کے دونوں بھائی عبداللہ اور عبید اللہ رسول اللہ صلی اللہ علیہ وسلم کی حیات میں ہی فوت ہو گئے تھے، ان میں عبداللہ جو بڑے ہیں وہ اُحد میں شہید ہوئے۔ اور چھوٹا بھائی عبید اللہ سرزمین حبشہ میں نصرانی ہو کر مر گیا۔ جس کی بیوی ام حبیبہ بنت ابی سفیان سے بعد میں رسول اللہ صلی اللہ علیہ وسلم نے شادی کر لی تھی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۲) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) ذکرہ ابن ہشام فی السیرۃ النبویۃ عن ابن اسحاق (۸۶/۲)\n(3) اسد الغابہ (۳۶۸/۴)\n(4) اخرجہ البخاری فی کتاب الطلاق، باب تحد المتوفی عنہا زوجہا اربعۃ اشہر وعشرا (الحدیث: ۵۳۳۵) و اخرجہ مسلم فی کتاب الطلاق باب وجوب الاحداد فی عدۃ الوفاۃ (الحدیث: ۳۷۰۹)"}],[8102,"§۹۳۹۰ ۔ ابواحمد بن قیس بن لوذان(1)\nبن لوذان انصاری، سلیم کے بھائی، عدوی نے کہا: ان دونوں حضرات کو شرف صحبت حاصل ہے اور وہ ان دس میں سے ایک ہیں جنہیں سیدنا عمر رضی اللہ عنہ نے سیدنا عمار بن یاسر رضی اللہ عنہ کے ہمراہ کوفہ بھیجا تھا۔","",{"fn":"(1) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[8103,"§۹۳۹۱ ۔ ابواحیحہ (دونوں حاؤں سے تصغیر ہے)\nقریشی ہیں، ان کا ذکر ابن اسحاق کی فتوح الشام میں یونس بن بکیر کی ان سے روایت میں آیا ہے، فرماتے ہیں: سیدنا خالد بن ولید رضی اللہ عنہ کی سماوہ سے دمشق کی جانب رافع طائی کی رہنمائی میں روانگی کے موقع پر ابواحیحہ نے کہا: \"خالد کی خوبیاں اللہ کے لیے ہیں جو ہدایت یافتہ آیا، جبکہ آنکھ اس سے خس و خاشاک سے ڈھک گئی۔ وہ آنکھ ایسے پیٹی ہوتی ہے گویا کہ مٹی سے بھری پڑی، وہ اپنے دل سے وہ کچھ دیکھتا ہے جو ہم نہیں دیکھتے، یاد کرنے والا دل اور میرا دل یاد کر چکا۔۔۔۔۔ (نظم کے آخری اشعار تک)۔\" ابن عساکر رحمہ اللہ یہ فرماتے ہیں: ان ابو احیحہ نے سیدنا خالد کے ساتھ فتح دمشق میں شرکت کی، اور یہ اشعار قعقاع بن عمرو تمیم سے بھی نقل کیے گئے ہیں۔ میں کہتا ہوں: یہ پہلے گزر چکا ہے کہ حجتہ الوداع کے موقع پر جو قریشی بھی حاضر تھا وہ مسلمان تھا لہذا یہ صحابی ہوئے۔"],[8104,"§۹۳۹۲ ۔ ابو احزم بن عتیک(1)\nابن نعمان ابن علیک الانصاری، سہل کے بھائی، ان کا نام حارث ہے۔ اسماء میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۰) الاستيعاب (ت: ۲۸۷۲)"}],[8105,"§۹۳۹۳ ۔ ابواخرم\nابن فتحون نے اس کا استدراک کیا ہے، فرمایا: طبری نے ان کا شعبہ کی سند سے ابومہاجر وہ کوفہ کے ایک شخص سے جسے اخرم کہا جاتا ہے کے حوالے سے نقل کرتے ہیں وہ اپنے والد سے روایت کرتے ہیں فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مال واہل میں تبقر سے منع فرمایا۔ کسی نے ان سے پوچھا: تبقر کیا ہے؟ فرمایا: کثرت۔ میں کہتا ہوں: ان کے نسب میں اختلاف ہے، جس کا کچھ تذکرہ میں نے سعد بن الاخرم میں کر دیا ہے۔"],[8106,"§۹۳۹۴ ۔ ابوالاخنس بن حذافہ(1)\nبن قیس ابن عدی بن سعد بن سہم قرشی سہمی، عبداللہ اور خنیس کے والد، ابوعمر نے کہا: ان کا نام معلوم نہیں ہو سکا، ان کی صحابیت کے بارے میں نظر ہے۔ زبیر بن بکار نے کہا: حذافہ کی نسل میں اولاد ابوالاخنس کی ہے۔ ان میں سے صرف عبد اللہ بن محمد بن ذویب بن عمامہ بن ابی الاخنس بن حذافہ بچے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۴) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[8107,"§۹۳۹۵ ۔ ابواذینہ (یا نون سے تصغیر ہے)(1)\nبغوی نے کہا: وہ اہل مصر سے تعلق رکھتے ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی، ان کے متعلق مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہے یا نہیں؟ ابن السکن نے کہا: ابواذینہ صدفی کو صحبت رسول حاصل ہے اور ان کی حدیث اہل مصر میں شمار ہوتی ہے۔ انہوں نے محمد بن بکار بن بلال کی سند سے موسیٰ بن علی بن رباح کے حوالہ سے نقل کیا وہ اپنے والد سے وہ ابو اذینہ صدفی سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری عورتوں میں سے بہترین عورت وہ ہے جو زیادہ محبت کرے، زیادہ بچے جنے، جس کے پاس آیا جائے، تسلی دینے والی (ان محاسن کے ساتھ) جب اللہ تعالیٰ سے ڈرتی ہو، اور تمہاری بری عورتیں وہ ہیں جو مردوں کی مشابہت اختیار کریں، منافق عورتوں سے تعلق رکھتی ہوں، بے حیا ہوں۔ ان میں سے جنت میں صرف اتنی جائیں گی جیسے سفید ٹانگوں والا کوا۔\"(2) ابو عمر نے نقل کیا ہے کہ انہیں العبدی بھی کہا جاتا ہے جو غلط ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۶) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) الہندی کنز العمال (الحدیث: ۴۴۵۶۹) زبیدی، اتحاف السادۃ المتقین (۲۹۷/۵) العراقی، مغنی المحتاج فی حمل الاسفار (۲۷/۲) ابن کثیر \"جامع المسانید والسنن\" (۱۱/۱۳) ابن الأثیر فی اسد الغابہ (۳۶۹/۴)"}],[8108,"§۹۳۹۶ ۔ ابوارطاۃ الاحمسی(1)\nجریر کے قاصد، ان کا نام حصین بن ربیعہ ہے، اسماء میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۴) الاستيعاب (ت: ۲۸۷۶)"}],[8109,"§۹۳۹۷ ۔ ابوالارقم القرشی(1)\nارقم کے والد ہیں، ابن ابوخیثمہ اور طبری نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ ابو علی الجیانی فرماتے ہیں: امام مسلم نے کتاب \"الاخوۃ والاخوات\" میں ان کا ذکر کیا ہے جہاں باب ہے، جنہوں نے نبی صلی اللہ علیہ وسلم سے سنا، انہیں اور ان کے والد کو شرف صحابیت حاصل ہے۔ ابوالارقم اور الارقم بن ابی الارقم۔ یہ ارقم، ان ارقم مخزومی کے علاوہ ہیں جن کا اسماء میں ذکر ہوا، اور وہ ارقم وہ والے ہیں جن کا ذکر سیرت میں رسول اللہ صلی اللہ علیہ وسلم کے دار ارقم میں داخل ہونے سے پہلے آئے گا۔ ان کے والد کا نام عبد مناف ہے اور یقینی بات ہے کہ انہیں شرف صحبت حاصل نہیں۔ جیسا کہ ابن عبدالبر نے دوسی کے (ترجمہ) حالات میں کہا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۱۴۷/۲)"}],[8110,"§۹۳۹۸ ۔ ابواروی الدوسی(1)\nان کا نام اور نسب معروف نہیں۔ ابن السکن نے کہا ہے: انہیں شرف صحابیت حاصل ہے۔ وہ ذوالحلیفہ میں پڑاؤ کرتے تھے، ابن السکن اور حاکم نے عاصم بن عمر العمری کی سند سے سہیل بن ابی صالح کے حوالہ سے، محمد بن ابراہیم تیمی سے وہ ابوسلمہ بن عبدالرحمن سے وہ ابواروی دوسی سے نقل کرتے ہیں، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس بیٹھا تھا کہ اچانک حضرات ابوبکر و عمر رضی اللہ عنہما آ گئے۔ تو آپ نے فرمایا: اللہ تعالیٰ کے لیے تمام تعریفیں ہیں جس نے تم دونوں کے ذریعہ میری تائید کی۔(2) اس کی سند ضعیف ہے۔ ان کی ایک اور حدیث ہے جسے امام احمد اور بغوی رحمہ اللہ نے ابو واقد لیثی کی سند سے۔ ان کا نام صالح بن محمد بن زائدہ ہے۔ ابواروی الدوسی سے نقل کیا ہے، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عصر کی نماز پڑھ رہا تھا پھر آپ غروب آفتاب سے پہلے چٹان کے پاس آئے۔(3) اور ابن مندہ اور ابونعیم نے ان الفاظ سے نقل کی ہے: \"ابھی تک سورج ڈوبا نہ تھا کہ آپ مقام ذوالحلیفہ پیدل آئے۔\" ابن ابی خیثمہ نے اسی سند سے نقل کی ہے جو ان کے ہاں ابو واقد کی سند سے ہے، فرمایا: \"مجھ سے ابواروی نے بیان کیا۔ فرماتے ہیں: میں نے ان کے متعلق یحیی بن معین سے پوچھا، تو انہوں نے اپنے قلم سے ابو واقد کے متعلق لکھا وہ ضعیف ہے۔ اور واقدی نے ذکر کیا ہے کہ ابواروی غزوہ قرقرہ الکدر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک تھے۔ ابن السکن اور ابو عمر کا کہنا ہے: ان کا انتقال امیر معاویہ رضی اللہ عنہ کی خلافت کے آخر میں ہوا، وہ عثمانی تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۸) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) الحاکم فی المستدرک (۷۴/۳) الہیثمی، مجمع الزوائد (۵۰/۹) الطبرانی، المعجم الکبیر (۹۲۶/۲۲) الہندی، کنز العمال (۳۲۶۸۱) ابن الاثیر اسد الغابہ (۳۷۰/۴)\n(3) اخرجہ الامام احمد فی مسندہ (الحدیث: ۹۲۶/۲۲) والطبرانی فی المعجم الکبیر (۹۲۵/۲۲) الہیثمی فی مجمع الزوائد (۳۰۷/۱)"}],[8111,"§۹۳۹۹ ۔ ابوالازور ضرار بن الخطاب(1)\nپہلے ذکر ہو چکا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۷)"}],[8112,"§۹۵۰۰ ۔ ابوالازور ضرار بن الازور(1)\nپہلے ذکر ہو چکا۔","",{"fn":"(1) الاستيعاب (ت: ۲۸۷۹)"}],[8113,"§۹۵۰۱ ۔ ابوالازور الاحمری(1)\nابن مندہ نے ان کا ذکر کیا اور ابراہیم بن اسمعیل بن ابی حبیبہ کی سند سے عمر بن ابی سفیان کے حوالہ سے نقل کیا وہ اپنے والد سے وہ ابوالازور الاحمری سے روایت کرتے ہیں، فرماتے ہیں: وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"رمضان کا عمرہ حج کے برابر ثواب رکھتا ہے۔\"(2)","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۹) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) بخاری کتاب العمرۃ باب عمرۃ فی رمضان الحدیث (۱۷۸۲) مسلم کتاب الحج باب فضل العمرۃ فی رمضان (الحدیث: ۳۰۲۸) نسائی کتاب الصیام باب الرخصۃ فی ان یقال لشہر رمضان (الحدیث: ۲۱۰۹) ترمذی کتاب الحج باب ما جاء فی عمرۃ رمضان (الحدیث: ۹۴۰) ابن ماجہ کتاب المناسک باب العمرۃ فی رمضان (الحدیث: ۲۹۹۳) الامام احمد فی مسندہ (الحدیث: ۶/۴۶) ابن الأثیر فی اسد الغابہ (۳۷۰/۴)"}],[8114,"§۹۵۰۲ ۔ ابوالازور (دوسرے)\nابو عمر نے انہیں پہلے والے سے ملا دیا ہے صحیح یہ ہے کہ دونوں میں فرق ہے۔ عبدالرزاق نے اپنی مصنف میں لکھا ہے، ابن جریج سے روایت ہے، فرمایا: جب ابو عبیدہ شام کے گورنر تھے اس وقت کی بات ہے مجھے بتایا گیا کہ انہوں نے ابوجندل بن سہیل، ضرار بن الخطاب اور ابوالازور کو شراب نوشی میں مصروف پایا، تو ابو جندل بولے: \"وہ لوگ جو ایمان لائے اور اعمال صالحہ کیے، جب وہ ایمان تقویٰ اور اعمال صالحہ کے ساتھ کچھ کھا لیں تو ان پر کوئی حرج نہیں۔\"(1) تو ابو عبیدہ رضی اللہ عنہ نے واقعہ کی اطلاع کے لیے سیدنا عمر رضی اللہ عنہ کو خط لکھا کہ ابو جندل نے ان آیات کے ذریعہ سے مجھ سے جھگڑا کیا ہے تو سیدنا عمر رضی اللہ عنہ نے انہیں جواباً لکھا: جس نے ابو جہل کو غلطی اچھی کر دکھائی اس (شیطان) نے ابو جندل کے لیے جھگڑے کو مزین کر دیا۔ انہیں حد لگاؤ! اس پر ابوالازور نے کہا: اگر تم نے ہمیں حد لگانی ہی ہے تو ہمیں کل دشمن سے مڈبھیڑ کر لینے دو اگر ہم مارے گئے تو بہتر ورنہ تمہاری طرف لوٹ آئے تو ہمیں حد لگا لینا۔ دشمن سے مقابلہ ہوا۔ ابوالازور تو شہید ہو گئے اور باقی دو صاحبان کو حد لگی۔ دونوں میں فرق کی دلیل یہ ہے کہ الاحمری کا دور اتنا مؤخر ہوا کہ ان سے ابوسفیان ثقفی نے روایت کی ہے اور ابوسفیان نے خلافت عمر کا دور نہیں پایا۔","",{"fn":"(1) سورۃ المائدۃ (۹۳)"}],[8115,"§۹۵۰۳ ۔ ابوالازھر الانماری(1)\nانہیں ابوزھیر بھی کہا جاتا ہے، ابوداؤد نے سنن میں اچھی شامی سند سے نقل کیا کہ مجھ سے ابوالازھر انماری اور وائلہ بن الاسقع رسول اللہ صلی اللہ علیہ وسلم کے صحابیوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے علم طلب کیا پھر اسے پالیا تو اس کے لیے اجر کے دو پیمانے ہیں۔\"۔ (الحدیث)(2) اور ابوداؤد نے یحیی بن حمزہ کی سند سے ثور بن یزید کے حوالہ سے خالد سے نقل کیا ہے جب وہ سونے لگتے تو فرماتے: \"اللہ کے نام سے میں نے اپنا پہلو رکھا۔\"۔ (الحدیث)(3) اس کے بعد کہا: ابو ہمام الاہوازی نے اسے ثور سے روایت کیا تو کہا: ابوزھیر نے کہا۔ میں کہتا ہوں: کہ ابو ہمام کی بات کی متابعت صدقہ بن عبد اللہ نے کی ہے۔ ابن ابی حاتم نے کہا: میں نے ابوزرعہ سے سنا، ان کے سامنے ابوزھیر انماری کا ذکر ہوا، فرمایا: ان کا کوئی نام نہیں لیا جاتا، وہ صحابی نہیں، انہوں نے تین احادیث روایت کی ہیں۔ میں نے اپنے والد سے کہا کہ ایک شخص نے ان کا نام یحیی بن نفیر بتایا ہے، تو انہوں نے ناواقفیت ظاہر کی۔ میں کہتا ہوں: آمین کے بارے میں ان کی حدیث ہے جسے ان سے ابواصبح قرشی روایت کرتے ہیں۔ کثیر بن مرہ اور شریح بن عبید نے بھی ان سے روایت نقل کی ہے۔ بغوی نے کہا: ابوالازھر انماری کا نسب بیان نہیں کیا جاتا، مجھے معلوم نہیں وہ صحابی ہیں یا نہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۱) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) الہیثمی فی مجمع الزوائد (الحدیث: ۱/۱۲۳) الطبرانی فی المعجم الکبیر (الحدیث: ۱۶۵/۲۲) ابن الأثیر فی اسد الغابہ (۳۷۱/۴) الہندی فی کنز العمال (۲۸۸۳۸) المنذری فی الترغیب والترہیب (۹۶/۱)\n(3) اخرجہ ابوداؤد فی کتاب الادب باب ما یقال عند النوم (الحدیث: ۵۰۵۴) و اخرجہ الطبرانی فی المعجم الکبیر (الحدیث: ۷۵۸/۲۲) ابن کثیر فی جامع المسانید والسنن (۱۵/۱۳) الہندی فی کنز العمال (الحدیث: ۱۸۲۳۶) والزبیدی فی اتحاف السادۃ المتقین (۱۸۲۳۶)"}],[8116,"§۹۵۰۴ ۔ ابواسحاق\nسعد بن ابی وقاص پہلے ذکر گزر چکا۔"],[8117,"§۹۵۰۵ ۔ ابواسرائیل الانصاری(1)\nیا قریشی عامری ہیں۔ بغوی وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے۔ ابو عمر نے کہا: ان کا نام یسیر (یا، سین سے تصغیر ہے)۔ ابن اسکن اور باوردی نے حرف قاف قشیر میں اس نام کو نقل کیا ہے۔ امام احمد(2) رحمہ اللہ نے فرمایا: عبدالرزاق نے ابن جریج، ابن طاؤس نے نقل کیا وہ اپنے والد سے وہ ابو اسرائیل سے روایت کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف لائے تو ابو اسرائیل نماز پڑھ رہے تھے، کسی نے آپ سے عرض کیا: وہ یہ ہیں، یا رسول اللہ! (کھڑے ہیں) بیٹھتے نہیں، نہ لوگوں سے بات کرتے ہیں۔ نہ سائے میں بیٹھتے ہیں۔ انہوں نے اس طرح کا روزہ رکھا ہے، آپ نے فرمایا: وہ بیٹھ جائیں، لوگوں سے بات کریں، سائے میں آجائیں، لوگوں سے بات کریں، سائے میں آجائیں اور روزہ رکھ لیں۔ اسے بغوی اور ابونعیم نے لیث بن ابی سلیم کی سند سے طاؤس کے حوالہ سے ابو اسرائیل سے روایت کیا ہے، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں دھوپ میں کھڑے دیکھ کر فرمایا: انہیں کیا ہوا؟ لوگوں نے عرض کیا: نذر مانی ہے پھر اسی طرح کا مفہوم ذکر کیا۔ اس کی اصل صحیحین میں ہے جو ابن عباس رضی اللہ عنہما کی حدیث سے ثابت ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دھوپ میں کھڑے دیکھا۔۔۔۔۔ (الحدیث) اسے بھی بغوی نے محمد بن کریب سے، انہوں نے ابن عباس رضی اللہ عنہما سے نقل کیا ہے: ابو اسرائیل قشیر نے کھڑے ہونے کی نذر مانی۔۔۔، پھر حدیث ذکر کی۔ اور بخاری رحمہ اللہ میں عکرمہ کی ابن عباس رضی اللہ عنہما کی سند سے مروی روایت ہے کہ وہ ابو اسرائیل تھا۔ اکثر روایات میں ان کا نام نہیں لیا گیا۔ اسی طرح امام مالک نے حمید بن قیس اور ثور سے بغیر نام کے مرسل روایت کیا ہے۔ اور خطیب نے مہمات میں جریر بن حازم سے، ایوب، مجاہد سے وہ ابن عباس رضی اللہ عنہما کی سند سے روایت کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جمعہ کے روز لوگوں سے خطاب فرماتے، تو آپ کی نظر بنی عامر بن لوئی کی شاخ قریش کے ایک شخص پر پڑی جسے ابواسرائیل کہا جاتا تھا۔۔۔۔ پھر اس روایت کو ذکر کیا۔ عبد الغنی نے مہمات میں کہا ہے کہ صحابہ رضی اللہ عنہم میں ان کے علاوہ کسی کی کنیت ابو اسرائیل نہیں ہے۔ اور اسماء میں گزر چکا ہے کہ ان کا نام قشیر ہے (شین سے تصغیر ہے) اسے ابن السکن نے روایت کیا اور ابوعمر نے اسے لفظی غلطی قرار دے کر کہا: قیسر (سین مفتوح سے پہلے یاء ساکن)۔ زبیر بن بکار نے نسب قریش میں ذکر کیا کہ بزدہ بنت عامر بن الحارث بن السباق بن عبدالدار، مہاجر خواتین سے تھیں۔ جن سے ابو اسرائیل فہری نے نکاح کر لیا تو ان کے ہاں جنگ جمل سے پہلے اسرائیل کی ولادت ہوئی۔ شاید وہ ابو اسرائیل یہی ہوں۔ عبد الغنی کے قول: \"صحابہ رضی اللہ عنہم میں ان کے علاوہ کسی کی کنیت ابو اسرائیل نہیں\" سے اس بات کی تائید ہوتی ہے کہ ابو اسرائیل ان کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۳) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) مسند احمد (۱۶۸/۴)"}],[8118,"§۹۵۰۶ ۔ ابواسماء السکونی\nغضیف بن الحارث، ناموں میں ذکر ہو گیا ہے۔"],[8119,"§۹۵۰۷ ۔ ابواسماء الشامی(1)\nابواحمد حاکم نے احمد بن یوسف بن ابی اسماء کی سند سے نقل کیا ہے، فرماتے ہیں: میں نے اپنے دادا ابواسماء بن علی بن ابی اسماء سے بحوالہ ان کے والد ان کے دادا ابو اسماء سے سنا، فرمایا: میں نبی کریم صلی اللہ علیہ وسلم کے پاس گیا، آپ سے بیعت کی، آپ نے مجھ سے مصافحہ کیا۔ اس کے بعد سے میں نے قسم کھالی کہ میں کسی سے مصافحہ نہیں کروں گا۔ چنانچہ وہ کسی سے مصافحہ نہیں کرتے تھے۔(2) ان میں اور غضیف میں فرق کیا گیا ہے۔ اسے ابن مندہ نے مذکورہ بالا احمد بن یوسف کی سند سے روایت کیا ہے اور ان کی سند میں غیر معروف راوی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۴) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) مسند احمد (۷۹/۵) المعجم الکبیر (۹۵۰/۲۲) مجمع الزوائد (۱۷۹/۴)"}],[8120,"§۹۵۰۸ ۔ ابو اسماء المزنی\nمزینہ کے جو لوگ \"خزاعی بن عبد نعم\" کے ہاتھ پر اسلام لائے ان میں سے ایک ہیں۔ وہ فتح مکہ میں شریک تھے یہ بات پہلے \"خزاعی بن عمرو\" کے سوانح میں گزر چکی ہے جسے \"تجرید\" میں اصل کی پیروی کرتے ہوئے نظر انداز کر دیا۔"],[8121,"§۹۵۰۹ ۔ ابواسماء بن عمرو الجذامی(1)\nواقدی نے ان کا جذام کے ان لوگوں کے وفد میں ذکر کیا ہے جو نبی صلی اللہ علیہ وسلم کے پاس یہ بتانے آئے تھے کہ ان کے مسلمان ہو چکنے کے بعد بھی زید بن حارثہ نے ان سے تعرض کیا ہے، چنانچہ آپ نے ان کے قیدی رہا کر دیئے۔ اور ان کا لیا مال واپس کر دیا۔","",{"fn":"(1) اسد الغابہ (۵۶۸۱)"}],[8122,"§۹۵۱۰ ۔ ابوالاسود الجذامی\nیہ دوسرے ہیں، عبداللہ بن سندر، پہلے ذکر ہو چکا ہے۔"],[8123,"§۹۵۱۱ ۔ ابوالاسود\nعبدالرحمن بن یعمر، ان کا تذکرہ بھی پہلے ہو گیا ہے۔"],[8124,"§۹۵۱۲ ۔ ابوالاسود بن یزید(1)\nبن معدی کرب بن سلمہ بن مالک بن حارث بن معاویہ اکرمین کندی ابن کلبی نے بحوالہ طبری ذکر کیا ہے: وہ معزز انسان تھے، نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر اسلام لائے۔ ابوعلی جیانی نے استیعاب پر اپنے اضافہ میں ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۷) تجرید (۱۴۷/۲)"}],[8125,"§۹۵۱۳ ۔ ابوالاسود السلمی\nآخری قسم میں تذکرہ آئے گا۔"],[8126,"§۹۵۱۵ ۔ ابوالاسود القرشی\nمالکی بھی کہا جاتا ہے \"جرح و تعدیل\" میں ابن ابی حاتم نے عبد اللہ بن اسود قرشی کے سوانح میں ذکر کیا ہے کہ وہ اپنے والد کے واسطہ سے اپنے دادا سے روایت کرتے ہیں۔ وہ نبی صلی اللہ علیہ وسلم سے کہ آپ نے فرمایا: جس حکمران نے ہمیشہ تجارت کی اس نے انصاف نہیں کیا۔ ابن وہب نے خالد بن عمیر سے بحوالہ ان سے نقل کیا ہے۔ ابن فتحون نے استیعاب پر اضافہ کرتے ہوئے استدراک کیا ہے۔ ابواحمد حاکم نے بقیہ کی سند سے بحوالہ خالد بن حمید روایت کیا ہے کہ ابن الاسود مالکی نے بواسطہ اپنے والد اپنے دادا سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس حکمران نے رعیت میں تجارت کی اس نے انصاف نہیں کیا۔\"(1)","",{"fn":"(1) کنز العمال (۱۴۶۷۶) المطالب العالیۃ (۲۱۰۷)"}],[8127,"§۹۵۱۶ ۔ ابوالاسود النهدی(1)\nباوردی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور یونس بن بکیر بحوالہ عنبسہ بن ازہر، ابوالاسود نہدی سے نقل کیا ہے انہوں نے نبی صلی اللہ علیہ وسلم کا دور پایا ہے۔ فرمایا: آپ غار کی جانب متوجہ تھے اور آپ کی انگشت پا زخمی ہوگئی۔ آپ نے فرمایا: تو ایک انگلی ہی تو ہے جو خون آلود ہوگئی، تجھے یہ تکلیف اللہ کی راہ میں پہنچی ہے۔(2) میں کہتا ہوں: اس کی سند میں تامل ہے۔ بعض کا قول ہے: ان کا نام عبد اللہ ہے۔","",{"fn":"(1) الاستيعاب (۲۸۸۳)\n(2) بخاری کتاب الجہاد والسیر باب من ینکب او یطعن فی سبیل اللہ (۲۸۰۲) مسلم کتاب الجہاد والسیر باب ما نہی النبی صلی اللہ علیہ وسلم اذی المشرکین والمنافقین (۱۷۹۶) مسند احمد (۱۸۸۳۰)"}],[8128,"§۹۵۱۷ ۔ ابواسید بن ثابت انصاری(1)\nالزرقی المدنی، زیتون کی فضیلت میں ان کی حدیث دارمی، ترمذی، نسائی اور حاکم نے عبداللہ بن عیسی کی سند سے بحوالہ ایک عطا نامی شامی شخص روایت کی ہے۔ نسائی کی روایت میں ہے۔ مجھے عطاء (ایک شخص جو ساحل پر رہتا تھا) نے بیان کیا اور ابواسید بن ثابت سے یہ روایت نقل کی۔ ابو حاتم رحمہ اللہ فرماتے ہیں: احتمال ہے کہ وہ شخص عبداللہ بن ثابت ہوں، جو نبی صلی اللہ علیہ وسلم کی خدمت کرتے تھے اور شعبی ان سے روایت لیتے ہیں کہ سیدنا عمر رضی اللہ عنہ ایک تحریر لائے\"۔ دارقطنی نے یہ نام شروع کے زبر سے قلمبند کیا ہے۔ پیش بھی نقل کیا ہے لیکن اسے کمزور قرار دیا ہے۔ اس میں اس پر بھی رد ہے، جس نے انہیں ساعدی کے ساتھ ملا دیا۔ چنانچہ ان کی مذکورہ حدیث امام احمد وغیرہ نے ابواسید ساعدی کی سند میں داخل کر دی ہے اور ابو عمر کے ہاں: ابواسید ثابت انصاری لکھا ہے، ان کی حدیث ہے: \"زیتون کھایا کرو۔\"(2) یوں ان کا نام ساقط کر دیا۔ میں نے دمیاطی کے قلم سے لکھا ہوا پڑھا ہے: ابن ابی حاتم نے فرمایا: عطاء شامی نے ابواسید عبداللہ بن ثابت سے روایت لی ہے۔ ابو عمر نے ان کا نام ثابت بتایا ہے اور ابن فتحون نے اس پر کوئی تنبیہ نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۶۷۸)\n(2) ترمذی کتاب الاطعمۃ باب ما جاء فی اکل الزیت (۱۸۵۲) مسند احمد (۴۹۷/۳) ابن ماجہ کتاب الاطعمۃ باب الزیت (۳۳۱۹) المعجم الکبیر (۵۹۶/۱۹، ۵۹۷)"}],[8129,"§۹۵۱۸ ۔ ابواسید بن ثابت انصاری (دوسرے)(1)\nان کا نام عبداللہ ہے جو ناموں میں گزر چکا ہے، ان کی حدیث کی سند میں جابر بھی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۵)"}],[8130,"§۹۵۱۹ ۔ ابواسید بن جعونہ\nیہ وفد میں آئے، ابن بشکوال نے ان کا ذکر کیا ہے۔ ایسا ہی تجرید میں لکھا ہے لیکن مجھے ابن بشکوال کے حاشیے میں نظر نہیں آیا۔ الاستیعاب میں ابوزہیر بن اسید بن جمعونہ لکھا ہے: پس اسے لکھ لیا جائے۔"],[8131,"§۹۵۲۰ ۔ ابواسید بن علی(1)\nبن مالک انصاری ابوالعباس السراج نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا اور ابن مندہ نے اسے نقل کیا ہے۔ اور بسطام کی سند سے بحوالہ حسن بصری ابواسید بن علی سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تجھے عمارتیں سلع پہاڑ تک پہنچی ہوئی دکھائی دیں تو شام کے جہاد میں نکل جانا ورنہ امیر کی بات سننا اور اس کا کہنا ماننا۔(2) وہ حدیث جو سراج نے ذکر کی ہے اسے ان سے ابواحمد نے کنیتوں میں نقل کیا ہے، جس کی سند زہیر بن عباد بحوالہ سعید، قتادہ سے مروی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے ابواسید بن علی کو بنی عامر بن صعصعہ کی ایک خاتون کی اپنے لئے منگنی کرنے بھیجا، آپ نے اسے دیکھا نہیں تھا، پھر نبی صلی اللہ علیہ وسلم کے دیکھے بغیر ابواسید نے اس کا آپ سے نکاح کرا دیا۔ تمہید میں ابو عمر نے اس کا تعاقب کرتے ہوئے لکھا ہے: اس میں حاکم کو وہم ہو گیا ہے یہ قصہ تو ابواسید ساعدی کا ہے۔ جبکہ اس میں تامل ہے اس لیے کہ دونوں قصے مختلف ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۷۹) تجرید (۱۴۸/۲)\n(2) جامع المسانید (۲۱/۱۳) اسد الغابہ (۳۷۲/۴)"}],[8132,"§۹۵۲۱ ۔ ابواسید الساعدی(1)\nنام مالک بن ربیعہ تھا، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۱۴۸)"}],[8133,"§۹۵۲۲ ۔ ابواسیرہ بن حارث(1)\nبن علقمہ، واقدی(2) نے شہدائے اُحد میں ان کا ذکر کیا ہے، جس کی سند حارث بن عبداللہ بن کعب بن مالک تک پہنچاتے ہیں۔ وہ فرماتے ہیں: مجھ سے اس شخص نے بیان کیا جس نے ابوالسیرۃ بن حارث بن علقمہ کو دیکھا وہ بنی ابی عزیز کے ایک شخص کے سامنے ہوئے دونوں کی تلواریں ٹکرائیں وہ ایک دوسرے کو مارنے کے لیے تیار تھے، مجھے وہ یوں نظر آئے یوں لگ رہا تھا کہ دو خونخوار درندے ہیں۔ پھر دونوں نے ایک دوسرے کو دبوچا، ابوالسیرۃ نے اسے اوپر اٹھایا اور ایسے ذبح کر دیا جیسے بکری ذبح کی جاتی ہے۔ اتنے میں خالد بن ولید رضی اللہ عنہ نے (جو ابھی مسلمان نہیں ہوئے تھے) ابوالسیرۃ کو پیچھے سے نیزہ مارا تو وہ گر کر شہید ہو گئے۔ ابن ماکولا(3) کہتے ہیں کہ واقدی نے ان کی یہی کنیت بیان کی ہے جبکہ دوسروں نے ابو ہبیرہ لکھی ہے۔ میں کہتا ہوں: جس کا ذکر نہیں وہ ابن اسحاق ہیں۔ ابو عمر کہتے ہیں: واقدی نے اُحد میں شہید ہونے والوں میں ان کا تذکرہ کیا ہے۔ اور ان کے متعلق کہا ہے کہ وہی ابو ہبیرہ ہیں اور کبھی انہیں ابوالسیرۃ کہا۔ فرماتے ہیں: بعض کا قول ہے کہ ابوالسیرۃ کہنا واقدی کی غلطی ہے، وہ تو ابو ہبیرہ ہیں۔ موسیٰ بن عقبہ کے ہاں ابوالسیرۃ لکھا ہے اور ابن القداح نے ان کی موافقت کی کہ وہ ابن الحارث بن علقمہ ہیں، خالد بن الیاس کہتے ہیں: ابو ہبیرہ کا نام حارث بن علقمہ ہے۔ ابن عائذ نے ان کی کنیت ابوسیرۃ لکھی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۸۱) الاستيعاب (۲۸۸۶) تجرید (۱۴۸/۲)\n(2) المغازی (۲۵۳، ۲۵۴)\n(3) الاکمال (۳۹/۱)"}],[8134,"§۹۵۲۳ ۔ ابوالاشعث(1)\nابن الاثیر(2) نے بحوالہ ابن الدباغ ان کا تذکرہ کیا ہے، ایسا ہی ابن فتحون نے ان کا استدراک کیا ہے جسے بزار کی طرف منسوب کیا ہے۔ \"تجرید\" میں ذہبی(3) نے بزار سے یونہی ذکر کیا ہے۔ مسند بزار میں کنیت کے لفظ سے مرقوم نہیں، اس میں سلیمان بن عبد اللہ کی سند سے بحوالہ محمد بن اشعث بن قیس، ان کے والد، ان کے دادا سے روایت ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تیل محتاجی کو ختم کرتا، کپڑا بے نیازی کو ظاہر کرتا اور خادم سے نیکی و احسان دشمن کو ہلاک کرتا ہے۔\"(4) اس کی سند میں غیر معروف راوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۸۲) تجرید (۱۴۸/۲)\n(2) اسد الغابہ (۳۷۳/۴)\n(3) التجرید (۱۴۸/۲)\n(4) کنز العمال (۱۷۲۱۱) مجمع الزوائد (۱۳۲/۵) جامع المسانید (۳۷/۱۳) اسد الغابہ (۳۷۳/۴) کشف الاسرار (۳۹۶۵)"}],[8135,"§۹۵۲۴ ۔ ابوالاعور\nسعید بن زید بن عمرو بن نفیل العددی، یکے از عشرہ مبشرہ، پہلے تذکرہ ہو چکا ہے۔"],[8136,"§۹۵۲۵ ۔ ابوالاعور بن ظالم(1)\nبن عبس بن حرام بن جندب بن عامر بن تمیم بن عدی بن النجار انصاری خزرجی۔ بدر و اُحد میں شریک رہے۔ ابن اسحاق(2) نے ان کا نام کعب بن حارث بتایا ہے جبکہ عدوی نے کہا: ان کا نام حارث بن ظالم ہے اور موسیٰ بن عقبہ کہتے ہیں: ابوالاعور بن حارث۔","",{"fn":"(1) اسد الغابہ (۵۶۸۳) تجرید (۱۴۸/۲)\n(2) السیرۃ النبویۃ (۲۶۳/۲)"}],[8137,"§۹۵۲۶ ۔ ابوالاعور السلمی\nعمرو بن سفیان، پہلے ذکر ہو چکا۔ ابو حاتم نے کہا: یہ صحابی نہیں ہیں۔"],[8138,"§۹۵۲۷ ۔ ابوالاعور الجرمی(1)\nابن ابی عیشہ نے ان کا ذکر کیا ہے اور سعید بن منان کی سند سے بحوالہ ابو زاہر، جبير سے روایت نقل کی ہے کہ قبیلہ جرم کا ایک شخص جسے ابوالاعور کہا جاتا تھا وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگا: السلام علیک یا رسول اللہ! آپ صلی اللہ علیہ وسلم نے فرمایا: وعلیک السلام ورحمۃ اللہ، ابوالاعور کیسے ہو؟(2) ابن مندہ نے اسی سند سے نقل کی ہے اور بغوی نے ابو عیشہ سے روایت کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۴) تجرید (۱۴۸/۲) الاستيعاب (۲۸۸۸)\n(2) جامع المسانید (۳۹/۱۳) اسد الغابہ (۳۷۴/۴)"}],[8139,"§۹۵۲۸ ۔ ابوامامہ اسعد بن زرارہ انصاری(1)\nخزرجی، نقیبوں میں سے ایک ہیں پہلے تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۷) الاستيعاب (۲۸۹۲) تجرید (۱۴۹/۲)"}],[8140,"§۹۵۲۹ ۔ ابوامامہ بن ثعلبہ الانصاری(1)\nثم الحارثی، اکثر کے ہاں ان کا نام \"ایاس\" ہے، بعض نے عبد اللہ بھی کہا ہے۔ اسی پر احمد بن حنبل رحمہ اللہ نے اعتماد کیا ہے۔ بعض نے ثعلبہ بن سہیل، تو بعض نے ابن عبد الرحمن بتایا ہے ابو عمر کہتے ہیں: ان کا نام ایاس تھا۔ کسی نے ثعلبہ، تو کسی نے سہیل کہا۔ جبکہ ایاس کے سوا کوئی نام صحیح نہیں۔ یہ ابو بردہ بن نیار کے بھانجے لگتے ہیں۔ نبی صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں جن میں سے چند امام مسلم اور اصحاب السنن نے درج کی ہیں۔ ان سے ان کے بیٹے عبد اللہ، عبد اللہ بن عطیہ بن عبد اللہ بن انیس انھیں بھی روایت کرتے ہیں۔ ابواحمد حاکم نے کہا: وہ نبی صلی اللہ علیہ وسلم کے ساتھ جہاد کے لیے نکلے تو آپ نے انہیں ان کی والدہ کی بیماری کی وجہ سے واپس کر دیا۔ جب واپس آئے تو وہ وفات پا چکی تھیں۔ ان کا جنازہ پڑھا۔ پھر یہی روایت عبد اللہ بن سنیب کی سند سے بحوالہ ان کے دادا عبد اللہ بن ابی امامہ بن ثعلبہ نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۹) تجرید (۱۴۸/۲)"}],[8141,"§۹۵۳۰ ۔ ابوامامہ الباہلی\nان کا نام صدی بن عجلان ہے، پہلے ذکر ہو چکا ہے۔"],[8142,"§۹۵۳۱ ۔ ابوامامہ بن سہل انصاری(1)\nثم البیاضی۔ واقدی کہتے ہیں: یہ صحابی ہیں۔ خلیفہ اور بغوی نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور محمد بن اسحاق کی سند سے بحوالہ محمد بن مالک، وہ اپنے بھائی عبد اللہ بن کعب سے وہ ابوامامہ بن سہل سے جو بنی بیاضہ کے فرد ہیں، روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو شخص اپنی قسم سے کسی مسلمان کا حق مارتا ہے، اللہ تعالیٰ اس پر جنت (کا اولین داخلہ) حرام کر دیتا ہے اور جہنم (میں بطور سزا جانا) اس کے لیے واجب کر دیتا ہے۔(2) اس کی سند مضبوط ہے۔ البتہ مسلم اور بغوی نے اسے علاء بن عبد الرحمن کی سند سے بحوالہ معبد بھی اور انہوں نے اپنے بھائی سے روایت کیا ہے، فرماتے ہیں: ابوامامہ بن ثعلبہ سے مروی ہے، جو محفوظ سند ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۵) الاستيعاب (۲۸۹۳)\n(2) مسلم کتاب الایمان باب وعید من اقتطع حق ... (۳۵۱) ابن ماجہ کتاب الاحتکام باب من خلف علی یمین فاجرۃ (۲۳۲۴)"}],[8143,"§۹۵۳۲ ۔ ابوامامہ انصاری(1)(2)\nبے نسبت، بے نام۔ ابن مندہ نے ان میں اور باہلی میں فرق کیا ہے اور کہا: عثمان بن عوف نے بحوالہ جریری، ابوالنضرہ سے وہ ابو سعید سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے وہاں آپ انصار کے ایک شخص سے ملے جسے ابوامامہ کہا جاتا تھا۔۔۔۔ پھر وہ حدیث ذکر کی۔ ابوداؤد نے یہ روایت اسی سند سے روایت کی ہے جس میں کہا آپ نے نماز کے وقت کے علاوہ ایک انصاری شخص کو بیٹھے دیکھا وہ عرض کرنے لگا: یا رسول اللہ! مجھے پریشانیوں اور قرضوں نے گھیرا ہوا ہے۔ آپ نے فرمایا: \"کیا میں تجھے ایسا قول نہ بتاؤں جسے تو کہے تو اللہ تعالیٰ تیرا قرض ادا کر دے؟\" میں نے عرض کیا: یا رسول اللہ! کیوں نہیں۔۔۔۔۔ پھر وہ حدیث ذکر کی۔ اس کے آخر میں ہے کہ میں نے وہ کلمات کہے تو اللہ تعالیٰ نے میرا قرض ادا کر دیا۔ شروع سے حدیث کے سیاق سے یہ ظاہر ہوتا ہے کہ وہ ابو سعید خدری کی حدیث ہے اور آخر سے لگتا ہے کہ انہی ابوامامہ کی روایت ہے۔ تہذیب اور اطراف میں مزنی(3) نے ان کے سوانح چھوڑ دیے جس پر میں نے ان دونوں کتابوں میں ان کی اس کمی کو دور کیا ہے۔ اور الکنیٰ میں ابواحمد حاکم بھی ان سے غافل رہے۔ ہو سکتا ہے یہ ابوامامہ بن ثعلبہ حارثی ہوں، لیکن ابن مندہ نے انہیں علیحدہ ذکر کیا ہے اور ابو نعیم نے بھی ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۷) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الصلاۃ باب فی الاستعاذۃ (۱۵۵۵)\n(3) تہذیب التہذیب (۱۴/۱۲)"}],[8144,"§۹۵۳۳ ۔ ابوامیہ (تمیرے) الجشمی (جیم کے پیش اور شین کے زبر سے)(1)\nابو عمر کہتے ہیں: صحابہ رضی اللہ عنہم کے بعض مؤلفین نے انہیں ذکر کیا ہے اور لیث کی سند سے بحوالہ معاویہ بن صالح، عصام بن یحییٰ سے بحوالہ ان کے روزوں کے متعلق ایک حدیث روایت کی ہے، جو انس بن مالک قشیری کعبی کی حدیث جیسی ہے کہ \"اللہ تعالیٰ نے مسافر سے روزے اور آدھی نماز کو ساقط کر دیا ہے۔\"(2) فرماتے ہیں: حدیث مضطرب ہے۔ انہیں ابوامیہ اور ابو تمیمہ بھی کہا گیا ہے، جو صحیح نہیں۔ میں کہتا ہوں: ابن ابی خیثمہ نے بحوالہ قتیبہ، لیث سے اسی سند سے ذکر کیا ہے۔ لیکن عصام اور صحابی کے درمیان سے دو آدمی ساقط ہو گئے۔ ابن مندہ نے ان کا عنوان ابوامیہ ضمری دیا اور حدیث لیث کی سند سے بیان کر کے ان دونوں حضرات کا ذکر کیا ہے۔ وہ ابو قلابہ الجرمی عبد اللہ بن زیاد سے روایت کرتے ہیں۔ لیکن انہوں نے \"ابوامیہ بن جعدہ کے بھائی سے مروی ہے\" کہا۔ پھر دوسری سند قتیبہ کی روایت جیسی نقل کی لیکن اس میں بھی ابوامیہ کہا، ایسا ہی طبرانی نے یہ روایت مسند شامیین میں معاویہ بن صالح کے سوانح میں، دولابی نے الکنیٰ میں عبد اللہ بن صالح بحوالہ معاویہ نقل کی لیکن انہوں نے \"عن ابی امیہ جعدی\" کہا۔ ایسا ہی بغوی نے انس بن مالک قشیری کی سوانح میں ابراہیم بن حانی بحوالہ عبد اللہ بن صالح ان کا علیحدہ ذکر کیا ہے، گویا ان کے نزدیک وہ وہی ہیں، جو جعدی نہیں۔ بعض نے عمرو بن امیہ ضمری کے سوانح میں ذکر کیا ہے کہ ان کی کنیت بھی ابوامیہ ہے تو جس نے ضمری کہا اس کی مراد یہ ہیں اور جس نے قشیری کہا اس کی مراد انس بن مالک ہیں جو کعبی ہیں۔ اس لیے جن کی طرف قشیری لوگ منسوب ہوتے ہیں وہ قشیر بن کعب بن ربیعہ بن عامر بن صعصعہ ہیں اور جس نے جعدی کہا تو انہیں ان کے چچا کی طرف منسوب کر دیا کیونکہ جعدہ، ابن کعب ہیں جو قشیر بن کعب کے بھائی ہیں۔ جہاں تک ضمری کا تعلق ہے تو وہ ان کے ساتھ صرف مضر بن نزار بن معد بن عدنان سے ملتے ہیں جو قشیر یوں اور جعد یوں کے دادا ہیں۔ وہ معاویہ بن بکر بن ہوازن بن منصور بن عکرمہ بن حفصہ بن قیس غیلان بن مضر ہیں اور ضمرہ بن بکر بن عبد مناف بن کنانہ بن خزیمہ بن مدرکہ بن الیاس بن مضر ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۱) تجرید (۱۴۹/۲)\n(2) نسائی کتاب الصیام باب ذکر وضع الصیام عن المسافر والاختلاف علی الاوزاعی فی خبر عمرو بن امیہ (۲۲۶۷، ۲۲۶۸) المعجم الکبیر (۹۰۶/۲۲، ۹۰۷) اسد الغابہ (۳۷۶/۴)"}],[8145,"§۹۵۳۴ ۔ ابوامیہ دوسی ثم زہرانی\nبعض ازدی پھر صقعی (صاد پر زبر قاف ساکن پھر با ہے) کہتے ہیں۔ صقب بن دھمان بن نضر بن حارث کی طرف نسبت ہے جو ام قافہ بنت ابی قافہ، صدیق اکبر رضی اللہ عنہ کی بہن کے، اشعث سے پہلے والے شوہر ہیں۔ ان کی ان سے ایک بیٹی تھی جس کا نام امیمہ تھا جس سے عبد اللہ بن زبیر رضی اللہ عنہ نے نکاح کیا تھا۔ یہ بات ابن کلبی اور ابن درید نے ذکر کی ہے۔ اس بنا پر وہ اس قسم سے ہوئے۔ اس لیے کہ سیرت شامیہ میں ہے: ام قافہ فتح مکہ کے موقع پر مکن تھیں۔ اس واسطے ان کے والد ان کی شادی کسی مسلمان سے ہی کریں گے اور جو صدیق اکبر کے سسرالی رشتہ دار ہوں گے وہ ضرور نبی صلی اللہ علیہ وسلم سے ملے ہوں گے۔"],[8146,"§۹۵۳۵ ۔ ابوامیہ(1)\nوہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، جب لوٹنے لگے، فرمایا: دوپہر کے کھانے کا انتظار نہیں کرتے ہو؟ ابن ابی حاتم کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے مسافر سے روزہ اور آدھی نماز معاف کر دی ہے۔(2) اسے بغوی نے نقل کیا ہے، فرماتے ہیں بعض لوگ کہتے ہیں: وہ عمرو بن امیہ ضمری ہیں اور بعض کا قول ہے: ابوامیہ ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۶) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الصوم باب اختیار الصوم (۲۴۰۸) بنحوہ، ترمذی کتاب الصیام باب ما جاء فی الرخصۃ فی الافطار (۷۱۱) نسائی کتاب الصوم باب وضع الصیام عن الحبلی والمرضع (۲۳۱۴) ابن ماجہ کتاب الصیام باب ما جاء فی الافطار للحامل والمرضع (۱۶۶۷) مسند احمد (۳۴۷/۴) (۲۹/۵)"}],[8147,"§۹۵۳۶ ۔ ابوامیہ ازدی(1)\nجنادہ کے والد، امام بخاری(2) اور ابو حاتم(3) فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ میں نے جنادہ کے سوانح میں وضاحت کر دی ہے کہ ان کے والد کا نام مالک ہے اور جس نے ان کا نام کثیر بتایا اس نے انہیں دوسرے سے ملا دیا ہے۔ جن لوگوں نے ان کے \"مالک\" نام پر بھروسا کیا ہے ان میں سے خلیفہ بن خیاط ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۲) تجرید (۱۴۹/۲)\n(2) التاریخ الکبیر (۶/۲)\n(3) الجرح والتعدیل (۵۱۵/۱)"}],[8148,"§۹۵۳۷ ۔ ابوامیہ بن عمرو\nبن وہب بن معتب ثقفی۔ عمرو بن امیہ بن وہب میں ان کی تحقیق گزر چکی ہے۔"],[8149,"§۹۵۳۸ ۔ ابوامیہ جمحی\nصفوان بن امیہ بن خلف تذکرہ ہو گیا۔"],[8150,"§۹۵۳۹ ۔ ابوامیہ\nوہ عمیر بن وہب ہیں، پہلے تذکرہ ہو چکا ہے۔"],[8151,"§۹۵۴۰ ۔ ابوامیہ الجمحی (یہ دوسرے ہیں)(1)\nابو عمر کہتے ہیں: بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جبکہ اس میں تامل ہے، روایت کرتے ہیں: کسی نے رسول اللہ صلی اللہ علیہ وسلم سے قیامت کے متعلق پوچھا، آپ نے فرمایا: \"اس کی ایک نشانی یہ ہے کہ (بڑے لوگ علم سے محروم ہوں گے تو پھر) چھوٹوں سے علم حاصل کیا جائے گا۔\" ابو موسیٰ(2) کہتے ہیں: ابو مسعود نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور کہا کہ ان سے بکر بن سوادہ روایت کرتے ہیں، پھر وہ حدیث ذکر کی۔ لیکن اس کی سند بیان نہیں کی۔ جو طبرانی کے ہاں ابن لہیعہ کی سند سے بحوالہ بکر اسی مفہوم میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۴) تجرید (۱۴۹/۲)\n(2) المعجم الکبیر (۹۰۸/۲۲) مجمع الزوائد (۱۳۵/۱) جامع المسانید (۲۳۹/۱۳)"}],[8152,"§۹۵۴۱ ۔ ابوامیہ الجمحی (دوسرے ہیں)\nان کا بیان ابو غلیظ، غین نقطے والی میں آئے گا۔"],[8153,"§۹۵۴۲ ۔ ابوامیہ الجعدی\nابوامیہ ذکر ہو چکا ہے، ایسا ہی الجعثی کا بھی تذکرہ گزر چکا ہے۔"],[8154,"§۹۵۴۳ ۔ ابوامیہ الضمری(1)\nعمرو بن امیہ ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۰۳) الاستيعاب (۲۸۹۷)"}],[8155,"§۹۵۴۴ ۔ ابوامیہ الفزاری(1)\nجن کا ذکر ابو امیہ پہلے حرف الف میں ہوا ہے۔","",{"fn":"(1) الاستيعاب (۲۸۹۴)"}],[8156,"§۹۵۴۵ ۔ ابوامیہ القشیری والکعبی\nتذکرہ ہو چکا۔"],[8157,"§۹۵۴۶ ۔ ابوامیہ المخزومی(1)\nبقول ابن اسکن: ان کا شمار اہل مدینہ میں ہے۔ پھر اسحاق بن عبد اللہ بن ابی طلحہ کی سند سے بحوالہ ابو المنذر مولائے ابوذر غفاری، ابوامیہ مخزومی کی ان حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا جس نے اپنے قصور کا اعتراف کیا لیکن اس کے پاس سامان نہ ملا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے خیال میں تم نے چوری نہیں کی۔\"(2) اس نے کہا: کیوں نہیں۔ اس سے پھر پوچھا۔۔۔۔ الحدیث ابوداؤد، نسائی، ابن ماجہ اور داری نے اسی سند سے نقل کی ہے۔ ابوداؤد نے روایت کی کہ ہشام کی روایت میں اسحاق بن ابی المنذر بحوالہ ابوامیہ۔ انصار(3) کے ایک شخص۔ لکھا ہے۔ جبکہ پہلی سند زیادہ مشہور ہے ابن اسکن فرماتے ہیں: اس میں حماد اسحاق سے روایت کرنے میں منفرد ہیں۔ میں کہتا ہوں: جس روایت کی طرف ابوداؤد نے اشارہ کی ہے۔ ہشام کی روایت اس کی تردید کرتی ہے۔ جبکہ دولابی نے اپنی سند سے اسے موصول کہا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۷) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الحدود باب فی التلقین فی الحد (۴۳۸۰) نسائی کتاب قطع السارق باب تلقین السارق (۴۸۷۷) ابن ماجہ کتاب الحدود باب تلقین السارق (۵۶۹۷) مسند احمد (۲۹۳/۵)\n(3) جامع المسانید والسنن (۲۳۸/۱۳)"}],[8158,"§۹۵۴۷ ۔ ابواناس بن زنیم اللیثی یا دولی(1)\nساریہ بن زنیم کے بھتیجے۔ ابو عمر نے ان کا ذکر کیا کہ وہ شاعر تھے اور ان کے شرفاء سے تعلق رکھتے تھے وہی اپنے قصیدہ میں کہتے ہیں: فما حملت من ناقۃ فوق رحلہا ابر و اوفی ذمۃ من محمد(2) فرماتے ہیں: ان کا ایک بیٹا انس بن ابی اناس تھا جسے الحکم بن عمرو نے اپنی وفات(3) کے وقت خراسان کا خلیفہ مقرر کیا تھا۔ میں کہتا ہوں: اناس ھمزہ کے پیش اور نون بغیر شد کے ہے۔ مذکورہ قصیدہ کس نے کہا ہے اس میں اختلاف ہے۔ بعض کا قول ہے کہ یہی ہیں بعض انس بن زنیم، بعض ساریہ بعض اسید بن ابی اناس کہتے ہیں۔ اسی قصیدہ کو ابن اسحاق نے ایمن بن زنیم کی طرف منسوب کر کے پڑھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۸) تجرید (۱۴۹/۲)\n(2) اسد الغابہ (۳۷۹/۴)\n(3) اسد الغابہ (۳۷۹/۴)"}],[8159,"§۹۵۴۸ ۔ ابواہاب بن عزیز(1)\nبن قیس ابن سوید بن ربیعہ بن زید بن عبد اللہ بن دارم تمیمی داری، بنی نوفل بن عبد مناف کے حلیف ان کے والد العزیز (عین کے زبر اور دو زاؤں سے) مکہ آئے اور ان سے معاہدہ کیا ہے اور ان کے ہاں سے شادی کی۔ چنانچہ ان کی بہن عمرو بن نوفل کی بیٹی ہے ان کے ہاں ابواہاب پیدا ہوئے پھر عقبہ بن عامر کی بیٹی ام یحییٰ سے شادی کی، جو ابواہاب کی بیٹی تھی، اتنے میں ایک سیاہ فام لونڈی آ کر کہنے لگی: میں نے تم دونوں کو دودھ پلایا ہے۔ حدیث جو صحیح میں مذکور ہے۔ جعفر المستغفری نے ان کا صحابہ میں ذکر کیا ہے اور کہا کہ ان سے ایک حدیث روایت کی جاتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ٹیک لگا کر کھانے سے منع فرمایا ہے،(2) فاکہی نے کتاب مکہ میں سفیان کی سند سے نقل کیا ہے کہ انہوں نے کسی شخص سے سنا کہ ابواہاب جن کا ابھی ذکر ہوا ہے پہلے شخص ہیں جب ان کی وفات ہوئی تو مسجد حرام میں ان کا جنازہ پڑھا گیا۔","",{"fn":"(1) اسد الغابہ (۵۷۰۰) تجرید (۱۵۰/۲)\n(2) مجمع الزوائد (۲۵/۵) اسد الغابہ (۳۷۹/۴)"}],[8160,"§۹۵۴۹ ۔ ابواوس الثقفی(1)\nحذیفہ بن اوس، تذکرہ ہو چکا ہے۔","",{"fn":"(1) مسند بزار (۲۸۷۰) اسد الغابہ (۵۷۰۹)"}],[8161,"§۹۵۵۰ ۔ ابواوس(1)\nجابر بن طارق ابن ابی طارق الاحمسی، طارق کے والد، انہیں جابر بن عوف بھی کہا جاتا ہے جو ان کے دادا کی طرف نسبت ہے۔ اس واسطے کہ ابو طارق کا نام عوف ہے اسماء میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۰)"}],[8162,"§۹۵۵۱ ۔ ابواوفی الاسلمی(1)\nعبد اللہ کے والد، ان کا نام علقمہ ہے، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۱) الاستيعاب (۲۹۰۲)"}],[8163,"§۹۵۵۲ ۔ ابوایاس الساعدی(1)\nطبری نے ان کا ذکر تو کیا ہے لیکن ان کی کوئی روایت نقل نہیں کی جبکہ مستغفری نے ان کا ذکر کیا اور عبد العزیز بن ابان، بحوالہ صالح بن حسان، سعید بن المسیب ابوایاس الساعدی سے اپنی سند سے نقل کیا، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ سوار تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: کہو! میں نے عرض کیا: کیا؟ فرمایا: کہو وہ اللہ ایک ہے۔ پھر فرمایا: کہو! \"کہو میں پناہ طلب کرتا ہوں صبح کے رب کی۔ کہو میں پناہ مانگتا ہوں لوگوں کے رب کی۔\" اس کے بعد ارشاد فرمایا: \"اے ایاس! لوگوں نے ان جیسا کلام نہیں پڑھا۔\"(2) ایسا ہی حارث بن ابی اسامہ نے بحوالہ عبد العزیز بن ابان نقل کیا ہے اور عبد العزیز متروک راوی ہے۔ ابن ابی عاصم(3) نے اسے وحدان میں ذکر کیا کہ ابوایاس بن سہل بنی ساعدہ سے ہیں، پھر ابو شیبہ سے بحوالہ مصعب بن مقدام، محمد بن ابراہیم، ابو حازم سے روایت نقل کی کہ وہ ابن ابی ایاس بن سہل انصاری کے پاس بیٹھے۔ پھر وہ کہنے لگے: ذرا دھیان کرو میں متوجہ ہو گیا، کہنے لگے: کیا میں تمہیں اپنے والد کی نبی صلی اللہ علیہ وسلم سے کوئی روایت نہ سناؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"سورج طلوع ہونے تک نماز پڑھنا مجھے اللہ تعالٰی کی راہ میں عمدہ گھوڑے باندھنے سے زیادہ محبوب ہے۔” (حدیث)(4) یونہی فرمایا: میرے خیال میں یہ پہلے کے علاوہ ہیں یقیناً ان کا نام سہل ہے انہیں ابو ایاس اس وجہ سے کہا جاتا ہے کہ ان کے بیٹے کا نام ایاس تھا۔","",{"fn":"(1) اسد الغابہ (۵۷۰۵) تجرید (۱۵۰/۲)\n(2) ترمذی کتاب الدعوات باب فی انتظار الفرج وغیر ذلک (۳۵۷۵) نسائی کتاب الاستعاذۃ باب (۱) حدیث (۵۴۴۴) مسند احمد (۱۵۳/۴)\n(3) الاحاد والمثانی (۲۱۶/۴)\n(4) مجمع الزوائد (۱۶۹۴۶) المعجم الکبیر (۵۷۶۱)"}],[8164,"§۹۵۵۳ ۔ ابو ایاس اللیثی\nابن عساکر نے اپنی تاریخ کے حرف الف اور آخری حرف یاء میں ان کا ذکر کیا ہے۔ فرماتے ہیں: بعض لوگوں کا کہنا ہے: وہ صحابی ہیں۔ سیدنا عمر رضی اللہ عنہ کے خطبہ جابیہ میں شریک تھے۔ پھر عبید اللہ بن ابی زیاد کی سند سے بحوالہ زہری، عبید اللہ بن عبداللہ بن عتبہ، ابو ایاس لیثی ثم الاجہی، صحابی رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ ایک دفعہ وہ جابیہ میں سیدنا عمر رضی اللہ عنہ کی آمد کے وقت ان کے پاس تھے کہ آپ کے پاس ایک شخص آ کر کہنے لگا: میری بیوی نے زنا کر لیا ہے، پھر وہ قصہ ذکر کیا۔ ابن عساکر فرماتے ہیں: ان کے علاوہ کسی کا قول ہے: “ابو زائدہ لیثی سے مروی ہے یہی درست ہے۔” میں کہتا ہوں: اس کا احتمال ہے، ہو سکتا ہے یہ وہ ابو اناس ہوں جن کا تذکرہ پہلے نون سے ہو چکا ہے۔"],[8165,"§۹۵۵۴ ۔ ابو ایمن الانصاری(1)\nعمرو بن الجموح کے غلام، ابن اسحاق(2) نے شہدائے اُحد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۰۶) تجرید (۱۵۰/۲)\n(2) السیرۃ النبویۃ عن ابن اسحاق (۹۸/۳)"}],[8166,"§۹۵۵۵ ۔ ابو ایوب انصاری(1)\nخالد بن زید بن کلیب، کنیت سے مشہور ہیں، ان کا نام پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۴) الاستیعاب (۲۹/۵)"}],[8167,"§۹۵۵۶ ۔ ابو ایوب\nجاریہ بن قدامہ تمیمی۔ ناموں میں تذکرہ ہو گیا۔ نام سے زیادہ مشہور ہیں۔"],[8168,"§۹۵۵۷ ۔ ابو ایوب الیمامی(1)\nمستغفری نے ان کا ذکر کیا ہے اور خلیفہ نے نقل کیا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ہے۔","",{"fn":"(1) تجرید (۱۵۰/۲)"}],[8169,"§۹۵۵۸ ۔ ابو ایوب (دوسرے)\nعثمانی نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور عاصم بن علی کی سند سے بحوالہ ان کے والد عبداللہ بن عثمان بن خیثم سے وہ اپنے دادا ابو ایوب سے روایت کرتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: مجھے مختصر سی نصیحت کریں۔ ابن فتحون نے ان کا ذکر کیا ہے۔"],[8170,"§۹۵۵۹ ۔ ابو ایوب الازدی\nان شاء اللہ تعالیٰ ان کا تذکرہ چوتھی قسم میں آئے گا۔"],[8171,"§۹۵۶۰ ۔ ابو ایوب المالکی\nسیف نے فتوح میں ذکر کیا ہے کہ سیدنا عمرو بن العاص نے انہیں رومیوں کی جنگ میں لشکر کا امیر بنایا تھا۔ طبری نے اپنی مسند سے ان کا ذکر کیا اور ابن فتحون نے ان کا استدراک کیا ہے۔"],[8172,"§۹۵۶۱ ۔ ابو ادریس الخولانی(1)\nعائد اللہ بن عبید اللہ تذکرہ پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۲) الاستیعاب (۲۸۷۴)"}],[8173,"§۹۵۶۲ ۔ ابو اسحاق\nقبیصہ بن ذویب خزاعی، ان کا ذکر بھی ہو گیا ہے۔"],[8174,"§۹۵۶۳ ۔ ابو اسحاق(1)\nابراہیم بن عبدالرحمن بن عوف زہری، تذکرہ ہو گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۹)"}],[8175,"§۹۵۶۴ ۔ ابو امامہ بن سہل(1)\nمحمد بن حنیف انصاری ان کا نام اسعد ہے، پہلے تذکرہ گزر گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۷)"}],[8176,"§۹۵۶۵ ۔ ابو امیہ بن الاخنس\nبن شہاب ابن شریق ثقفی، ان کے والد کے صحابی ہونے میں اختلاف ہے۔ وہ سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ ثوری نے کہا: عمرو بن عبد الرحمن سہمی سے بحوالہ ابو سلمہ بن سفیان مخزومی، ابو امیہ بن اخنس ثقفی سے روایت ہے۔ فرمایا: میں عمر رضی اللہ عنہ کے پاس تھا۔ آپ کے پاس ایک شخص آ کر کہنے لگا: میرا بیٹا اتنا زخمی کیا گیا کہ اس کی ہڈی نظر آنے لگی۔"],[8177,"§۹۵۶۶ ۔ ابو اسحاق\nکعب بن مانع، جو کعب احبار سے مشہور ہیں۔ ناموں میں تذکرہ گزر چکا ہے۔"],[8178,"§۹۵۶۷ ۔ ابو الاسود\nیزید بن الاسود الجرشی، تذکرہ ہو چکا ہے۔"]])